window.BANQUE_INFINI = {"module":"annee-2/theorique/semestre-1/cardio-respi","titre":"Cardio-respiratoire","sources":[{"t":"Système de transport de l'oxygène","q":"cours-01-transport-oxygene/quiz.html","f":"cours-01-transport-oxygene/fiche.html"},{"t":"Examen subjectif","q":"cours-02-examen-subjectif/quiz.html","f":"cours-02-examen-subjectif/fiche.html"},{"t":"Imagerie du thorax","q":"cours-03-imagerie-thorax/quiz.html","f":"cours-03-imagerie-thorax/fiche.html"},{"t":"Radiographie dans la pathologie pulmonaire","q":"cours-04-rx-pathologie-respiratoire/quiz.html","f":"cours-04-rx-pathologie-respiratoire/fiche.html"},{"t":"Gazométrie artérielle","q":"cours-05-gazometrie/quiz.html","f":"cours-05-gazometrie/fiche.html"},{"t":"Épreuve fonctionnelle respiratoire","q":"cours-06-epreuve-fonctionnelle-respiratoire/quiz.html","f":"cours-06-epreuve-fonctionnelle-respiratoire/fiche.html"},{"t":"Aspiration des sécrétions chez l'adulte","q":"cours-07-aspiration/quiz.html","f":"cours-07-aspiration/fiche.html"},{"t":"Électrocardiogramme","q":"cours-08-ecg/quiz.html","f":"cours-08-ecg/fiche.html"},{"t":"Réadaptation cardiovasculaire","q":"cours-09-readaptation-cardiovasculaire/quiz.html","f":"cours-09-readaptation-cardiovasculaire/fiche.html"},{"t":"Ventilation mécanique","q":"cours-10-ventilation-mecanique/quiz.html","f":"cours-10-ventilation-mecanique/fiche.html"},{"t":"Kinésithérapie chez le patient critique","q":"cours-11-patient-critique/quiz.html","f":"cours-11-patient-critique/fiche.html"},{"t":"Kinésithérapie respiratoire en pédiatrie","q":"cours-12-pediatrie/quiz.html","f":"cours-12-pediatrie/fiche.html"}],"questions":[{"q":"Quelle est la composition de l'air atmosphérique en oxygène ?","o":["Environ 21 %","Environ 79 %","Environ 0,03 %","Environ 50 %"],"r":0,"e":"79 % d'azote, 20,97 % d'O₂ et 0,03 % de CO₂. Exactement 20,97 %.","s":0},{"q":"Quel gaz représente 79 % de l'air atmosphérique ?","o":["L'azote","L'oxygène","Le CO₂","La vapeur d'eau"],"r":0,"e":"L'azote constitue 79 % de l'air atmosphérique.","s":0},{"q":"Quelle structure ne fait PAS partie de la zone conductrice ?","o":["Les alvéoles","La trachée","Le larynx","Les bronchioles"],"r":0,"e":"Zone conductrice : nez, pharynx, larynx, trachée, bronches et bronchioles. Zone respiratoire : bronchioles respiratoires, conduits alvéolaires et alvéoles.","s":0},{"q":"Quelles sont les trois fonctions du nez sur l'air inspiré ?","o":["Filtrer, humidifier et réchauffer","Filtrer, refroidir et comprimer","Humidifier, oxygéner et filtrer","Réchauffer, assécher et filtrer"],"r":0,"e":"Le nez filtre, humidifie et réchauffe l'air.","s":0},{"q":"Quel cartilage est le seul anneau complet autour de la trachée ?","o":["Le cricoïde","La thyroïde","L'épiglotte","L'aryténoïde"],"r":0,"e":"Le cricoïde, cartilage le plus caudal, protège la trachée de la compression dynamique lors d'une inspiration ou expiration forcée.","s":0},{"q":"Quel est le rôle de l'épiglotte ?","o":["Agir comme une valve contre le passage des aliments dans la trachée","Produire le surfactant qui stabilise les alvéoles en fin d'expiration","Filtrer et réchauffer l'air inspiré avant les bronches","Assurer les échanges gazeux au niveau du larynx"],"r":0,"e":"L'épiglotte, dans le larynx, agit comme une valve.","s":0},{"q":"À quel niveau la trachée se divise-t-elle en bronches principales ?","o":["La carène","Le cricoïde","Le hile","L'angle de Louis"],"r":0,"e":"La trachée se divise au niveau de la carène en bronche principale droite et gauche.","s":0},{"q":"Pourquoi la bronche droite est-elle plus exposée au risque d'inhalation ?","o":["La bronche gauche se ramifie selon un angle plus aigu","La bronche droite est plus longue et plus horizontale que la gauche","La bronche droite est plus étroite et plus souvent encombrée","La carène est déviée vers la gauche chez la plupart des adultes"],"r":0,"e":"L'angle plus aigu de la bronche gauche prédispose la bronche droite à un risque plus élevé d'inhalation de matériel.","s":0},{"q":"Que devient la composition des parois en descendant dans l'arbre bronchique ?","o":["Moins de plaques cartilagineuses et plus de muscle lisse","Plus de plaques cartilagineuses et moins de muscle lisse","Plus de cils et plus de cartilage, jusqu'aux alvéoles","Aucune modification, de la trachée aux bronchioles"],"r":0,"e":"Les voies aériennes deviennent plus petites, avec progressivement moins de cartilage et plus de muscle lisse.","s":0},{"q":"Qu'est-ce qui marque la zone de transition ?","o":["L'apparition d'alvéoles dans les parois des bronchioles respiratoires","La disparition du cartilage dans la paroi des bronches segmentaires","L'apparition des cellules caliciformes dans l'épithélium bronchique","La division de la trachée en deux bronches souches, au niveau de la carène"],"r":0,"e":"La zone de transition correspond aux bronchioles respiratoires.","s":0},{"q":"Quel est le rôle des macrophages alvéolaires ?","o":["Ingérer les particules non filtrées, comme défense","Produire le surfactant, comme pneumocytes de type II","Assurer la diffusion de l'O₂, comme la membrane","Sécréter le mucus, comme les cellules caliciformes"],"r":0,"e":"On les trouve dans la zone respiratoire, où cils et muscle lisse ont disparu.","s":0},{"q":"Que signifie l'interdépendance alvéolaire ?","o":["Les alvéoles voisines partagent une paroi, et leur forme dépend des voisines","Les alvéoles se vident toutes en même temps, à chaque expiration complète","Chaque alvéole est isolée, avec sa propre paroi et sa propre bronchiole","Les alvéoles ont toutes la même taille, quelle que soit leur position"],"r":0,"e":"Forme et dimensions varient selon l'agencement des alvéoles adjacentes.","s":0},{"q":"Quel mouvement thoracique augmente le diamètre transverse ?","o":["L'anse de seau","Le bras de pompe","La rotation costale","L'ascension diaphragmatique"],"r":0,"e":"L'anse de seau pousse les côtes inférieures vers l'extérieur et vers le haut.","s":0},{"q":"Quels muscles assurent l'inspiration de repos ?","o":["Le diaphragme et les intercostaux externes","Les abdominaux et les intercostaux internes","Les scalènes et le SCM","Le grand pectoral"],"r":0,"e":"L'inspiration est un mouvement actif ; les muscles accessoires sont recrutés à l'effort ou en cas de pathologie.","s":0},{"q":"Que doivent vaincre les muscles respiratoires ?","o":["La rétraction élastique du poumon et du thorax, et la résistance des voies","La pression artérielle pulmonaire, dans les capillaires alvéolaires","La tension superficielle seule, à l'interface air-liquide des alvéoles","La pesanteur seule, qui tire le poumon vers les bases en position debout"],"r":0,"e":"C'est la définition de la mécanique de la respiration donnée dans le cours.","s":0},{"q":"Combien de temps le sang séjourne-t-il dans la membrane alvéolo-capillaire au repos ?","o":["0,75 seconde","0,25 seconde","2 secondes","0,1 seconde"],"r":0,"e":"Le sang séjourne 0,75 s au repos mais sature en environ 0,25 s.","s":0},{"q":"En combien de temps le sang sature-t-il en oxygène ?","o":["Environ 0,25 seconde","Environ 0,75 seconde","Environ 1 seconde","Environ 2 secondes"],"r":0,"e":"D'où une réserve importante de temps de contact au repos.","s":0},{"q":"Quel facteur ne conditionne PAS la diffusion de l'oxygène ?","o":["La fréquence cardiaque de repos","La surface de la membrane alvéolo-capillaire","Le rapport ventilation/perfusion","Le volume de sang capillaire pulmonaire"],"r":0,"e":"Les facteurs cités sont la surface, la capacité de diffusion, le volume capillaire, le rapport V/Q, le temps de séjour, l'hémoglobine et la PaO₂.","s":0},{"q":"De quoi dépend surtout la distribution de la perfusion pulmonaire ?","o":["De la pesanteur","De la fréquence","De la température","De la FiO₂"],"r":0,"e":"Les champs dépendants sont mieux perfusés que les non dépendants.","s":0},{"q":"En position debout, quelle région pulmonaire est la mieux perfusée ?","o":["Les bases","Les sommets","Les régions moyennes uniquement","La perfusion est homogène"],"r":0,"e":"Les champs dépendants — donc les bases en position debout — sont mieux perfusés.","s":0},{"q":"De quoi dépend l'optimisation du débit cardiaque ?","o":["De la synchronie entre excitation électrique et contraction mécanique","De la seule fréquence cardiaque, quel que soit le volume d'éjection","De la pression artérielle seule, systolique et diastolique","De la fraction inspirée d'oxygène et de la saturation artérielle"],"r":0,"e":"C'est l'énoncé de l'étape 6 du système de transport de l'oxygène.","s":0},{"q":"Par quoi est régulée l'extraction de l'O₂ par les cellules ?","o":["Par le besoin des cellules, selon la transformation de l'ADP en ATP","Par la quantité d'oxygène disponible, selon la saturation artérielle","Par la fréquence respiratoire, selon le volume courant","Par la pression artérielle, selon la PAM et le débit capillaire"],"r":0,"e":"L'extraction dépend du besoin métabolique et non de l'O₂ disponible.","s":0},{"q":"Quel est le taux habituel d'extraction tissulaire de l'oxygène ?","o":["23 %","50 %","75 %","5 %"],"r":0,"e":"Ce taux peut augmenter en périodes de plus grand besoin métabolique.","s":0},{"q":"Quel est le rôle de la myoglobine ?","o":["Faciliter le transfert d'O₂ dans la mitochondrie","Transporter le CO₂ dans le sang vers les poumons","Produire l'ATP directement, sans passer par la mitochondrie","Filtrer les particules alvéolaires, comme un macrophage"],"r":0,"e":"C'est une protéine semblable à l'hémoglobine, présente dans les mitochondries musculaires.","s":0},{"q":"Quelle proportion du poids corporel est constituée de fluides ?","o":["60 %","40 %","80 %","20 %"],"r":0,"e":"D'où l'importance des mécanismes de régulation des fluides pour la stabilité hémodynamique.","s":0},{"q":"Quelle est la principale cause de perte des mécanismes de régulation des fluides ?","o":["L'immobilité et l'alitement","La déshydratation aiguë","L'exercice intense et prolongé","Le stress émotionnel chronique"],"r":0,"e":"Ces mécanismes sont responsables de la stabilité hémodynamique ; la position debout restaure le stress gravitationnel.","s":0},{"q":"De combien le débit cardiaque peut-il augmenter à l'exercice ?","o":["Jusqu'à cinq fois","Jusqu'à deux fois","Jusqu'à dix fois","Il n'augmente pas"],"r":0,"e":"Toutes les étapes du système de transport de l'oxygène sont influencées par l'exercice.","s":0},{"q":"Quel est l'effet de l'exercice sur le rapport ventilation/perfusion ?","o":["Il est optimisé","Il se dégrade","Il reste inchangé","Il s'inverse"],"r":0,"e":"L'exercice augmente aussi la ventilation et l'extraction tissulaire d'oxygène.","s":0},{"q":"Quel système médie la réponse au stress émotionnel ?","o":["Le système nerveux sympathique","Le système nerveux parasympathique","Le système endocrinien seul","Le système lymphatique"],"r":0,"e":"La réponse « lutte ou fuite » est semblable à celle du stress de l'exercice.","s":0},{"q":"Quelle conséquence globale a la réponse « lutte ou fuite » ?","o":["Une consommation accrue d'O₂","Une diminution de la glycémie","Une bradycardie","Une baisse de la pression artérielle"],"r":0,"e":"Elle augmente FC, PA, CO₂, glycémie, force musculaire, vigilance et métabolisme cellulaire.","s":0},{"q":"Quelles sont les neuf étapes du système de transport de l'oxygène, dans l'ordre ?","o":["O₂ inspiré, voies aériennes, poumons et paroi","Diffusion, perfusion, fonction cardiaque","Circulation périphérique, extraction tissulaire","Retour veineux et du CO₂ aux poumons","Filtration rénale des bicarbonates"],"r":[0,1,2,3],"e":"Les neuf étapes s'enchaînent : air ambiant → voies aériennes → poumons et paroi thoracique → diffusion → perfusion → fonction cardiaque → circulation périphérique → extraction tissulaire → retour veineux.","s":0},{"q":"Quels facteurs influencent la qualité de l'air inspiré ?","o":["La zone géographique et la saison","Le milieu rural ou urbain","L'altitude","Les lieux fermés et le travail","Le groupe sanguin du patient"],"r":[0,1,2,3],"e":"Zone géographique, saisons, milieu rural/urbain, altitude, espaces fermés/ouverts et environnement professionnel. Il s'agit des espaces fermés ou ouverts et de l'environnement professionnel.","s":0},{"q":"Quelle est la proportion de CO₂ dans l'air atmosphérique ?","o":["0,03 %","0,3 %","3 %","21 %"],"r":0,"e":"79 % d'azote, 20,97 % d'O₂ et 0,03 % de CO₂.","s":0},{"q":"Que se passe-t-il dans le pharynx pendant la déglutition ?","o":["Les muscles squelettiques se contractent pour éviter l'inhalation","L'épiglotte se relève pour laisser passer l'air vers la trachée","Le cricoïde se referme pour bloquer le passage vers les poumons","Les cils accélèrent leur battement pour repousser les aliments"],"r":0,"e":"Dans le pharynx, les muscles squelettiques se contractent pendant la déglutition pour éviter l'inhalation.","s":0},{"q":"Contre quoi le cricoïde protège-t-il la trachée ?","o":["La compression dynamique d'une inspiration ou expiration forcée","L'inhalation de particules alimentaires pendant la déglutition","La sécheresse de l'air inspiré, par l'humidification du mucus","Les infections, par la production d'anticorps dans la muqueuse"],"r":0,"e":"Seul anneau cartilagineux complet et cartilage le plus caudal, le cricoïde protège la trachée de la compression dynamique lors d'une inspiration ou expiration forcée.","s":0},{"q":"Selon quel schéma les bronches principales se ramifient-elles ?","o":["Un schéma dichotomique irrégulier","Un schéma trichotomique régulier","Un schéma en étoile","Un schéma aléatoire"],"r":0,"e":"Après la carène, les bronches principales se ramifient selon un schéma dichotomique irrégulier.","s":0},{"q":"Quelles modifications histologiques observe-t-on dans la région des bronchioles ?","o":["Le cartilage diminue","Les cellules caliciformes diminuent","L'épithélium devient cuboïde cilié simple","Le muscle lisse disparaît totalement"],"r":[0,1,2],"e":"Cartilage et cellules caliciformes diminuent, l'épithélium pseudo-stratifié devient cuboïde simple cilié. Le muscle lisse, lui, augmente en proportion. L'épithélium pseudo-stratifié est remplacé par un épithélium cilié cuboïde simple.","s":0},{"q":"Qu'advient-il de la musculature lisse et des cils dans la zone respiratoire ?","o":["Le muscle lisse s'amincit, les cils disparaissent peu à peu","Le muscle lisse et les cils augmentent, pour mieux protéger","Le muscle lisse augmente, les cils persistent jusqu'aux alvéoles","Les cils se densifient, le muscle lisse reste inchangé"],"r":0,"e":"Dans la zone respiratoire, la musculature lisse s'amincit et les cils disparaissent progressivement.","s":0},{"q":"Comment se terminent les conduits alvéolaires ?","o":["Par des alvéoles simples et des sacs alvéolaires","Par des bronchioles terminales, sans alvéoles","Par des capillaires directs, sans membrane","Par la carène, à la division de la trachée"],"r":0,"e":"Les conduits alvéolaires, entièrement tapissés d'alvéoles, se terminent par des alvéoles simples et des sacs alvéolaires.","s":0},{"q":"Qu'est-ce qui rend le revêtement alvéolaire idéal pour les échanges gazeux ?","o":["Sa finesse particulière","Sa richesse en muscle lisse","Sa densité en cils","Sa couche cartilagineuse"],"r":0,"e":"Le revêtement alvéolaire particulièrement fin est idéal pour les échanges gazeux.","s":0},{"q":"En quoi consiste le mouvement en bras de pompe ?","o":["Les côtes supérieures montent, le diamètre antéro-postérieur augmente","La grille costale inférieure s'ouvre, le diamètre transverse augmente","Le diaphragme descend, le diamètre vertical augmente","Les vertèbres tournent, le diamètre oblique augmente"],"r":0,"e":"Bras de pompe : côtes supérieures, diamètre antéro-postérieur. Anse de seau : grille costale inférieure, diamètre transverse.","s":0},{"q":"Quand les muscles respiratoires accessoires sont-ils recrutés ?","o":["À l'effort","En présence d'une pathologie","Au repos systématiquement","Pendant le sommeil profond"],"r":[0,1],"e":"L'inspiration de repos mobilise le diaphragme et les intercostaux externes ; les accessoires sont recrutés à l'effort ou en cas de pathologie.","s":0},{"q":"Comment définit-on l'élasticité pulmonaire ?","o":["Reprendre sa forme d'origine quand les forces d'étirement cessent","Résister au flux d'air dans les voies aériennes, à l'inspiration","Produire du surfactant pour réduire la tension superficielle","Développer la force du diaphragme à chaque inspiration"],"r":0,"e":"L'élasticité est le retour à la forme d'origine après retrait des forces extérieures — comme un ballon qui se dilate puis reprend sa position de repos.","s":0},{"q":"De quels facteurs la diffusion de l'oxygène dépend-elle ?","o":["La surface et la capacité de diffusion de la membrane","Le volume de sang capillaire pulmonaire","Le rapport ventilation/perfusion","Le temps de séjour du sang au contact de la membrane","L'hémoglobine et la PaO₂","La fréquence cardiaque de repos"],"r":[0,1,2,3,4],"e":"Les six facteurs sont énumérés dans la fiche.","s":0},{"q":"Quels champs pulmonaires sont les mieux perfusés ?","o":["Les champs dépendants","Les champs non dépendants","Les sommets en position debout","Tous de façon homogène"],"r":0,"e":"La perfusion dépend surtout de la pesanteur : les champs dépendants sont mieux perfusés. Debout, ce sont donc les bases.","s":0},{"q":"Quel est l'objectif principal du système de transport de l'oxygène ?","o":["La perfusion des tissus avec du sang oxygéné","La saturation maximale de l'hémoglobine","L'élimination du CO₂","L'augmentation du débit cardiaque"],"r":0,"e":"L'objectif principal est la perfusion des tissus avec du sang oxygéné, l'extraction étant régulée par le besoin cellulaire.","s":0},{"q":"Quels facteurs peuvent limiter l'étape d'extraction tissulaire ?","o":["Les enzymes mitochondriales du cycle de Krebs","La myoglobine musculaire","Des déficits nutritionnels ou enzymatiques","La fraction inspirée en oxygène"],"r":[0,1,2],"e":"Enzymes mitochondriales du cycle de Krebs et myoglobine, secondairement à des déficits nutritionnels ou enzymatiques musculaires. C'est la quantité et la qualité des enzymes qui comptent.","s":0},{"q":"Que devient le CO₂ à l'étape 9 du transport de l'oxygène ?","o":["Il passe des cellules au cœur droit, diffuse dans l'alvéole et est expiré","Il est stocké dans les alvéoles, puis libéré lentement entre deux cycles","Il est transformé en oxygène dans les capillaires pulmonaires","Il est éliminé par les reins, sous forme de bicarbonates dans les urines"],"r":0,"e":"Le sang veineux et le CO₂ retournent au cœur droit et aux poumons ; le CO₂ diffuse à travers la membrane alvéolo-capillaire et est éliminé.","s":0},{"q":"Pourquoi la position debout est-elle importante face au stress gravitationnel ?","o":["Elle restaure le stress gravitationnel qui entretient la régulation des fluides","Elle augmente la fraction inspirée d'oxygène dans les alvéoles des bases","Elle réduit la fréquence cardiaque de repos et le travail du cœur","Elle diminue la consommation d'oxygène des muscles posturaux"],"r":0,"e":"L'immobilité et l'alitement font perdre les mécanismes de régulation des fluides responsables de la stabilité hémodynamique ; la position debout restaure le stress gravitationnel.","s":0},{"q":"Quels paramètres augmente la réponse « lutte ou fuite » ?","o":["La fréquence cardiaque et la pression artérielle","Le CO₂ et la glycémie","La force musculaire et la vigilance mentale","Le métabolisme et l'apport sanguin musculaire","La production de surfactant alvéolaire"],"r":[0,1,2,3],"e":"Tous ces paramètres augmentent, avec pour conséquence une consommation accrue d'oxygène — réponse médiée par le système nerveux sympathique.","s":0},{"q":"Quels sont les quatre symptômes majeurs de l'examen subjectif respiratoire ?","o":["Toux, expectoration, dyspnée et douleur thoracique","Fièvre, toux, asthénie, anorexie et perte de poids","Dyspnée, cyanose, œdème des chevilles et palpitations","Toux, hémoptysie, vomique et fièvre"],"r":0,"e":"Hémoptysie et vomique font partie des symptômes mineurs ou complémentaires.","s":1},{"q":"Que faut-il préciser pour chaque symptôme majeur ?","o":["Fréquence, durée, localisation, sévérité, qualité, facteurs, signes associés","L'intensité seule, cotée sur une échelle visuelle analogique de 0 à 10","La durée seule, en jours, depuis le début des symptômes","Les facteurs déclenchants seuls, notés dans l'ordre d'apparition"],"r":0,"e":"C'est la grille systématique d'analyse d'un symptôme.","s":1},{"q":"Pourquoi consigner les données de l'évaluation ?","o":["Informer les autres professionnels, évaluer le traitement, organiser le raisonnement","Satisfaire une obligation administrative, sans aucune autre utilité clinique pour le patient","Permettre la facturation de l'acte auprès de la caisse d'assurance","Informer le patient seul, qui conserve son propre dossier à domicile"],"r":0,"e":"Ce sont les trois justifications données dans le cours.","s":1},{"q":"Que permet le diagnostic médical au kinésithérapeute ?","o":["Connaître l'étiopathogénie, le stade, l'évolution, et orienter l'examen","Remplacer l'examen subjectif, puisque tout est déjà dans le dossier","Poser lui-même le diagnostic médical, à partir des examens prescrits","Éviter l'examen objectif, puisque la pathologie est déjà connue"],"r":0,"e":"Il permet de contextualiser les altérations du patient.","s":1},{"q":"Où se situent les zones réflexogènes de la toux ?","o":["Larynx, trachée, bronches, plèvre et conduit auditif externe","Alvéoles, parenchyme pulmonaire et capillaires","Plèvre viscérale seule, sur toute la surface du poumon","Diaphragme, paroi abdominale et muscles intercostaux"],"r":0,"e":"Les récepteurs sont plus sensibles au niveau de la glotte et de la carène.","s":1},{"q":"Où les récepteurs de la toux sont-ils les plus sensibles ?","o":["À la glotte et à la carène","Dans les alvéoles","Dans la plèvre viscérale","Dans les bronchioles terminales"],"r":0,"e":"C'est ce qui explique l'efficacité des stimulations trachéales.","s":1},{"q":"Qu'est-ce qu'une toux quinteuse ?","o":["Des accès de toux rapprochés, par irritation du vague ou du laryngé","Une toux qui s'accompagne de vomissements, souvent chez l'enfant","Une toux sans son, par atteinte des cordes vocales","Une toux productive efficace, qui ramène les sécrétions"],"r":0,"e":"La toux émétisante est celle qui s'accompagne de vomissements.","s":1},{"q":"Quelle est la différence entre toux productive et toux efficace ?","o":["La productive mobilise les sécrétions, l'efficace les élimine","Ce sont deux synonymes, qui désignent la même toux grasse","L'efficace est toujours sèche, la productive toujours grasse","La productive est nocturne, l'efficace est matinale"],"r":0,"e":"Une toux peut être productive sans être efficace.","s":1},{"q":"Jusqu'à quelle durée une toux est-elle dite aiguë ?","o":["3 semaines","1 semaine","6 semaines","3 mois"],"r":0,"e":"La toux aiguë est associée à des infections respiratoires, les virus étant les agents causaux les plus fréquents.","s":1},{"q":"Quelle proportion de fumeurs présente une toux chronique ?","o":["Environ un tiers","Environ 10 %","Environ 80 %","Moins de 5 %"],"r":0,"e":"La toux chronique diminue fortement avec l'arrêt du tabac.","s":1},{"q":"Quelle est la prévalence de la toux chronique dans la population générale non fumeuse ?","o":["3 à 13 %","30 à 40 %","Moins de 1 %","50 %"],"r":0,"e":"Elle augmente avec l'âge, davantage chez la femme, et avec la pollution.","s":1},{"q":"Quelles sont les causes les plus fréquentes de toux chez le non-fumeur ?","o":["L'écoulement nasal postérieur et le reflux gastro-œsophagien","L'asthme et la BPCO, même chez le jeune adulte non-fumeur","La tuberculose et le cancer bronchique, chez l'adulte de plus de 40 ans","L'insuffisance cardiaque gauche et l'œdème pulmonaire"],"r":0,"e":"Le cours précise aussi qu'il y a parfois plus d'une cause à l'origine de la toux.","s":1},{"q":"Quelle manifestation est associée à la toux et doit être recherchée ?","o":["L'incontinence urinaire","La bradycardie sinusale","L'hypertension artérielle","La dysphagie haute"],"r":0,"e":"Bronchospasme et incontinence urinaire sont les deux manifestations associées citées.","s":1},{"q":"De quoi est formée l'expectoration ?","o":["Des sécrétions bronchiques, orales salivaires et nasales","Des sécrétions bronchiques seules, issues des glandes","Du mucus alvéolaire seul, produit par les pneumocytes","Du surfactant, produit en excès par les alvéoles"],"r":0,"e":"Elle survient lorsqu'il existe une hypersécrétion bronchique par inflammation ou irritation de l'appareil muco-sécréteur.","s":1},{"q":"Quelle caractéristique de l'expectoration ne figure PAS dans la grille d'analyse ?","o":["Le pH","La viscosité et l'adhérence","La couleur","L'odeur"],"r":0,"e":"On recherche provenance, viscosité/adhérence, couleur, volume/quantité et odeur.","s":1},{"q":"Comment l'ATS (1999) définit-elle la dyspnée ?","o":["Une sensation subjective d'inconfort respiratoire, faite de sensations distinctes","Une baisse objective de la saturation, mesurée à l'oxymètre au repos","Une augmentation de la fréquence respiratoire, au-delà de 20 cycles par minute","Une douleur thoracique à l'inspiration, d'origine pleurale"],"r":0,"e":"L'expérience dérive de facteurs physiologiques, psychologiques, sociaux et environnementaux.","s":1},{"q":"Quand survient normalement la dyspnée ?","o":["Quand le besoin respiratoire dépasse la capacité ventilatoire","Uniquement à l'effort maximal, chez le sujet sain","Uniquement en décubitus, dans l'insuffisance cardiaque","Uniquement en cas d'hypoxémie, quelle qu'en soit la cause"],"r":0,"e":"C'est la définition physiopathologique retenue dans le cours.","s":1},{"q":"Quelle n'est PAS une des trois causes fondamentales de dyspnée ?","o":["Une anémie ferriprive isolée","Une perception accrue du souffle","Un travail respiratoire augmenté","Une pompe ou des échanges déficients"],"r":0,"e":"Les trois causes citées sont la dyspnée psychogène, l'augmentation du travail respiratoire et la déficience des échanges ou de la pompe.","s":1},{"q":"Quel mode d'installation évoque un pneumothorax spontané ou une embolie pulmonaire ?","o":["Soudain","Progressif","Nocturne exclusivement","Postural"],"r":0,"e":"L'installation progressive est caractéristique des processus évolutifs comme la BPCO ou la fibrose pulmonaire.","s":1},{"q":"Qu'est-ce que l'orthopnée ?","o":["Une dyspnée de décubitus dorsal","Une dyspnée qui survient en position debout","Une dyspnée en décubitus latéral","Une dyspnée d'effort"],"r":0,"e":"Le patient rapporte souvent le besoin de relever la tête de lit. Cardiopathies, BPCO.","s":1},{"q":"Qu'est-ce que la platypnée ?","o":["Une dyspnée qui survient ou s'aggrave en position debout","Une dyspnée qui survient ou s'aggrave en décubitus dorsal","Une dyspnée qui survient ou s'aggrave en décubitus latéral","Une dyspnée qui survient ou s'aggrave la nuit, au réveil"],"r":0,"e":"Exemple donné : la péricardite.","s":1},{"q":"Qu'est-ce que la trépopnée ?","o":["Une dyspnée qui survient ou s'aggrave en décubitus latéral","Une dyspnée qui survient ou s'aggrave en position debout","Une dyspnée qui survient ou s'aggrave en parlant","Une dyspnée qui survient par accès, la nuit, au réveil"],"r":0,"e":"Exemple donné : l'épanchement pleural unilatéral.","s":1},{"q":"Comment se manifeste la dyspnée paroxystique nocturne ?","o":["Le sommeil est interrompu par un manque d'air dramatique, avec sueurs","Par une toux sèche matinale, au lever, qui cède après le petit-déjeuner","Par une douleur thoracique à l'inspiration, qui réveille le patient","Par une orthopnée progressive, qui oblige à ajouter des oreillers"],"r":0,"e":"C'est une forme particulière de dyspnée décrite dans le cours.","s":1},{"q":"Quelles structures thoraciques n'ont PAS de sensibilité ?","o":["Les bronchioles, le parenchyme pulmonaire et la plèvre viscérale","La plèvre pariétale, au contact de la paroi thoracique","Les nerfs intercostaux, le long du bord inférieur des côtes","La paroi thoracique, muscles et côtes compris"],"r":0,"e":"Les récepteurs douloureux sont uniquement dans la plèvre pariétale.","s":1},{"q":"Quelle est la douleur thoracique la plus fréquente ?","o":["La douleur musculo-squelettique","La douleur d'origine cardiaque","La douleur d'origine pleurétique","La douleur d'origine œsophagienne"],"r":0,"e":"Par ordre de fréquence : musculo-squelettique, puis cardiaque, puis pleurétique.","s":1},{"q":"Où irradie la douleur de la plèvre diaphragmatique ?","o":["À l'épaule, par le nerf phrénique","Au bras gauche, par le plexus brachial","À l'abdomen, par les nerfs intercostaux","Au rachis cervical, par les nerfs rachidiens"],"r":0,"e":"C'est un point clé du diagnostic différentiel de la douleur thoracique.","s":1},{"q":"Comment distinguer la douleur pleurétique de la douleur musculo-squelettique ?","o":["Les deux surviennent à l'inspiration, la musculo-squelettique en un point","La pleurétique ne varie pas avec l'inspiration, contrairement à l'autre","La musculo-squelettique est toujours nocturne, la pleurétique diurne","La pleurétique irradie au bras gauche, l'autre reste localisée"],"r":0,"e":"La douleur cardiaque, elle, est très intense et ne varie ni avec l'inspiration ni avec la position.","s":1},{"q":"Qu'est-ce qui distingue l'hémoptysie de l'hématémèse ?","o":["L'hémoptysie est du sang rouge vif respiratoire, l'hématémèse du sang foncé digestif","L'hémoptysie vient de l'estomac, l'hématémèse des voies aériennes inférieures","L'hématémèse est toujours plus abondante que l'hémoptysie, à chaque épisode","Aucune différence, les deux termes désignent un saignement par la bouche"],"r":0,"e":"Pathologies associées à l'hémoptysie : tuberculose pulmonaire, néoplasie pulmonaire.","s":1},{"q":"Qu'est-ce que la vomique ?","o":["L'émission par la bouche d'un grand volume de liquide respiratoire","Un vomissement alimentaire, d'origine digestive, après un repas copieux","Une expectoration sanglante, d'origine bronchique, rouge vif et aérée","Une toux émétisante, qui se termine par un vomissement"],"r":0,"e":"Elle est purulente ou non, par exemple lors d'un abcès.","s":1},{"q":"Comment calcule-t-on la charge tabagique en paquets-années ?","o":["Paquets par jour × années de tabagisme","Cigarettes par jour × mois de tabagisme","Années de tabagisme ÷ paquets par jour","Paquets par jour + années de tabagisme"],"r":0,"e":"PA = (nb de paquets) × (nb d'années de tabagisme).","s":1},{"q":"Par quels moyens le kinésithérapeute recueille-t-il les données de l'évaluation respiratoire ?","o":["Entretien avec le patient ou ses proches","Dossier clinique et comptes rendus","Observation directe","Mesures et tests spécifiques","Capacité vitale mesurée chez tous"],"r":[0,1,2,3],"e":"Les quatre sources sont citées : entretien, documents, observation directe, mesures et tests spécifiques.","s":1},{"q":"Que permet l'entretien avec le patient ?","o":["Obtenir sa perspective","Établir un contact","Obtenir l'information du diagnostic kiné","Suivre les symptômes sous traitement","Remplacer l'examen objectif"],"r":[0,1,2,3],"e":"Quatre apports ; l'information recueillie doit ensuite être confrontée à celle obtenue objectivement.","s":1},{"q":"Quelles données figurent dans la rubrique démographique ?","o":["Nom, âge, sexe, état civil, origine","Adresse, téléphone, contacts, profession","Hospitalisation ou ambulatoire, médecin","Dates de demande et de prise en charge","Diagnostic médical et comorbidités"],"r":[0,1,2,3],"e":"Le diagnostic médical constitue une rubrique distincte, la troisième.","s":1},{"q":"Que comprend la rubrique « examen subjectif » proprement dite ?","o":["Histoire clinique actuelle","Histoire clinique antérieure","Revue par systèmes","Données démographiques"],"r":[0,1,2],"e":"L'examen subjectif regroupe histoire actuelle, histoire antérieure et revue par systèmes.","s":1},{"q":"Quels déclencheurs peuvent provoquer la toux ?","o":["L'inflammation, les sécrétions","Des corps étrangers","Gaz, odeurs, produits chimiques","Tumeurs, compressions trachéales","Une hypoglycémie sévère"],"r":[0,1,2,3],"e":"Les quatre familles de déclencheurs sont citées.","s":1},{"q":"Qu'est-ce qu'une toux rauque ?","o":["Une toux qui vient des cordes vocales et du larynx","Une toux qui s'accompagne de vomissements, chez l'enfant","Une toux en accès très rapprochés, par irritation vagale","Une toux non productive, qui ne ramène rien"],"r":0,"e":"La toux rauque vient des cordes vocales et du larynx ; la toux aphone en est une variante. L'émétisante s'accompagne de vomissements, la quinteuse survient en accès rapprochés.","s":1},{"q":"Quel nerf est irrité dans la toux quinteuse ?","o":["Le nerf vague ou laryngé","Le nerf phrénique","Le nerf intercostal","Le nerf récurrent seul"],"r":0,"e":"Les accès de toux très rapprochés et successifs traduisent une irritation du nerf vague ou laryngé.","s":1},{"q":"Comment évolue la toux chronique avec l'âge et l'environnement ?","o":["Elle augmente avec l'âge, plus chez la femme","Elle augmente avec la pollution","Elle diminue fortement avec l'arrêt du tabac","Elle disparaît systématiquement après 60 ans"],"r":[0,1,2],"e":"La prévalence augmente avec l'âge (davantage chez la femme) et avec la pollution, et diminue fortement à l'arrêt du tabac.","s":1},{"q":"Qu'est-ce qui explique l'apparition d'une expectoration ?","o":["Une hypersécrétion bronchique, par inflammation ou irritation muqueuse","Une déshydratation, qui épaissit les sécrétions de la trachée","Une hyperventilation, qui assèche les voies aériennes et le mucus","Un bronchospasme isolé, sans inflammation ni sécrétion associée"],"r":0,"e":"L'expectoration survient en cas d'hypersécrétion bronchique liée à une inflammation ou une irritation de l'appareil muco-sécréteur.","s":1},{"q":"Quelles caractéristiques de l'expectoration faut-il rechercher ?","o":["Sa provenance, haute ou basse","Sa viscosité et son adhérence","Sa couleur, son volume, sa quantité","Son odeur, inodore ou fétide","Sa température au thermomètre"],"r":[0,1,2,3],"e":"Provenance et caractéristiques : viscosité/adhérence, couleur, volume/quantité et odeur.","s":1},{"q":"De quoi dérive l'expérience de la dyspnée selon l'ATS ?","o":["De l'interaction de facteurs physiologiques, psychologiques, sociaux, environnementaux","De la seule PaO₂, mesurée sur les gaz du sang artériel, au repos et à l'effort","De la seule fréquence respiratoire, au repos puis à l'effort maximal","De la volonté du patient, qui peut décider de ne pas la ressentir"],"r":0,"e":"C'est une sensation subjective d'inconfort respiratoire, qualitativement distincte et variable en intensité, dérivant de facteurs physiologiques, psychologiques, sociaux et environnementaux.","s":1},{"q":"Quelles sont les trois causes fondamentales de dyspnée ?","o":["Une perception accrue de la respiration","Une augmentation du travail respiratoire","Une déficience des échanges ou de la pompe","Une anémie isolée, sans atteinte respiratoire"],"r":[0,1,2],"e":"Perception accrue, augmentation du travail respiratoire et déficience de l'appareil respiratoire. La perception accrue correspond à la dyspnée psychogène.","s":1},{"q":"Quelle pathologie illustre une dyspnée d'installation progressive ?","o":["La BPCO","La fibrose pulmonaire","Le pneumothorax spontané","L'embolie pulmonaire"],"r":[0,1],"e":"BPCO et fibrose pulmonaire évoluent progressivement. Pneumothorax spontané et embolie pulmonaire donnent une dyspnée soudaine.","s":1},{"q":"Quelle pathologie illustre la trépopnée ?","o":["L'épanchement pleural unilatéral","La péricardite aiguë","La BPCO avec distension","Les cardiopathies évoluées"],"r":0,"e":"Trépopnée (décubitus latéral) : épanchement pleural unilatéral. Platypnée (debout) : péricardite. Orthopnée (décubitus dorsal) : cardiopathies, BPCO.","s":1},{"q":"Quelles autres formes de dyspnée sont décrites ?","o":["La dyspnée de phonation","La dyspnée inspiratoire, par obstruction haute","La dyspnée expiratoire, dans l'asthme","La dyspnée paroxystique nocturne","La dyspnée d'origine rénale"],"r":[0,1,2,3],"e":"Les quatre formes sont citées. La dyspnée d'effort est, elle, très fréquente et non spécifique.","s":1},{"q":"Quelle est la différence entre une douleur irradiée et une douleur réflexe ?","o":["L'irradiée suit un trajet nerveux lésé ; la réflexe siège dans le dermatome d'un viscère","L'irradiée est d'origine viscérale ; la réflexe est d'origine nerveuse périphérique","L'irradiée est toujours d'origine cardiaque ; la réflexe toujours pleurale","Aucune différence : ce sont deux termes pour la même douleur thoracique"],"r":0,"e":"Localisée : limitée au lieu de genèse. Irradiée : lésion de tout un trajet nerveux. Réflexe : ressentie dans le dermatome correspondant à l'origine viscérale du stimulus.","s":1},{"q":"À quoi la douleur d'origine cardiaque est-elle essentiellement due ?","o":["À l'extension de l'inflammation à la plèvre diaphragmatique","À la stimulation des fibres C des bronches principales","À une compression des nerfs intercostaux par le cœur","À un reflux œsophagien, lié à la proximité du cœur"],"r":0,"e":"La douleur cardiaque est essentiellement due à l'extension à la plèvre diaphragmatique du processus inflammatoire.","s":1},{"q":"Quelles fibres sensitives persistent dans les voies aériennes ?","o":["Quelques fibres C, dans les bronches principales et la trachée","Des fibres A delta, dans les alvéoles et les bronchioles terminales","Des nocicepteurs, dans la plèvre viscérale qui recouvre le poumon","Des récepteurs, dans le parenchyme pulmonaire"],"r":0,"e":"Les poumons sont virtuellement insensibles ; seules quelques fibres C persistent dans les bronches principales et la trachée.","s":1},{"q":"Comment reconnaît-on une douleur d'origine cardiaque ?","o":["Elle est très intense et ne varie ni avec l'inspiration ni avec la position","Elle survient à l'inspiration profonde et cède quand le patient tient l'apnée","Elle est localisée en un point précis, reproduit à la palpation","Elle cède au repos strict, en décubitus, en quelques minutes"],"r":0,"e":"La douleur cardiaque est très intense et ne varie pas avec l'inspiration ni la position — contrairement aux douleurs pleurétique et musculo-squelettique.","s":1},{"q":"Quels éléments faut-il explorer dans les antécédents et l'environnement familiaux ?","o":["Les pathologies héréditaires","La possibilité de contagion","La situation socio-familiale","Le logement, ses barrières et l'humidité","Le niveau de revenu du patient"],"r":[0,1,2,3],"e":"Les quatre dimensions sont explorées. Le logement inclut aussi la présence d'animaux.","s":1},{"q":"Qu'observe-t-on lorsque les rayons X traversent une matière peu dense ?","o":["Une hypertransparence : zones plus sombres","Une opacité : zones plus claires et blanches","Aucune image : la matière ne laisse aucune trace","Un artefact : zones floues et mal définies"],"r":0,"e":"La matière peu dense perd peu d'énergie, d'où l'hypertransparence.","s":2},{"q":"Qu'observe-t-on lorsque les rayons X traversent une matière très dense ?","o":["Une hypotransparence ou opacité : zones plus claires","Une hypertransparence : zones plus sombres et noires","Une image noire : aucune énergie n'est absorbée","Aucune absorption : le film reste uniformément gris"],"r":0,"e":"La matière très dense perd beaucoup d'énergie.","s":2},{"q":"Quelle pathologie donne une hypertransparence ?","o":["Le pneumothorax","La pneumonie","L'atélectasie","L'épanchement pleural"],"r":0,"e":"Hypertransparence : emphysème pulmonaire et pneumothorax.","s":2},{"q":"Quelle pathologie donne une hypotransparence ?","o":["L'atélectasie","L'emphysème","Le pneumothorax","La distension pulmonaire"],"r":0,"e":"Hypotransparence : pneumonie et atélectasie.","s":2},{"q":"Comment le patient est-il positionné pour une incidence PA ?","o":["Debout, thorax contre le film, épaules en avant, mains sur les lombes","Couché sur le dos, bras le long du corps, film sous le thorax","Debout, dos contre le film, bras le long du corps, menton levé","Assis, bras le long du corps, dos contre le dossier, film devant"],"r":0,"e":"Le cliché est pris en apnée inspiratoire. C'est le dos des mains qui repose sur la région lombaire.","s":2},{"q":"Quand utilise-t-on une incidence antéro-postérieure (AP) ?","o":["Lorsque le patient est alité et ne peut pas se tenir debout","Systématiquement en première intention, chez tout patient","Pour l'étude du diaphragme, en inspiration et en expiration","Pour l'étude des épanchements interlobaires, en lordose"],"r":0,"e":"C'est une incidence non conventionnelle, utilisée par défaut chez le patient alité.","s":2},{"q":"À quel moment du cycle respiratoire le cliché est-il pris ?","o":["En apnée inspiratoire","En apnée expiratoire","En respiration libre","En expiration forcée"],"r":0,"e":"L'apnée conditionne la netteté du cliché.","s":2},{"q":"Comment juge-t-on de la dureté des rayons sur un cliché PA ?","o":["La colonne se devine à peine derrière le cœur, la trame reste fine","La colonne est invisible derrière l'ombre cardiaque, même à la loupe","La colonne est parfaitement nette sur toute sa hauteur","Les côtes sont effacées et la trame pulmonaire très marquée"],"r":0,"e":"C'est le critère de bonnes conditions techniques.","s":2},{"q":"Quel critère permet de vérifier que le patient n'est pas tourné ?","o":["La trachée centrée sur les épineuses, les clavicules à égale distance","Les coupoles diaphragmatiques à la même hauteur des deux côtés","L'ombre cardiaque de taille normale, centrée sur la ligne médiane","Les scapulas bien visibles, en dehors des champs pulmonaires"],"r":0,"e":"C'est le critère de bonne position du patient par rapport au film.","s":2},{"q":"Quel hile est normalement le plus haut ?","o":["Le hile gauche","Le hile droit","Ils sont au même niveau","Cela varie selon les patients"],"r":0,"e":"Le hile gauche est plus haut que le droit ; les hiles correspondent à la division des artères pulmonaires.","s":2},{"q":"Quelle coupole diaphragmatique est normalement la plus haute ?","o":["La droite","La gauche","Elles sont symétriques","Cela dépend de la position"],"r":0,"e":"La coupole droite est plus haute que la gauche, du fait du foie.","s":2},{"q":"Qu'appelle-t-on la trame pulmonaire ?","o":["L'arborisation broncho-vasculaire","La silhouette cardiaque et médiastinale","Le contour interne des côtes","La ligne pleurale périphérique"],"r":0,"e":"Elle s'analyse dans les champs pulmonaires.","s":2},{"q":"Quelles structures composent l'ombre médiastinale ?","o":["Le cœur et les gros vaisseaux","Les hiles pulmonaires","Le sternum et la colonne","La trachée seule"],"r":0,"e":"L'ombre médiastinale est un des éléments à décrire systématiquement.","s":2},{"q":"Quels angles faut-il analyser au niveau des coupoles ?","o":["Les angles costo-phréniques et cardio-phréniques","Les angles scapulaires supérieur et inférieur","L'angle de Louis, entre manubrium et sternum","Les angles costo-vertébraux, en arrière"],"r":0,"e":"On analyse aussi la position et la courbure des coupoles.","s":2},{"q":"Que permet de bien visualiser le cliché de profil ?","o":["Les culs-de-sac costo-phréniques et l'espace rétro-sternal","Les clavicules et les articulations sterno-claviculaires","Les sommets pulmonaires, au-dessus des clavicules","Le rachis cervical, de C1 à C7, et la charnière"],"r":0,"e":"Il permet de voir en avant ou en arrière de l'ombre cardiaque.","s":2},{"q":"Sur un profil, comment se comporte la densité des corps vertébraux ?","o":["Les corps supérieurs sont plus denses que les inférieurs","Les corps inférieurs sont plus denses que les supérieurs","La densité est homogène, du haut en bas du rachis","Les corps vertébraux ne sont pas visibles sur le profil"],"r":0,"e":"C'est un des critères de lecture du cliché de profil.","s":2},{"q":"Comment le patient positionne-t-il ses membres supérieurs pour un profil ?","o":["Élevés, avant-bras posés sur la tête","Le long du corps, paumes en avant","Le dos des mains sur la région lombaire","Croisés sur la poitrine, mains aux épaules"],"r":0,"e":"Cette position dégage les champs pulmonaires.","s":2},{"q":"Quelle incidence spéciale met en évidence les petits épanchements pleuraux ?","o":["Le décubitus latéral","La lordotique apicale","L'oblique","Le profil standard"],"r":0,"e":"Elle met en évidence les niveaux liquidiens (ou gazeux pour un pneumothorax).","s":2},{"q":"Quelle incidence améliore la visualisation des sommets pulmonaires ?","o":["La lordotique apicale","Le décubitus latéral","Le profil","L'incidence PA standard"],"r":0,"e":"Elle sert aussi à visualiser les épanchements interlobaires.","s":2},{"q":"Comment sont obtenues les images en tomodensitométrie ?","o":["Par des rayons X émis en arc, donnant des images en coupe","Par résonance magnétique, avec des ondes de radiofréquence","Par ultrasons, réfléchis par les interfaces des tissus","Par émission de positons, après injection d'un traceur radioactif"],"r":0,"e":"On distingue les fenêtres médiastinale et pulmonaire.","s":2},{"q":"Quelle est l'indication principale de la TDM thoracique ?","o":["Clarifier les anomalies vues sur la radiographie conventionnelle","Dépister systématiquement les pathologies chez tous les patients","Évaluer la cinétique du diaphragme pendant la respiration","Guider les ponctions pleurales et la pose de drains thoraciques"],"r":0,"e":"La cinétique diaphragmatique et le guidage relèvent plutôt de l'échographie.","s":2},{"q":"Quel diagnostic différentiel la TDM permet-elle ?","o":["Solide ou kystique, pulmonaire, pleurale ou pariétale","Pneumonie virale ou bactérienne, selon l'aspect","Asthme ou BPCO, selon l'épaisseur des bronches","Atélectasie ou emphysème seulement, selon la densité"],"r":0,"e":"Elle permet aussi l'étude des hiles et du médiastin. Elle distingue les lésions solides des kystiques, et les lésions pulmonaires, pleurales et pariétales.","s":2},{"q":"Quel est un avantage majeur de l'IRM thoracique ?","o":["Elle ne nécessite pas de produit de contraste","Elle est plus rapide que la radiographie","Elle utilise moins de rayons X que la TDM","Elle visualise mieux le parenchyme aéré"],"r":0,"e":"Elle donne des images anatomiques de haute définition sans produit de contraste.","s":2},{"q":"Quelle structure l'IRM permet-elle particulièrement bien d'étudier ?","o":["Les vaisseaux, le médiastin, les hiles et le diaphragme","Le parenchyme aéré, jusqu'à la périphérie du poumon","Les alvéoles, une à une, avec leur paroi","Les bronchioles terminales et leur épithélium cilié"],"r":0,"e":"Elle explore aussi l'envahissement tumoral et les cardiopathies congénitales.","s":2},{"q":"Pourquoi l'échographie est-elle limitée pour l'étude du parenchyme pulmonaire ?","o":["L'air fait barrière au passage des ultrasons","Les côtes absorbent tous les ultrasons émis","La résolution est insuffisante pour voir les bronches","Elle nécessite un produit de contraste iodé"],"r":0,"e":"C'est la limite fondamentale de l'échographie thoracique.","s":2},{"q":"Quelle est une indication de l'échographie thoracique ?","o":["Les épanchements pleuraux et la cinétique du diaphragme","Le parenchyme aéré et les bronches segmentaires et sous-segmentaires","Le bilan d'un emphysème et de la distension","Les sommets pulmonaires et les lésions apicales"],"r":0,"e":"Elle sert aussi au guidage pour la pose de drain thoracique et la ponction aspirative.","s":2},{"q":"Quel est le rôle du film radiographique ?","o":["Il constitue le négatif de l'image","Il émet les rayons X vers le patient","Il filtre le faisceau avant le thorax","Il amplifie le signal reçu par le tube"],"r":0,"e":"Le tube à rayons X est la source d'énergie, le faisceau est légèrement divergent en cône, et le film est le négatif.","s":2},{"q":"Quelles structures font partie des parties molles à analyser ?","o":["Seins, muscles, graisse, peau et tissu sous-cutané","Clavicules, côtes, scapulas et rachis thoracique","Cœur, gros vaisseaux et médiastin supérieur","Hiles pulmonaires, bronches souches et artères"],"r":0,"e":"Les structures osseuses et l'ombre médiastinale sont analysées séparément.","s":2},{"q":"À quoi correspond le contrôle du « dégagement des scapulas » ?","o":["Vérifier que les scapulas ne se superposent pas aux champs pulmonaires","Mesurer la hauteur des scapulas par rapport aux clavicules et aux côtes","Évaluer la mobilité de l'épaule en élévation sur le cliché de face","Contrôler la symétrie osseuse des deux ceintures scapulaires"],"r":0,"e":"C'est une des étapes de l'analyse systématique d'un cliché PA.","s":2},{"q":"Quel élément du cliché de profil permet d'évaluer la distension thoracique ?","o":["Le diamètre antéro-postérieur du thorax","La densité des corps vertébraux, de haut en bas","La position des scapulas par rapport au rachis","L'émergence des bronches souches au niveau des hiles"],"r":0,"e":"L'augmentation du diamètre antéro-postérieur et de l'espace clair rétro-sternal signe la distension.","s":2},{"q":"Quels sont les trois éléments du dispositif radiographique décrit ?","o":["Le tube à rayons X, la source","Le faisceau, divergent en cône","Le film radiographique, négatif","Le capteur, à ultrasons"],"r":[0,1,2],"e":"Tube (source), faisceau divergent en cône et film radiographique négatif.","s":2},{"q":"Que devient l'énergie des rayons X lorsqu'ils traversent une substance ?","o":["Elle est partiellement absorbée","Elle est intégralement transmise","Elle est convertie en ultrasons","Elle est réfléchie"],"r":0,"e":"L'énergie est partiellement absorbée, et c'est l'importance de cette absorption qui crée le contraste de l'image.","s":2},{"q":"Comment le patient place-t-il ses mains lors d'une incidence postéro-antérieure ?","o":["Le dos des mains sur la région lombaire, épaules projetées en avant","Les mains posées sur la tête, coudes écartés et projetés vers l'arrière","Les bras le long du corps, paumes tournées vers l'avant","Les mains croisées devant la poitrine, épaules en arrière"],"r":0,"e":"Debout, face antérieure du thorax contre le film, épaules projetées vers l'avant et dos des mains sur la région lombaire — cette position dégage les scapulas.","s":2},{"q":"Quelles sont les caractéristiques de l'incidence de profil ?","o":["Face latérale contre le film","Bras élevés, avant-bras sur la tête","En apnée inspiratoire","Patient couché sur le dos"],"r":[0,1,2],"e":"Face latérale contre le film, membres supérieurs élevés avec avant-bras sur la tête, en apnée inspiratoire.","s":2},{"q":"Que doit-on voir des champs pulmonaires sur un cliché correctement exposé ?","o":["Une trame fine et discrète","Une opacité homogène","Un blanc complet","Une absence totale de trame"],"r":0,"e":"Les conditions techniques sont bonnes si la colonne se devine tout juste derrière l'ombre cardiaque et si les champs pulmonaires montrent une trame fine et discrète.","s":2},{"q":"De quoi dépend la netteté d'un cliché thoracique ?","o":["De l'apnée","De la dureté des rayons","Du centrage","De la position des scapulas"],"r":0,"e":"La netteté dépend de l'apnée ; la dureté des rayons conditionne l'exposition et le centrage la position de l'image.","s":2},{"q":"Quelles structures osseuses faut-il analyser sur un cliché thoracique ?","o":["La colonne vertébrale","Les clavicules et les arcs costaux","Le sternum","Les scapulas","Les coupoles diaphragmatiques"],"r":[0,1,2,3],"e":"Colonne vertébrale, clavicules, arcs costaux, sternum et scapulas composent l'analyse des structures osseuses.","s":2},{"q":"À quoi correspondent les hiles pulmonaires sur un cliché ?","o":["À la division des artères pulmonaires","À l'arborisation broncho-vasculaire périphérique","Aux coupoles diaphragmatiques","Aux culs-de-sac costo-phréniques"],"r":0,"e":"Les hiles correspondent à la division des artères pulmonaires, le gauche étant normalement plus haut que le droit.","s":2},{"q":"Quels culs-de-sac le cliché de profil permet-il de visualiser ?","o":["Le costo-phrénique antérieur","Le costo-phrénique postérieur","Le cardio-phrénique droit","Le costo-phrénique latéral"],"r":[0,1],"e":"Le profil visualise bien les culs-de-sac costo-phréniques antérieur et postérieur, ainsi que l'espace rétro-sternal.","s":2},{"q":"Quels éléments analyse-t-on sur un cliché de profil ?","o":["Le diamètre antéro-postérieur du thorax","Le médiastin et l'espace rétro-sternal","L'émergence des bronches principales","Les sinus costo-phréniques antérieur et postérieur","Les extrémités internes des clavicules"],"r":[0,1,2,3],"e":"S'y ajoutent position, conditions techniques, netteté, colonne vertébrale, champs pulmonaires, coupoles et scapulas.","s":2},{"q":"Que met en évidence l'incidence en décubitus latéral ?","o":["Un niveau liquidien d'un petit épanchement","Un niveau gazeux d'un pneumothorax","Les sommets des deux poumons, sous les clavicules","Les épanchements interlobaires, dans les scissures"],"r":[0,1],"e":"L'incidence PA ou AP en décubitus latéral met en évidence les niveaux liquidiens des petits épanchements, ou gazeux en cas de pneumothorax. Les sommets et les épanchements interlobaires relèvent de l'incidence lordotique apicale.","s":2},{"q":"Quelles fenêtres la tomodensitométrie utilise-t-elle ?","o":["La fenêtre médiastinale","La fenêtre pulmonaire","La fenêtre osseuse exclusivement","La fenêtre vasculaire"],"r":[0,1],"e":"La TDM produit des images en coupe exploitées en fenêtres médiastinale et pulmonaire.","s":2},{"q":"Quels diagnostics différentiels la TDM thoracique permet-elle ?","o":["Entre lésions solides et kystiques","Entre lésions pulmonaires, pleurales et pariétales","L'étude des hiles et du médiastin","La cinétique du diaphragme en temps réel"],"r":[0,1,2],"e":"La TDM distingue solide/kystique et pulmonaire/pleural/pariétal, et étudie hiles et médiastin. La cinétique diaphragmatique relève de l'échographie.","s":2},{"q":"Quel est le principe de l'IRM thoracique ?","o":["Des antennes de radiofréquence, avec intégration de l'image par ordinateur","Un faisceau de rayons X en arc, avec reconstruction en coupes axiales","Des ondes ultrasonores réfléchies par les interfaces entre tissus","Un produit de contraste iodé obligatoire, injecté avant l'examen"],"r":0,"e":"L'IRM repose sur la résonance magnétique, avec des antennes de radiofréquence, et ne nécessite pas de produit de contraste.","s":2},{"q":"Quelles atteintes tumorales l'IRM permet-elle d'explorer ?","o":["L'envahissement des vaisseaux","L'envahissement du péricarde, de la plèvre","L'envahissement du diaphragme, de la paroi","Les micronodules du parenchyme"],"r":[0,1,2],"e":"L'IRM explore l'envahissement tumoral des vaisseaux, du péricarde, de la plèvre, du diaphragme et de la paroi thoracique, ainsi que l'infarctus pulmonaire et les cardiopathies congénitales.","s":2},{"q":"Quelles indications l'échographie thoracique a-t-elle ?","o":["L'étude des épanchements pleuraux","La cinétique du diaphragme","Le guidage pour la pose de drain thoracique","Le guidage de la ponction aspirative de lésions pulmonaires","L'étude du parenchyme pulmonaire"],"r":[0,1,2,3],"e":"Quatre indications. L'étude du parenchyme reste très difficile, l'air faisant barrière au passage des ultrasons.","s":2},{"q":"Pourquoi une pneumonie apparaît-elle plus claire sur un cliché ?","o":["Le tissu dense absorbe plus d'énergie et donne une hypotransparence","L'air y est plus abondant, absorbe plus d'énergie et donne une opacité","Les rayons la traversent sans aucune perte d'énergie","Le film est surexposé à l'endroit de la pneumonie"],"r":0,"e":"Une matière très dense perd beaucoup d'énergie : il en résulte une hypotransparence, c'est-à-dire une zone plus claire — comme dans la pneumonie ou l'atélectasie.","s":2},{"q":"Pourquoi un pneumothorax apparaît-il plus sombre ?","o":["L'air peu dense absorbe peu d'énergie et donne une hypertransparence","La plèvre épaissie absorbe davantage d'énergie et noircit le film à cet endroit","Le poumon collabé devient plus dense et plus noir","Le cliché est sous-exposé à cet endroit précis"],"r":0,"e":"Une matière peu dense perd peu d'énergie : l'image est hypertransparente, plus sombre — comme dans l'emphysème ou le pneumothorax.","s":2},{"q":"Quelles étapes d'analyse d'un cliché PA concernent la qualité technique avant l'analyse anatomique ?","o":["La position de l'image sur le film","La dureté des rayons","La netteté","La position du patient","Le dégagement des scapulas"],"r":[0,1,2,3],"e":"Ces quatre contrôles précèdent l'analyse du dégagement des scapulas, des parties molles, des structures osseuses, du médiastin, des hiles, des champs et des coupoles.","s":2},{"q":"Un cliché montre les extrémités internes des clavicules à des distances inégales des apophyses épineuses. Qu'en concluez-vous ?","o":["Le patient est tourné : le cliché est mal positionné","Les rayons sont trop durs : le cliché est trop noir","L'apnée n'a pas été tenue : le cliché est flou","Une scoliose est certaine : le rachis est dévié"],"r":0,"e":"Le contrôle de rotation repose sur deux repères : trachée centrée par rapport aux apophyses épineuses et extrémités internes des clavicules équidistantes de celles-ci.","s":2},{"q":"Quel aspect radiologique de pneumonie se caractérise par des foyers multiples à distribution segmentaire ?","o":["L'aspect broncho-pneumonique","L'aspect alvéolaire systématisé","L'aspect interstitiel diffus","L'aspect nodulaire multiple"],"r":0,"e":"L'aspect broncho-pneumonique donne des foyers multiples, à distribution segmentaire, sans perte de volume.","s":3},{"q":"Quel signe caractérise l'aspect alvéolaire de la pneumonie ?","o":["Le bronchogramme aérien","Les images réticulaires","La perte de volume","La déviation médiastinale"],"r":0,"e":"L'aspect alvéolaire donne une condensation aux bords bien délimités avec bronchogramme aérien.","s":3},{"q":"Quel aspect de pneumonie donne des images réticulaires et micronodulaires ?","o":["L'aspect interstitiel","L'aspect alvéolaire","L'aspect broncho-pneumonique","L'aspect kystique"],"r":0,"e":"L'aspect interstitiel a une distribution non segmentaire et se présente sous forme d'images linéaires et de « points ».","s":3},{"q":"Les pneumonies s'accompagnent-elles d'une perte de volume ?","o":["Non, les trois aspects sont sans perte de volume","Oui, les trois aspects perdent toujours du volume","Oui, mais uniquement l'aspect alvéolaire systématisé","Oui, mais uniquement l'aspect interstitiel diffus"],"r":0,"e":"C'est ce qui les distingue radiologiquement de l'atélectasie.","s":3},{"q":"Quel est le signe distinctif de l'atélectasie ?","o":["La perte de volume","Le bronchogramme aérien","L'hypertransparence","La déviation controlatérale"],"r":0,"e":"L'atélectasie est une opacité en nappe avec perte de volume.","s":3},{"q":"Quelle conséquence la perte de volume atélectasique a-t-elle sur les structures voisines ?","o":["Un rapprochement du médiastin, des hiles et du diaphragme","Une déviation du médiastin et des hiles vers le côté opposé","Un éloignement du diaphragme et des côtes vers l'extérieur","Aucun effet sur les structures voisines, ni sur le médiastin"],"r":0,"e":"On observe aussi une diminution des espaces intercostaux et une hyperinsufflation compensatrice du parenchyme voisin.","s":3},{"q":"Que se passe-t-il dans le parenchyme voisin d'une atélectasie ?","o":["Une hyperinsufflation compensatrice","Une atélectasie secondaire voisine","Un épanchement pleural réactionnel","Une condensation alvéolaire étendue"],"r":0,"e":"C'est un mécanisme de compensation du volume perdu.","s":3},{"q":"Qu'est-ce qu'un épanchement pleural ?","o":["Une accumulation de liquide dans la cavité pleurale","Une interposition d'air dans la cavité pleurale","Une condensation alvéolaire","Une perte de volume pulmonaire"],"r":0,"e":"L'interposition d'air correspond au pneumothorax.","s":3},{"q":"Quel est l'aspect radiologique d'un épanchement pleural ?","o":["Une nappe de densité moyenne, qui efface les contours voisins","Une hypertransparence sans trame, avec la plèvre viscérale visible","Une opacité arrondie bien limitée, avec un niveau hydro-aérique","Des images réticulaires fines, diffuses aux deux bases"],"r":0,"e":"Il s'accompagne d'une déviation controlatérale des structures médianes.","s":3},{"q":"Dans quel sens dévient les structures médianes lors d'un épanchement pleural ?","o":["Vers le côté controlatéral","Vers le côté homolatéral","Elles ne dévient pas","Vers le haut"],"r":0,"e":"L'épanchement pousse le médiastin du côté opposé, contrairement à l'atélectasie qui l'attire.","s":3},{"q":"Quel signe permet d'identifier un pneumothorax sur la radiographie ?","o":["La plèvre viscérale visible et l'absence de trame","Le bronchogramme aérien dans une opacité dense","Une opacité en nappe effaçant la coupole","Un niveau hydro-aérique isolé dans le parenchyme"],"r":0,"e":"La plèvre viscérale visible marque la limite du poumon collabé ; l'absence de trame traduit l'augmentation de transparence.","s":3},{"q":"Quand observe-t-on une déviation controlatérale dans un pneumothorax ?","o":["Lorsqu'il est compressif","Toujours","Jamais","Uniquement s'il est bilatéral"],"r":0,"e":"Le pneumothorax compressif refoule les structures médianes du côté opposé.","s":3},{"q":"Qu'est-ce qu'un hydropneumothorax ?","o":["Un pneumothorax et un épanchement pleural associés, avec niveau hydro-aérique","Un pneumothorax bilatéral, avec déviation du médiastin vers le côté le plus atteint","Un épanchement cloisonné, avec plusieurs poches de liquide","Un abcès pulmonaire vidangé, avec une cavité dans le parenchyme"],"r":0,"e":"Le niveau hydro-aérique signe la présence simultanée d'air et de liquide.","s":3},{"q":"Quel signe caractérise l'emphysème pulmonaire à la radiographie ?","o":["La réduction ou l'absence de la trame pulmonaire","Une opacité en nappe de densité moyenne aux bases","Un bronchogramme aérien dans une opacité lobaire","Une perte de volume, avec rapprochement des côtes"],"r":0,"e":"S'y associent les signes de distension pulmonaire.","s":3},{"q":"Quelle est la position des coupoles diaphragmatiques dans l'emphysème ?","o":["Basse","Haute","Normale","Asymétrique"],"r":0,"e":"C'est un signe de distension pulmonaire, avec l'hypertransparence.","s":3},{"q":"Quel signe de distension accompagne l'emphysème sur le profil ?","o":["L'augmentation du diamètre antéro-postérieur et de l'espace rétro-sternal","La diminution du diamètre antéro-postérieur et du thorax en profil","L'effacement complet de l'espace clair rétro-sternal sur le profil","La réduction de l'ombre cardiaque et l'élargissement du médiastin"],"r":0,"e":"On note aussi une diminution de l'indice phréno-cinétique.","s":3},{"q":"Quel est l'aspect initial d'un abcès pulmonaire ?","o":["Une opacité homogène arrondie","Un niveau hydro-aérique","Une hypertransparence","Une image réticulaire"],"r":0,"e":"Le niveau hydro-aérique n'apparaît qu'après vidange partielle.","s":3},{"q":"Quel aspect prend un abcès après vidange partielle ?","o":["Un contour inférieur arrondi et une limite supérieure horizontale","Une opacité totalement homogène, sans aucune limite visible","Une hypertransparence complète, sans aucune trame pulmonaire","Une image micronodulaire, diffuse aux deux champs"],"r":0,"e":"C'est la définition radiologique du niveau hydro-aérique.","s":3},{"q":"Qu'est-ce que le pectus excavatum ?","o":["Une déformation sternale en entonnoir","Une déformation sternale en carène","Une cyphoscoliose","Une thoracoplastie"],"r":0,"e":"Le pectus carinatum est la déformation en carène.","s":3},{"q":"Quelle déformation associe une cyphose et une scoliose ?","o":["La cyphoscoliose","La lordose","Le pectus carinatum","La thoracoplastie"],"r":0,"e":"Les déformations rachidiennes citées sont cyphose, scoliose, cyphoscoliose et lordose.","s":3},{"q":"Qu'est-ce qu'une thoracoplastie ?","o":["Une chirurgie qui modifie la paroi thoracique","Une déformation congénitale du sternum, en entonnoir","Un épanchement pleural cloisonné, en plusieurs poches","Une atélectasie chronique d'un lobe"],"r":0,"e":"Elle figure parmi les anomalies de paroi à reconnaître sur une radiographie.","s":3},{"q":"Quelle est la distribution de l'aspect interstitiel de la pneumonie ?","o":["Non segmentaire","Segmentaire","Lobaire stricte","Uniquement apicale"],"r":0,"e":"L'aspect broncho-pneumonique, lui, a une distribution segmentaire.","s":3},{"q":"Quelle pathologie combine hypertransparence et absence de trame ?","o":["Le pneumothorax","La pneumonie alvéolaire","L'épanchement pleural","L'atélectasie"],"r":0,"e":"C'est la traduction radiologique de l'air dans la cavité pleurale.","s":3},{"q":"Quelle pathologie donne une opacité SANS perte de volume ?","o":["La pneumonie","L'atélectasie","Le pneumothorax","L'emphysème"],"r":0,"e":"C'est le critère radiologique qui différencie pneumonie et atélectasie.","s":3},{"q":"Que traduit une diminution des espaces intercostaux ?","o":["Une perte de volume, typique de l'atélectasie","Une distension pulmonaire, typique de l'emphysème","Un épanchement pleural, typique de l'insuffisance cardiaque","Un pneumothorax, typique du sujet jeune longiligne"],"r":0,"e":"Elle fait partie des signes de rapprochement des structures dans l'atélectasie.","s":3},{"q":"Quel signe permet de différencier un épanchement pleural d'une atélectasie sur la déviation médiastinale ?","o":["L'épanchement dévie le médiastin vers l'autre côté, l'atélectasie l'attire","Les deux dévient le médiastin du même côté, vers la lésion, en l'attirant","Aucun ne dévie le médiastin, qui reste sur la ligne médiane, quel que soit le volume","L'atélectasie dévie vers l'autre côté, l'épanchement l'attire"],"r":0,"e":"C'est le point clé du diagnostic différentiel radiologique.","s":3},{"q":"L'aspect alvéolaire de la pneumonie a des bords :","o":["Bien délimités","Flous et diffus","Irréguliers et multiples","Réticulaires"],"r":0,"e":"Condensation alvéolaire aux bords bien délimités avec bronchogramme aérien.","s":3},{"q":"Que signifie « image en nappe » ?","o":["Une opacité homogène étendue","Une hypertransparence étendue","Un nodule isolé et arrondi","Une ligne fine et horizontale"],"r":0,"e":"Terme utilisé pour l'atélectasie et l'épanchement pleural.","s":3},{"q":"Quelle est la conséquence radiologique d'un épanchement pleural sur les structures voisines ?","o":["Il efface leur limite","Il les rend plus nettes","Il les rapproche","Il les fait disparaître totalement"],"r":0,"e":"L'image en nappe de densité moyenne efface la limite des structures voisines.","s":3},{"q":"Quel indice diminue dans l'emphysème pulmonaire ?","o":["L'indice phréno-cinétique","L'indice cardio-thoracique","L'indice de Tiffeneau radiologique","L'indice costo-vertébral"],"r":0,"e":"La diminution de l'indice phréno-cinétique traduit la limitation de la course diaphragmatique.","s":3},{"q":"Quelles déformations rachidiennes de la paroi thoracique faut-il reconnaître ?","o":["Cyphose","Scoliose","Cyphoscoliose","Lordose","Pectus carinatum"],"r":[0,1,2,3],"e":"Cyphose, scoliose, cyphoscoliose et lordose sont rachidiennes. Pectus carinatum et excavatum sont sternales, la thoracoplastie est chirurgicale.","s":3},{"q":"Qu'est-ce que le pectus carinatum ?","o":["Un thorax en carène","Un thorax en entonnoir","Une résection costale chirurgicale","Une hypercyphose"],"r":0,"e":"Pectus carinatum = thorax en carène ; pectus excavatum = thorax en entonnoir.","s":3},{"q":"Quels signes composent l'aspect broncho-pneumonique de la pneumonie ?","o":["Des foyers multiples","Une distribution segmentaire","L'absence de perte de volume","Un bronchogramme aérien"],"r":[0,1,2],"e":"Foyers multiples, distribution segmentaire, sans perte de volume. Le bronchogramme aérien caractérise l'aspect alvéolaire.","s":3},{"q":"Quelles images caractérisent l'aspect interstitiel de la pneumonie ?","o":["Des images réticulaires, c'est-à-dire linéaires","Des images micronodulaires, en « points »","Une distribution non segmentaire","Une condensation à bords bien délimités"],"r":[0,1,2],"e":"Images réticulaires et micronodulaires, de distribution non segmentaire et sans perte de volume. La condensation bien délimitée est alvéolaire.","s":3},{"q":"Quels signes traduisent la perte de volume d'une atélectasie ?","o":["Un champ pulmonaire plus petit du même côté","Un rapprochement du médiastin, des hiles, du diaphragme","Des espaces intercostaux diminués","Une hyperinsufflation du parenchyme voisin","Une déviation du médiastin vers l'autre côté"],"r":[0,1,2,3],"e":"Quatre signes de perte de volume. La déviation controlatérale caractérise au contraire l'épanchement pleural et le pneumothorax compressif.","s":3},{"q":"Sur quelles étendues une atélectasie peut-elle porter ?","o":["Un segment","Un lobe","Un poumon entier","Une scissure"],"r":[0,1,2],"e":"L'opacité en nappe de l'atélectasie peut concerner un segment, un lobe ou un poumon entier.","s":3},{"q":"Quels volumes un épanchement pleural peut-il atteindre ?","o":["Petit","Moyen","Grand","Toujours massif"],"r":[0,1,2],"e":"L'épanchement pleural peut être de petit, moyen ou grand volume.","s":3},{"q":"Quel effet un épanchement pleural a-t-il sur la limite des structures voisines ?","o":["Il l'efface","Il l'accentue","Il la déplace vers le haut uniquement","Il n'a aucun effet"],"r":0,"e":"L'épanchement donne une image en nappe de densité moyenne qui efface la limite des structures voisines, avec déviation controlatérale des structures médianes.","s":3},{"q":"Que voit-on précisément dans un pneumothorax ?","o":["La plèvre viscérale, limite du poumon","Une absence de trame pulmonaire","Une transparence augmentée","Un bronchogramme aérien dans l'opacité"],"r":[0,1,2],"e":"Plèvre viscérale visible, absence de trame et hypertransparence. Le bronchogramme aérien est un signe de pneumonie alvéolaire.","s":3},{"q":"Qu'est-ce qui définit un hydropneumothorax ?","o":["Un pneumothorax et un épanchement associés, avec niveau hydro-aérique","Un pneumothorax compressif isolé, avec déviation du médiastin vers l'autre côté","Un épanchement purulent, avec une opacité en nappe épaisse","Un abcès vidangé, avec une cavité ronde dans le parenchyme"],"r":0,"e":"L'hydropneumothorax associe air et liquide dans la cavité pleurale, ce qui crée un niveau hydro-aérique.","s":3},{"q":"Quels signes de distension accompagnent l'emphysème pulmonaire ?","o":["Hypertransparence","Coupoles diaphragmatiques en position basse","Augmentation du diamètre antéro-postérieur","Augmentation de l'espace clair rétro-sternal","Diminution de l'indice phréno-cinétique","Une élévation des coupoles diaphragmatiques"],"r":[0,1,2,3,4],"e":"Les cinq signes, avec une réduction ou une absence de la trame pulmonaire.","s":3},{"q":"Quelle est la forme de l'opacité d'un abcès après vidange partielle ?","o":["Un contour inférieur arrondi et une limite supérieure rectiligne","Une opacité homogène parfaitement ronde, sans niveau visible","Une image en nappe de densité moyenne, effaçant la coupole","Des images réticulaires fines, autour de la cavité vidée"],"r":0,"e":"Après vidange partielle, l'abcès donne un contour inférieur arrondi et une limite supérieure rectiligne horizontale : c'est le niveau hydro-aérique.","s":3},{"q":"Quelles pathologies s'accompagnent d'une augmentation de volume de l'hémithorax ?","o":["L'épanchement pleural","Le pneumothorax","L'atélectasie","La pneumonie"],"r":[0,1],"e":"Épanchement pleural et pneumothorax augmentent le volume. L'atélectasie le diminue, la pneumonie le laisse inchangé.","s":3},{"q":"Quelles pathologies ne s'accompagnent d'aucune déviation médiastinale ?","o":["La pneumonie","L'emphysème","L'abcès","L'épanchement"],"r":[0,1,2],"e":"Pneumonie, emphysème et abcès ne dévient pas le médiastin. L'épanchement le dévie du côté controlatéral, l'atélectasie l'attire du côté homolatéral.","s":3},{"q":"Quelle est la densité radiologique d'un épanchement pleural ?","o":["Moyenne, intermédiaire","Maximale, comme l'os","Minimale, comme l'air","Variable, selon la position"],"r":0,"e":"L'épanchement donne une image en nappe de densité moyenne.","s":3},{"q":"Un patient présente une opacité en nappe avec attraction du médiastin du côté atteint. Que suspectez-vous ?","o":["Une atélectasie","Un épanchement pleural","Un pneumothorax","Une pneumonie"],"r":0,"e":"Opacité avec perte de volume et rapprochement des structures voisines du côté atteint : c'est l'atélectasie. L'épanchement, lui, repousse le médiastin du côté opposé.","s":3},{"q":"Un patient présente une hypertransparence unilatérale avec absence de trame et déviation du médiastin du côté opposé. Que suspectez-vous ?","o":["Un pneumothorax compressif","Un emphysème bulleux diffus","Une atélectasie lobaire","Un abcès pulmonaire vidangé"],"r":0,"e":"Hypertransparence, absence de trame et déviation controlatérale signent un pneumothorax compressif. L'emphysème est bilatéral et ne dévie pas le médiastin.","s":3},{"q":"Qu'est-ce qui distingue radiologiquement une pneumonie d'une atélectasie ?","o":["La pneumonie ne perd pas de volume, l'atélectasie en perd","La pneumonie est hypertransparente, l'atélectasie opaque","L'atélectasie dévie le médiastin vers l'autre côté, pas la pneumonie","La pneumonie donne un niveau hydro-aérique, pas l'atélectasie"],"r":0,"e":"Les deux donnent une opacité, mais seule l'atélectasie s'accompagne d'une perte de volume, avec rapprochement des structures voisines.","s":3},{"q":"Que traduit une hyperinsufflation du parenchyme voisin d'une opacité ?","o":["Une compensation d'une perte de volume, en faveur d'une atélectasie","Un emphysème diffus, avec destruction alvéolaire des deux poumons","Un épanchement pleural, avec déviation controlatérale","Un abcès pulmonaire, avec niveau hydro-aérique dans la cavité"],"r":0,"e":"L'hyperinsufflation compensatrice du parenchyme voisin fait partie des signes de perte de volume de l'atélectasie.","s":3},{"q":"Quelle image radiologique correspond à une condensation alvéolaire avec bronchogramme aérien ?","o":["L'aspect alvéolaire de la pneumonie","L'aspect interstitiel de la pneumonie","L'atélectasie d'un lobe avec perte de volume","L'abcès pulmonaire vidangé"],"r":0,"e":"L'aspect alvéolaire associe condensation, bords bien délimités et bronchogramme aérien, sans perte de volume.","s":3},{"q":"Quelle est la valeur normale du pH artériel ?","o":["7,35 à 7,45","7,25 à 7,35","7,45 à 7,55","7,00 à 7,20"],"r":0,"e":"Le métabolisme cellulaire ne fonctionne correctement que dans cet intervalle étroit.","s":4},{"q":"Quelle est la valeur normale de la PaCO₂ ?","o":["35 à 45 mmHg","22 à 28 mmHg","80 à 100 mmHg","50 à 60 mmHg"],"r":0,"e":"22 à 28 correspond au HCO₃⁻ en mmol/L, et 80 à 100 mmHg à la PaO₂.","s":4},{"q":"Quelle est la valeur normale du bicarbonate ?","o":["22 à 28 mmol/L","35 à 45 mmol/L","7,35 à 7,45 mmol/L","80 à 100 mmol/L"],"r":0,"e":"Le HCO₃⁻ est la composante métabolique, régulée par le rein.","s":4},{"q":"Quel organe régule le CO₂ ?","o":["Le poumon","Le rein","Le foie","La rate"],"r":0,"e":"Le poumon régule le CO₂ (acide), le rein régule le HCO₃⁻ (base).","s":4},{"q":"Quel organe régule les bicarbonates ?","o":["Le rein","Le poumon","Le cœur","Le pancréas"],"r":0,"e":"Le rein augmente ou diminue la rétention de bicarbonates dans le sang.","s":4},{"q":"Que se passe-t-il lors d'une hyperventilation ?","o":["Plus de libération de CO₂, sang moins acide","Moins de libération de CO₂, sang plus acide","Plus de rétention de bicarbonates","Moins de rétention de bicarbonates"],"r":0,"e":"L'hypoventilation fait l'inverse : moins de CO₂ libéré, sang plus acide.","s":4},{"q":"Comment appelle-t-on un pH inférieur à 7,35 ?","o":["Une acidémie","Une alcalémie","Une normoxémie","Une hypercapnie"],"r":0,"e":"Acidémie = sang trop acide, correspondant à une acidose.","s":4},{"q":"Quel profil correspond à une acidose respiratoire ?","o":["pH bas, PaCO₂ élevée","pH bas, HCO₃⁻ bas","pH élevé, PaCO₂ basse","pH élevé, HCO₃⁻ élevé"],"r":0,"e":"L'acidose respiratoire est liée à une hypoventilation ; le rein compense en augmentant le HCO₃⁻.","s":4},{"q":"Quel profil correspond à une acidose métabolique ?","o":["pH bas, HCO₃⁻ bas, PaCO₂ normale","pH bas, HCO₃⁻ normal, PaCO₂ élevée","pH élevé, HCO₃⁻ élevé, PaCO₂ normale","pH élevé, HCO₃⁻ normal, PaCO₂ basse"],"r":0,"e":"L'acidose lactique après un effort exténuant en est un exemple typique.","s":4},{"q":"Quel profil correspond à une alcalose respiratoire ?","o":["pH élevé, PaCO₂ basse","pH élevé, HCO₃⁻ élevé","pH bas, PaCO₂ élevée","pH bas, HCO₃⁻ bas"],"r":0,"e":"C'est l'alcalose d'hyperventilation, par exemple lors d'une crise d'anxiété avec polypnée.","s":4},{"q":"Quel profil correspond à une alcalose métabolique ?","o":["pH élevé, HCO₃⁻ élevé, PaCO₂ normale","pH élevé, HCO₃⁻ normal, PaCO₂ basse","pH bas, HCO₃⁻ bas, PaCO₂ normale","pH bas, HCO₃⁻ normal, PaCO₂ élevée"],"r":0,"e":"Exemple : vomissements répétés avec perte d'acide chlorhydrique.","s":4},{"q":"Comment le rein compense-t-il une acidose respiratoire ?","o":["En augmentant le HCO₃⁻","En diminuant le HCO₃⁻","En augmentant la PaCO₂","En diminuant la PaCO₂"],"r":0,"e":"Le rein ajoute du bicarbonate au sang pour ramener le pH vers la normale.","s":4},{"q":"Comment le poumon compense-t-il une acidose métabolique ?","o":["En diminuant la PaCO₂","En augmentant la PaCO₂","En augmentant le HCO₃⁻","En diminuant le HCO₃⁻"],"r":0,"e":"Le poumon hyperventile pour éliminer du CO₂ acide.","s":4},{"q":"Une gazométrie montre pH 7,32, PaCO₂ 55, HCO₃⁻ 24. De quoi s'agit-il ?","o":["Une acidose respiratoire non compensée","Une acidose métabolique","Une alcalose respiratoire","Une acidose respiratoire compensée"],"r":0,"e":"Le HCO₃⁻ est encore normal : la compensation rénale n'a pas encore eu lieu.","s":4},{"q":"Une gazométrie montre pH 7,34, PaCO₂ 55, HCO₃⁻ 30. De quoi s'agit-il ?","o":["Une acidose respiratoire en compensation","Une alcalose métabolique non compensée","Une acidose métabolique avec compensation respiratoire","Un état normal, sans trouble acido-basique"],"r":0,"e":"Le HCO₃⁻ a augmenté et le pH s'est rapproché de la normale : la compensation rénale est en cours.","s":4},{"q":"Quelle est la limite inférieure normale de la PaO₂ ?","o":["80 mmHg","60 mmHg","100 mmHg","40 mmHg"],"r":0,"e":"En dessous de 80 mmHg on parle d'hypoxémie ; la normoxémie se situe entre 80 et 100 mmHg.","s":4},{"q":"Une PaO₂ entre 60 et 80 mmHg correspond à :","o":["Une hypoxémie légère","Une normoxémie","Une hypoxémie modérée","Une hypoxémie grave"],"r":0,"e":"Modérée entre 40 et 60, grave en dessous de 40 mmHg.","s":4},{"q":"Une PaO₂ inférieure à 40 mmHg correspond à :","o":["Une hypoxémie grave","Une hypoxémie modérée","Une hypoxémie légère","Une normoxémie"],"r":0,"e":"C'est le seuil le plus bas de la classification de l'oxygénation artérielle.","s":4},{"q":"À quelle PaO₂ correspond une SatO₂ de 89 % ?","o":["60 mmHg","80 mmHg","100 mmHg","40 mmHg"],"r":0,"e":"SatO₂ 89 % ↔ PaO₂ 60 mmHg : hypoxémie modérée.","s":4},{"q":"À quelle SatO₂ correspond une PaO₂ de 40 mmHg ?","o":["75 %","89 %","96 %","50 %"],"r":0,"e":"C'est le niveau d'hypoxémie grave, correspondant aussi au sang veineux.","s":4},{"q":"Qu'est-ce qu'une insuffisance respiratoire de type I ?","o":["Une hypoxémie avec normocapnie","Une hypoxémie avec hypercapnie","Une hypercapnie isolée","Une alcalose respiratoire"],"r":0,"e":"L'IR partielle (type I) associe hypoxémie et normocapnie.","s":4},{"q":"Qu'est-ce qu'une insuffisance respiratoire de type II ?","o":["Une hypoxémie avec hypercapnie","Une hypoxémie avec normocapnie","Une hypocapnie isolée","Une acidose métabolique"],"r":0,"e":"L'IR globale (type II) associe hypoxémie et hypercapnie.","s":4},{"q":"Quelle est la première étape de la classification systématique de l'équilibre acido-basique ?","o":["Vérifier le pH","Vérifier la PaCO₂","Vérifier le HCO₃⁻","Vérifier la SatO₂"],"r":0,"e":"pH → PaCO₂ (composante respiratoire) → HCO₃⁻ (composante métabolique) → confirmer la compensation.","s":4},{"q":"Quelle est la dernière étape de la classification ?","o":["Confirmer que la composante non causale a bien répondu","Vérifier la PaO₂ pour classer l'hypoxémie, de légère à sévère","Vérifier le pH pour savoir s'il y a acidose ou alcalose","Calculer le trou anionique à partir des électrolytes"],"r":0,"e":"Il s'agit de confirmer la compensation.","s":4},{"q":"PaCO₂ élevée + pH bas + bicarbonates normaux : la situation est :","o":["Aiguë","Chronique","Compensée","Normale"],"r":0,"e":"En situation chronique, les bicarbonates ont eu le temps de s'élever et le pH est normal ou peu diminué.","s":4},{"q":"PaCO₂ élevée + pH normal + bicarbonates élevés : la situation est :","o":["Chronique","Aiguë","Non compensée","Métabolique pure"],"r":0,"e":"Le rein a eu le temps de compenser, ce qui signe la chronicité.","s":4},{"q":"Quel est le mécanisme de l'alcalose d'hyperventilation ?","o":["Une élimination excessive de CO₂","Une rétention de bicarbonates","Une perte d'acide chlorhydrique","Une production d'acide lactique"],"r":0,"e":"L'anxiété peut provoquer une polypnée avec chute de la PaCO₂.","s":4},{"q":"Quel est le mécanisme de l'alcalose métabolique après vomissements répétés ?","o":["La perte d'acide chlorhydrique fait pencher le pH vers le bicarbonate","Une hyperventilation compensatrice fait baisser la PaCO₂ et monter le pH","Une rétention de CO₂ fait monter les bicarbonates dans le sang","Une production de lactate fait monter le pH par effet tampon"],"r":0,"e":"Le suc gastrique perdu contient de l'acide chlorhydrique.","s":4},{"q":"À quel pH correspond une PaCO₂ de 60 mmHg selon le tableau du cours ?","o":["7,2","7,4","7,3","7,0"],"r":0,"e":"PaCO₂ 40 → pH 7,4 ; 50 → 7,3 ; 60 → 7,2 ; 70 → 7,1 ; 80 → 7,0 ; 90 → 6,9.","s":4},{"q":"Quelle est la valeur normale minimale de la SatO₂ ?","o":["> 90 %","> 80 %","> 95 %","> 75 %"],"r":0,"e":"C'est la valeur retenue dans le tableau des normes de la gazométrie.","s":4},{"q":"Que permet de déterminer la gazométrie artérielle ?","o":["Si le patient est bien oxygéné","L'équilibre acido-basique","Le volume courant expiré","La compliance du poumon"],"r":[0,1],"e":"La gazométrie renseigne sur l'oxygénation et sur l'équilibre acido-basique, respiratoire et métabolique. L'équilibre est à la fois respiratoire et métabolique.","s":4},{"q":"Pourquoi la régulation du pH est-elle si importante ?","o":["Le métabolisme cellulaire ne marche que dans un intervalle étroit, de 7,35 à 7,45","Le pH détermine directement la saturation artérielle en oxygène, de 0 à 100 %","Le pH règle la fréquence cardiaque, de 60 à 100 battements par minute","Le pH mesure l'oxygénation du sang, de 80 à 100 mmHg"],"r":0,"e":"Le métabolisme des cellules n'est correct que dans l'intervalle étroit 7,35-7,45, d'où l'importance des systèmes tampons.","s":4},{"q":"Que se passe-t-il lors d'une hypoventilation ?","o":["Moins de libération de CO₂, donc un sang plus acide","Plus de libération de CO₂, donc un sang moins acide","Une rétention de bicarbonates","Une élimination de bicarbonates"],"r":0,"e":"L'hypoventilation diminue l'élimination du CO₂ : le sang devient plus acide. L'hyperventilation fait l'inverse.","s":4},{"q":"Comment le rein rend-il le sang plus basique ?","o":["En augmentant la rétention de bicarbonates","En diminuant la rétention de bicarbonates","En éliminant du CO₂","En retenant du CO₂"],"r":0,"e":"Le rein régule la base : plus de rétention de bicarbonates rend le sang plus basique, moins de rétention le rend moins basique.","s":4},{"q":"Quel est le profil d'une alcalose respiratoire décompensée ?","o":["pH augmenté, PaCO₂ diminuée, HCO₃⁻ normal","pH augmenté, PaCO₂ normale, HCO₃⁻ augmenté","pH diminué, PaCO₂ augmentée, HCO₃⁻ normal","pH diminué, PaCO₂ normale, HCO₃⁻ diminué"],"r":0,"e":"Alcalose respiratoire par hyperventilation : pH ↑, PaCO₂ ↓, HCO₃⁻ normal. Le rein compense en diminuant les bicarbonates.","s":4},{"q":"Comment le rein compense-t-il une alcalose respiratoire ?","o":["En diminuant les bicarbonates","En augmentant les bicarbonates","En augmentant la PaCO₂","En diminuant la PaCO₂"],"r":0,"e":"Acidose respiratoire → le rein augmente le HCO₃⁻. Alcalose respiratoire → le rein le diminue.","s":4},{"q":"Comment le poumon compense-t-il une alcalose métabolique ?","o":["En augmentant la PaCO₂","En diminuant la PaCO₂","En augmentant le HCO₃⁻","En diminuant le HCO₃⁻"],"r":0,"e":"Alcalose métabolique (HCO₃⁻ ↑) → le poumon retient du CO₂, donc la PaCO₂ augmente. Acidose métabolique → la PaCO₂ diminue.","s":4},{"q":"Une gazométrie montre pH 7,31, PaCO₂ 40, HCO₃⁻ 18 après un effort exténuant. De quoi s'agit-il ?","o":["Une acidose métabolique, de type lactique","Une acidose respiratoire, de type hypoventilation aiguë","Une alcalose métabolique, de type perte d'acide","Une alcalose respiratoire, de type hyperventilation"],"r":0,"e":"pH bas, PaCO₂ normale et bicarbonates bas : c'est une acidose métabolique, ici lactique, liée à un effort chez une personne mal préparée.","s":4},{"q":"Une gazométrie montre pH 7,50, PaCO₂ 31, HCO₃⁻ 23 chez un patient anxieux. De quoi s'agit-il ?","o":["Une alcalose respiratoire, d'hyperventilation","Une alcalose métabolique, de vomissements","Une acidose respiratoire, d'hypoventilation","Une acidose métabolique, d'effort exténuant et prolongé"],"r":0,"e":"pH haut, PaCO₂ basse et bicarbonates normaux : alcalose respiratoire par hyperventilation, typique de l'anxiété avec polypnée.","s":4},{"q":"Une gazométrie montre pH 7,51, PaCO₂ 38, HCO₃⁻ 32 après vomissements répétés. De quoi s'agit-il ?","o":["Une alcalose métabolique, par perte d'acide chlorhydrique","Une alcalose respiratoire, par hyperventilation anxieuse","Une acidose métabolique, par production de lactate à l'effort","Une acidose respiratoire compensée, par rétention de CO₂"],"r":0,"e":"pH haut, PaCO₂ normale et bicarbonates hauts : alcalose métabolique, ici par perte d'acide chlorhydrique due aux vomissements.","s":4},{"q":"À quelle SatO₂ correspond une PaO₂ de 100 mmHg ?","o":["97,5 %","96 %","89 %","75 %"],"r":0,"e":"PaO₂ 100 → SatO₂ 97,5 % (sang artériel). PaO₂ 80 → 96 % (limite inférieure). PaO₂ 60 → 89 %. PaO₂ 40 → 75 %.","s":4},{"q":"À quelle PaO₂ correspond une SatO₂ de 50 % ?","o":["27 mmHg","40 mmHg","60 mmHg","80 mmHg"],"r":0,"e":"SatO₂ 50 % correspond à une PaO₂ de 27 mmHg, valeur de sang veineux.","s":4},{"q":"Quelle est la plage normale de la PaO₂ ?","o":["Entre 80 et 100 mmHg","Entre 60 et 80 mmHg","Entre 40 et 60 mmHg","Entre 120 et 150 mmHg"],"r":0,"e":"Normoxémie : PaO₂ > 80 mmHg, normalement entre 80 et 100.","s":4},{"q":"Une PaO₂ entre 40 et 60 mmHg correspond à quelle classification ?","o":["Une hypoxémie modérée","Une hypoxémie légère","Une hypoxémie grave","Une normoxémie"],"r":0,"e":"60-80 : légère. 40-60 : modérée. < 40 : grave.","s":4},{"q":"Quelles sont les deuxième et troisième étapes de la méthode de classification en 4 temps ?","o":["Vérifier la PaCO₂, la composante respiratoire","Vérifier le HCO₃⁻, la composante métabolique","Vérifier le pH, pour savoir s'il est acide ou basique","Confirmer la compensation par l'autre composante"],"r":[0,1],"e":"1. pH. 2. PaCO₂ (respiratoire). 3. HCO₃⁻ (métabolique). 4. Confirmer la compensation.","s":4},{"q":"Que cherche-t-on à la quatrième étape de la méthode ?","o":["Si la composante non causale a répondu de façon adéquate","Si le pH est revenu entre 7,35 et 7,45, quelle que soit la cause","Si la PaO₂ est basse, ce qui signe une insuffisance respiratoire","Si la SatO₂ dépasse 90 %, au repos et en air ambiant"],"r":0,"e":"La quatrième étape confirme la compensation : la composante non causale a-t-elle répondu de façon adéquate ?","s":4},{"q":"Un patient a pH 7,53, pCO₂ 28,2, pO₂ 119, HCO₃ 23,4. Quel est le trouble ?","o":["Une alcalose respiratoire","Une alcalose métabolique","Une acidose respiratoire","Un équilibre normal"],"r":0,"e":"pH élevé, PaCO₂ basse et bicarbonates normaux : alcalose respiratoire — cohérent avec un patient ventilé, ici hyperventilé.","s":4},{"q":"Un patient a pH 7,26, pCO₂ 54,4, pO₂ 64,8, HCO₃ 26,7. Quel est le trouble ?","o":["Une acidose respiratoire avec hypoxémie modérée","Une acidose métabolique avec hypoxémie sévère","Une alcalose respiratoire avec normoxémie","Un équilibre acido-basique normal"],"r":0,"e":"pH bas, PaCO₂ haute, bicarbonates à peine élevés : acidose respiratoire peu compensée. La PaO₂ à 64,8 signe une hypoxémie légère à modérée, avec hypercapnie : insuffisance respiratoire de type II.","s":4},{"q":"Un patient a pH 7,21, pCO₂ 38,8, pO₂ 100, HCO₃ 19,5. Quel est le trouble ?","o":["Une acidose métabolique","Une acidose respiratoire","Une alcalose métabolique","Une alcalose respiratoire"],"r":0,"e":"pH bas, PaCO₂ normale et bicarbonates bas : acidose métabolique, sans hypoxémie associée ici.","s":4},{"q":"Un patient a pH 7,60, pCO₂ 40,2, pO₂ 74, HCO₃ 31,7. Quel est le trouble ?","o":["Une alcalose métabolique","Une alcalose respiratoire","Une acidose métabolique","Une acidose respiratoire"],"r":0,"e":"pH élevé, PaCO₂ normale et bicarbonates élevés : alcalose métabolique. La PaO₂ à 74 traduit une hypoxémie légère.","s":4},{"q":"Que mesure l'épreuve fonctionnelle respiratoire ?","o":["Le volume d'air inspiré ou expiré en fonction du temps","La pression artérielle en oxygène, sur un prélèvement","La saturation en oxygène, au doigt et au repos, puis à l'effort","Le débit cardiaque, au repos et à l'effort"],"r":0,"e":"On peut mesurer le volume ou le débit.","s":5},{"q":"Quels sont les deux types de manœuvres en spirométrie ?","o":["Lentes et forcées","Inspiratoires et expiratoires","Actives et passives","Statiques et dynamiques"],"r":0,"e":"Les manœuvres lentes mesurent volumes et capacités, les forcées donnent CVF, VEMS et DEP.","s":5},{"q":"Quel volume ne peut PAS être mesuré par la spirométrie simple ?","o":["Le volume résiduel","Le volume courant","Le volume de réserve inspiratoire","Le volume de réserve expiratoire"],"r":0,"e":"Le volume résiduel figure parmi les volumes pulmonaires mais n'est pas mobilisable, donc non mesurable par spirométrie.","s":5},{"q":"Quelle capacité n'est PAS listée dans le cours ?","o":["La capacité de diffusion","La capacité vitale","La capacité inspiratoire","La capacité résiduelle fonctionnelle"],"r":0,"e":"Les capacités citées sont vitale, inspiratoire, résiduelle fonctionnelle et pulmonaire totale.","s":5},{"q":"Quelle contre-indication temporelle est citée pour la spirométrie ?","o":["Un infarctus du myocarde de moins d'un mois","Une pneumonie de moins d'un an, même guérie","Une chirurgie thoracique de moins de cinq ans","Une grossesse au premier trimestre"],"r":0,"e":"Il existe des contre-indications absolues et relatives ; l'IDM < 1 mois est explicitement mentionné.","s":5},{"q":"Quelle n'est PAS une indication de la spirométrie ?","o":["Le calcul du débit cardiaque","Le diagnostic des troubles ventilatoires","La surveillance d'une maladie respiratoire chronique","La santé publique, par le dépistage"],"r":0,"e":"Les indications sont le diagnostic, l'évaluation des dysfonctions/déficiences, la surveillance et la santé publique.","s":5},{"q":"Que signifie VEMS ?","o":["Volume expiratoire maximal en 1 seconde","Volume expiratoire moyen sur 6 secondes","Volume ventilatoire de la même seconde","Ventilation expiratoire maximale sur 6 s"],"r":0,"e":"Le VEMS est l'une des quatre mesures principales avec CVF, VEMS/CVF et DEP.","s":5},{"q":"Quelles sont les deux courbes affichées par le spiromètre ?","o":["Débit-volume et volume-temps","Pression-volume et débit-temps","Débit-temps et pression-temps","Volume-pression et débit-volume"],"r":0,"e":"Ce sont les deux modes d'affichage classiques.","s":5},{"q":"Quel délai minimal doit-on respecter pour le tabac avant le test ?","o":["1 heure","24 heures","10 minutes","1 semaine"],"r":0,"e":"Il faut éviter le tabac dans l'heure précédant l'épreuve, ainsi que l'exercice vigoureux, la caféine, l'alcool et les repas.","s":5},{"q":"Pourquoi mesure-t-on le poids et la taille le jour du test ?","o":["Ce sont des déterminants de la taille pulmonaire","Ils servent à calculer l'IMC du patient","Ils servent à ajuster la dose de bronchodilatateur","Ils servent à évaluer la sévérité de l'obstruction"],"r":0,"e":"Les valeurs prédites dépendent de la taille, de l'âge et du sexe.","s":5},{"q":"Quelle est la première étape de la manœuvre forcée ?","o":["Une inspiration maximale","Une expiration explosive","Une apnée","Une inspiration lente"],"r":0,"e":"Inspiration maximale → expiration explosive → expiration complète 15 s → inspiration de restauration.","s":5},{"q":"Quelle est la durée maximale de l'expiration forcée ?","o":["15 secondes","6 secondes","2 secondes","30 secondes"],"r":0,"e":"Le plateau de la courbe volume-temps doit durer ≥ 6 s et le temps expiratoire forcé aller jusqu'à 15 s.","s":5},{"q":"Quelle est la durée minimale du plateau de la courbe volume-temps ?","o":["6 secondes","2 secondes","15 secondes","1 seconde"],"r":0,"e":"C'est un critère d'acceptabilité de la manœuvre.","s":5},{"q":"Quelle est la pause maximale entre l'inspiration maximale et l'expiration ?","o":["2 secondes","6 secondes","10 secondes","Aucune limite"],"r":0,"e":"Une pause trop longue altère la validité de la manœuvre forcée.","s":5},{"q":"Quel matériel évite les fuites d'air par le nez ?","o":["La pince nasale","L'embout buccal","Le filtre antibactérien","Le masque facial"],"r":0,"e":"Posture, embout buccal, pince nasale et contrôle des joues sont les points de vigilance.","s":5},{"q":"Quelle erreur ne figure PAS parmi les erreurs fréquentes citées ?","o":["Une inspiration trop lente avant la manœuvre","Un retard au démarrage de l'expiration forcée","Un effort expiratoire insuffisant, sans explosion","Une toux pendant la première seconde"],"r":0,"e":"Les erreurs citées sont : retard au démarrage, effort insuffisant, toux et fin précoce du débit expiratoire.","s":5},{"q":"Combien de mesures acceptables et reproductibles sont nécessaires au minimum ?","o":["3","1","5","8"],"r":0,"e":"On réalise 3 à 8 mesures, avec un minimum de 3 acceptables et reproductibles.","s":5},{"q":"Quel est le nombre maximal de mesures recommandé ?","o":["8","3","5","12"],"r":0,"e":"3 à 8 mesures sont réalisées lors d'une évaluation.","s":5},{"q":"Que détermine le test de réversibilité ?","o":["Le gain de débit après un bronchodilatateur","La capacité de diffusion du monoxyde de carbone à travers la membrane","Le volume résiduel après une expiration maximale","La force des muscles respiratoires, inspiratoires et expiratoires"],"r":0,"e":"Le choix porte sur un BD de courte ou longue durée d'action, sa dose et son mode d'administration.","s":5},{"q":"Quelle est la formule de la réponse au bronchodilatateur ?","o":["(VEMS post-BD − VEMS pré-BD) × 100 / valeur prédite","(VEMS post-BD − VEMS pré-BD) × 100 / VEMS pré-BD","(VEMS post-BD / CVF post-BD) × 100 / valeur prédite","(CVF post-BD − CVF pré-BD) × 100 / VEMS pré-BD mesuré"],"r":0,"e":"La valeur prédite est celle correspondant au sexe biologique et à l'âge.","s":5},{"q":"À partir de quel pourcentage la réversibilité est-elle considérée comme significative ?","o":["Plus de 10 %","Plus de 5 %","Plus de 20 %","Plus de 12 %"],"r":0,"e":"Le cours retient un seuil de 10 % sur le VEMS.","s":5},{"q":"Quel est le premier paramètre à évaluer dans l'interprétation ?","o":["Le rapport VEMS/CVF","La CVF seule, en litres","Le VEMS seul, en litres","Le DEP, en L/min"],"r":0,"e":"Ordre : VEMS/CVF → CVF → VEMS pour la sévérité → toujours considérer le post-BD.","s":5},{"q":"Quel paramètre évalue-t-on en deuxième dans l'interprétation ?","o":["La CVF","Le VEMS","Le DEP","Le volume résiduel"],"r":0,"e":"Le VEMS n'est évalué qu'ensuite, pour classer la sévérité d'une obstruction.","s":5},{"q":"À quoi sert le VEMS dans l'interprétation ?","o":["À classer la sévérité de l'obstruction","À poser le diagnostic d'obstruction","À évaluer la restriction","À mesurer la diffusion"],"r":0,"e":"Le diagnostic d'obstruction repose sur le rapport VEMS/CVF ; le VEMS en gradue la sévérité.","s":5},{"q":"En cas de test pré et post-BD, quel résultat faut-il considérer ?","o":["Toujours le résultat post-BD","Toujours le résultat pré-BD","La moyenne des deux","Le meilleur des deux"],"r":0,"e":"C'est la 4ᵉ règle d'interprétation énoncée dans le cours.","s":5},{"q":"Quelle référence internationale est citée pour la classification de l'obstruction ?","o":["GOLD 2024","NYHA","ASIA","GINA 2010"],"r":0,"e":"Le cours renvoie à GOLD 2024 pour la classification de sévérité de l'obstruction.","s":5},{"q":"Que doit-on vérifier concernant les prothèses le jour du test ?","o":["Leur présence, qui peut gêner l'étanchéité de l'embout","Leur date de pose, qui conditionne la validité de la mesure","Leur matériau, qui peut fausser la lecture du spiromètre","Rien de particulier, elles n'ont aucune incidence sur la manœuvre"],"r":0,"e":"C'est l'un des points à contrôler le jour du test, avec le poids, la taille et les signes et symptômes.","s":5},{"q":"Quelle consigne verbale correspond au début de l'expiration forcée ?","o":["« Explosivement »","« Continuez »","« Inspirez à fond »","« Encore, encore »"],"r":0,"e":"Les consignes s'enchaînent : inspiration maximale, puis expiration explosive, puis « continuez ».","s":5},{"q":"Que signifie CVF ?","o":["Capacité vitale forcée","Capacité ventilatoire fonctionnelle","Capacité de volume forcé","Coefficient ventilatoire final"],"r":0,"e":"La CVF est l'une des quatre mesures principales de la spirométrie.","s":5},{"q":"Quelle interprétation correspond à l'exemple 2 du cours ?","o":["Une restriction possible","Un tracé normal","Une obstruction modérée","Une réversibilité significative"],"r":0,"e":"Exemple 1 : normal ; exemple 2 : restriction possible ; exemple 3 : obstruction modérée ; exemple 4 : réversibilité > 10 %.","s":5},{"q":"Que mesure-t-on lors des manœuvres lentes de l'épreuve fonctionnelle respiratoire ?","o":["Les volumes et capacités en respiration contrôlée","La CVF, le VEMS et le DEP en expiration forcée","Le débit expiratoire de pointe seul, au peak flow","La capacité de diffusion du CO à travers la membrane"],"r":0,"e":"Manœuvres lentes : volumes et capacités en respiration contrôlée. Manœuvres forcées : spirométrie forcée avec CVF, VEMS et DEP.","s":5},{"q":"Quels volumes pulmonaires sont listés dans le cours ?","o":["Volume de réserve inspiratoire","Volume courant","Volume de réserve expiratoire","Volume résiduel","Capacité vitale"],"r":[0,1,2,3],"e":"Quatre volumes. La capacité vitale est une capacité, comme la capacité inspiratoire, la capacité résiduelle fonctionnelle et la capacité pulmonaire totale.","s":5},{"q":"Quelles capacités pulmonaires sont listées ?","o":["Capacité vitale","Capacité inspiratoire","Capacité résiduelle fonctionnelle","Capacité pulmonaire totale","Capacité de diffusion"],"r":[0,1,2,3],"e":"Les quatre capacités sont énumérées dans la fiche.","s":5},{"q":"Sur quoi se fonde l'indication d'une épreuve fonctionnelle respiratoire ?","o":["L'examen physique","Les symptômes","Les antécédents","Le seul âge du patient"],"r":[0,1,2],"e":"L'indication découle de l'examen physique, des symptômes et des antécédents.","s":5},{"q":"Quelles sont les indications de la spirométrie ?","o":["Le diagnostic","Les dysfonctions","La surveillance","La santé publique","Le dépistage du cancer"],"r":[0,1,2,3],"e":"Quatre indications : diagnostic, évaluation des dysfonctions et déficiences, surveillance et santé publique. Il s'agit des dysfonctions et des déficiences.","s":5},{"q":"Que signifie DEP ?","o":["Débit expiratoire de pointe","Débit expiratoire prolongé","Durée expiratoire prédite","Déficit expiratoire partiel"],"r":0,"e":"DEP = débit expiratoire de pointe, l'une des quatre mesures principales avec CVF, VEMS et VEMS/CVF.","s":5},{"q":"Que faut-il éviter avant une épreuve fonctionnelle respiratoire ?","o":["L'exercice vigoureux","Le tabac dans l'heure précédente","La caféine et l'alcool","Un repas","Le port de vêtements adaptés"],"r":[0,1,2,3],"e":"Exercice vigoureux, tabac dans l'heure, caféine, alcool et repas sont à éviter. Les vêtements adaptés sont au contraire recommandés.","s":5},{"q":"Que faut-il faire le jour du test, avant la manœuvre ?","o":["Mesurer le poids et la taille","Vérifier les prothèses","Rechercher signes et symptômes","Expliquer la manœuvre","Mesurer la saturation"],"r":[0,1,2,3],"e":"Les quatre actions précèdent la réalisation du test. Le poids et la taille sont des déterminants de la taille pulmonaire.","s":5},{"q":"Quelles sont les quatre étapes de la manœuvre forcée ?","o":["Inspiration maximale","Expiration explosive","Expiration complète, jusqu'à 15 s","Inspiration pour restaurer le volume","Apnée de dix secondes"],"r":[0,1,2,3],"e":"Les quatre étapes s'enchaînent dans cet ordre.","s":5},{"q":"Quels points de vigilance surveille-t-on pendant la manœuvre ?","o":["La posture","L'embout et le pince-nez","Les joues","La pause inspiration-expiration","La fréquence cardiaque"],"r":[0,1,2,3],"e":"Posture, embout buccal, pince nasale, joues et pause ≤ 2 s entre l'inspiration maximale et l'expiration.","s":5},{"q":"Quelles erreurs fréquentes invalident une manœuvre ?","o":["Un retard au démarrage","Un effort expiratoire insuffisant","Une toux","Une fin précoce du débit expiratoire","Une inspiration trop profonde"],"r":[0,1,2,3],"e":"Les quatre erreurs sont citées.","s":5},{"q":"Quels choix concernent le bronchodilatateur lors d'un test de réversibilité ?","o":["Sa durée d'action, courte ou longue","Sa dose","Son mode d'administration","Sa marque commerciale"],"r":[0,1,2],"e":"Le choix porte sur un BD de courte ou longue durée d'action, sa dose et son mode d'administration.","s":5},{"q":"Par quoi divise-t-on la différence de VEMS dans le calcul de la réponse au bronchodilatateur ?","o":["La valeur prédite pour le sexe biologique et l'âge","Le VEMS mesuré avant le bronchodilatateur","La CVF mesurée après le bronchodilatateur, au même moment","La capacité pulmonaire totale mesurée en pléthysmographie"],"r":0,"e":"Réponse au BD = (VEMS post-BD − VEMS pré-BD) × 100 / valeur prédite pour le sexe biologique et l'âge.","s":5},{"q":"Quand évalue-t-on le VEMS dans la séquence d'interprétation ?","o":["En troisième, en cas d'obstruction, pour en classer la sévérité","En premier, avant le rapport VEMS/CVF, pour dépister l'obstruction","En deuxième, juste après le rapport VEMS/CVF, pour la restriction","Jamais, car seul le rapport VEMS/CVF est interprété"],"r":0,"e":"1) VEMS/CVF, 2) CVF, 3) VEMS si trouble obstructif pour la sévérité, 4) toujours considérer le post-BD.","s":5},{"q":"Quelles références internationales encadrent l'épreuve fonctionnelle respiratoire ?","o":["Miller MR et al., 2005","Pellegrino R et al., 2005","Graham BL et al., 2019","Stanojevic S et al., 2022","GOLD COPD report, 2025"],"r":[0,1,2,3],"e":"Les quatre références sont citées en fin de fiche.","s":5},{"q":"Quelle interprétation correspond à l'exemple 3 du cours ?","o":["Une obstruction modérée, selon GOLD 2024","Un résultat normal, selon GOLD 2024","Une restriction possible, à confirmer par la CPT","Une variation significative du VEMS, de plus de 10 %"],"r":0,"e":"Exemple 1 : normal. Exemple 2 : restriction possible. Exemple 3 : obstruction modérée (GOLD 2024). Exemple 4 : variation > 10 % du VEMS, significative.","s":5},{"q":"Quel enchaînement de consignes verbales guide la manœuvre forcée ?","o":["« Inspirez à fond », puis « encore »","« Explosivement »","« Continuez »","« Retenez votre souffle »"],"r":[0,1,2],"e":"La séquence va de l'inspiration maximale à la poursuite de l'expiration, jusqu'au plateau de la courbe volume-temps (≥ 6 s) et un temps expiratoire forcé pouvant aller à 15 s.","s":5},{"q":"Que signifie CVF et pourquoi l'évalue-t-on en deuxième ?","o":["Capacité vitale forcée ; elle oriente vers la restriction, après le rapport","Capacité ventilatoire fonctionnelle ; elle mesure seule l'obstruction","Coefficient de ventilation forcée ; il se calcule avant le rapport VEMS/CVF","Capacité vitale fonctionnelle ; elle remplace le VEMS pour la sévérité"],"r":0,"e":"CVF = capacité vitale forcée. On évalue d'abord le rapport VEMS/CVF, puis la CVF, puis le VEMS en cas d'obstruction.","s":5},{"q":"Pourquoi mesure-t-on systématiquement le poids et la taille ?","o":["Ils déterminent la taille pulmonaire, donc les valeurs prédites","Ils servent à calculer la dose de bronchodilatateur à donner","Ils servent à choisir la taille de l'embout buccal et de la pince","Ils servent à estimer la durée du test, de cinq à quinze minutes"],"r":0,"e":"Poids et taille conditionnent la taille pulmonaire, donc les valeurs de référence auxquelles on compare les mesures.","s":5},{"q":"Pourquoi la pause entre l'inspiration maximale et l'expiration doit-elle rester courte ?","o":["Elle ne doit pas dépasser 2 s, sinon la manœuvre perd sa validité","Elle doit durer au moins 6 s, pour remplir toutes les alvéoles","Elle doit durer 15 s, pour stabiliser le volume pulmonaire","Sa durée est indifférente, seule l'expiration compte"],"r":0,"e":"La pause entre inspiration maximale et expiration doit rester inférieure ou égale à 2 secondes.","s":5},{"q":"Comment définit-on l'aspiration des voies aériennes ?","o":["Le retrait des sécrétions par un cathéter et une pression négative","L'insufflation d'air sous pression positive, par une sonde nasale","Le lavage bronchique au sérum physiologique, sous fibroscopie","La kinésithérapie de désencombrement manuelle, par des pressions thoraciques"],"r":0,"e":"Elle vise à favoriser la clairance, maintenir la perméabilité, améliorer l'oxygénation et prévenir les atélectasies.","s":6},{"q":"Quel objectif n'est PAS attribué à l'aspiration ?","o":["Améliorer la force des muscles respiratoires","Favoriser la clairance des voies aériennes","Maintenir la perméabilité des voies aériennes","Prévenir les atélectasies"],"r":0,"e":"Les quatre objectifs cités sont clairance, perméabilité, oxygénation et prévention des atélectasies.","s":6},{"q":"Quelle indication d'aspiration est visible sur le ventilateur ?","o":["Un aspect en dents de scie sur la courbe","Une augmentation de la PEP réglée sur la machine","Une baisse de la FiO₂ affichée par le ventilateur","Une alarme de volume courant bas"],"r":0,"e":"Les autres indications sont les bruits adventices à l'auscultation et les sécrétions visibles dans la voie aérienne artificielle.","s":6},{"q":"Quelle situation est une contre-indication à l'aspiration ?","o":["Un saignement nasal","Des bruits adventices","Des sécrétions visibles","Une hypersécrétion bronchique"],"r":0,"e":"Contre-indications : saignement nasal, chirurgie de la trachée, IDM et bronchospasme.","s":6},{"q":"Quelle contre-indication cardiaque est citée ?","o":["L'infarctus aigu du myocarde","L'hypertension artérielle","La fibrillation auriculaire chronique","L'insuffisance cardiaque stable"],"r":0,"e":"L'IDM figure parmi les contre-indications à l'aspiration.","s":6},{"q":"Quelle compétence est un prérequis à l'aspiration ?","o":["La compétence en auscultation","La compétence en radiologie","La compétence en prescription","La compétence chirurgicale"],"r":0,"e":"Il faut aussi savoir surveiller les signes vitaux, connaître l'anatomie et physiologie, utiliser les équipements et répondre aux événements indésirables.","s":6},{"q":"Quel type de gants est encouragé lorsque c'est possible ?","o":["Des gants stériles","Des gants en vinyle","Des gants de ménage","Aucun gant"],"r":0,"e":"L'hygiène des mains est systématique et l'usage de gants stériles ou chirurgicaux est encouragé.","s":6},{"q":"Quel lubrifiant est recommandé pour l'aspiration nasopharyngée ?","o":["Un lubrifiant à base d'eau","Une pommade grasse antiseptique","De la vaseline, à base d'huile minérale","Aucun lubrifiant, la sonde suffit"],"r":0,"e":"Le lubrifiant ou anesthésique doit être à base d'eau pour le nasopharynx.","s":6},{"q":"Quelle voie d'aspiration n'est PAS citée dans le cours ?","o":["La voie bronchique par fibroscopie","La voie nasopharyngée, par une narine","La sonde endotrachéale, chez l'intubé","La trachéotomie, par la canule"],"r":0,"e":"Les voies citées : nasopharyngée, oropharyngée, sonde endotrachéale, trachéotomie et cavité orale.","s":6},{"q":"Quelles doivent être les caractéristiques du cathéter d'aspiration ?","o":["Stérile, flexible, avec plus d'un orifice","Rigide, avec un orifice unique distal","Réutilisable, souple, avec un seul orifice","Stérile, rigide, avec un orifice latéral"],"r":0,"e":"Ces trois caractéristiques limitent le traumatisme muqueux.","s":6},{"q":"Quelle est la formule de calcul de la taille du cathéter ?","o":["(taille de la voie aérienne − 2) / 2","(taille de la voie aérienne + 2) × 2","taille de la voie aérienne / 3","(taille de la voie aérienne − 1) / 3"],"r":0,"e":"Pour les sécrétions épaisses, la taille maximale est (taille de la sonde − 1) × 2.","s":6},{"q":"Quelle taille de cathéter utilise-t-on pour l'aspiration naso ou oropharyngée ?","o":["10 ou 12","6 ou 8","14 ou 16","18 ou 20"],"r":0,"e":"C'est la taille recommandée pour ces voies.","s":6},{"q":"Quelle est la pression d'aspiration recommandée ?","o":["Inférieure à −200 mmHg","Supérieure à −200 mmHg","Exactement −300 mmHg","Entre −250 et −300 mmHg"],"r":0,"e":"Les guidelines antérieures indiquaient entre 100 et 150 mmHg.","s":6},{"q":"Quelle était la pression indiquée par les guidelines antérieures ?","o":["Entre 100 et 150 mmHg","Entre 200 et 250 mmHg","Entre 50 et 80 mmHg","Entre 300 et 350 mmHg"],"r":0,"e":"La recommandation actuelle est une pression inférieure à −200 mmHg.","s":6},{"q":"Quelle est la durée maximale d'une aspiration ?","o":["15 secondes","30 secondes","5 secondes","1 minute"],"r":0,"e":"Une durée supérieure augmente le risque de désaturation et de complications.","s":6},{"q":"Pourquoi le système fermé a-t-il été créé ?","o":["Pour éviter les inconvénients de la déconnexion de la sonde","Pour réduire le coût de chaque aspiration endotrachéale en réanimation","Pour augmenter le volume de sécrétions recueilli à chaque passage","Pour supprimer la nécessité de pré-oxygéner le patient ventilé"],"r":0,"e":"Les critères de choix portent ensuite sur les quantités recueillies, le coût et les complications.","s":6},{"q":"Que sait-on de l'instillation de sérum physiologique ?","o":["Elle ne doit pas être utilisée au quotidien, à cause de ses effets indésirables","Elle est recommandée à chaque aspiration, pour fluidifier les sécrétions épaisses","Elle est sans effet, ni bénéfique ni délétère, quel que soit le volume","Elle remplace la pré-oxygénation chez le patient ventilé"],"r":0,"e":"Elle semble augmenter la désaturation, les arythmies, la toux excessive, le bronchospasme et détacher des bactéries.","s":6},{"q":"Quel risque infectieux l'instillation de sérum physiologique fait-elle courir ?","o":["Détacher des bactéries dans la voie aérienne","Contaminer le circuit du ventilateur par le flacon de sérum ouvert","Provoquer une pneumopathie chimique par le sel","Aucun risque infectieux, le sérum étant stérile"],"r":0,"e":"C'est l'un des effets indésirables cités, avec la désaturation, les arythmies, la toux excessive et le bronchospasme.","s":6},{"q":"Si l'instillation de sérum physiologique est nécessaire, quel volume utiliser ?","o":["De faibles volumes","Au moins 10 mL","20 mL","Le volume n'importe pas"],"r":0,"e":"Le cours précise : si nécessaire, de faibles volumes.","s":6},{"q":"Comment définit-on l'aspiration superficielle ?","o":["Elle ne dépasse pas la longueur de la sonde endotrachéale","Elle s'arrête à 1 cm de la carène, après une première résistance","Elle ne dépasse pas le pharynx, en aspiration oropharyngée","Elle est réalisée sans pression négative, par simple drainage"],"r":0,"e":"L'aspiration profonde va au-delà de l'extrémité de la sonde.","s":6},{"q":"Comment réalise-t-on une aspiration profonde ?","o":["Au-delà de la sonde jusqu'à la résistance, retrait de 1 cm, puis le vide","Jusqu'à la résistance, puis aspiration immédiate, sans aucun retrait","Dans la longueur de la sonde, sans la dépasser de plus de 1 cm","En aspirant pendant toute la descente, jusqu'à la résistance de la carène"],"r":0,"e":"Le retrait de 1 cm évite le traumatisme direct de la muqueuse.","s":6},{"q":"Quelle complication traumatique l'aspiration peut-elle provoquer ?","o":["Une trachéite ou une perforation des fosses nasales","Une fracture costale, provoquée par la toux réflexe violente","Une atélectasie lobaire, provoquée par le vide trop fort","Un pneumothorax compressif, provoqué par le cathéter"],"r":0,"e":"Les mécanismes traumatiques provoquent traumatisme de la muqueuse, trachéite, lacération et perforation.","s":6},{"q":"Quelle complication cardiovasculaire est citée ?","o":["Les arythmies cardiaques","La bradycardie sinusale isolée","L'insuffisance cardiaque","L'hypotension artérielle"],"r":0,"e":"On observe aussi une augmentation de la fréquence cardiaque et de la pression artérielle.","s":6},{"q":"Quelles pressions peuvent augmenter lors d'une aspiration ?","o":["Systolique, moyenne, de perfusion cérébrale et intracrânienne","La pression systolique seule, de façon transitoire","La pression veineuse centrale seule, à la toux","Aucune pression, l'aspiration étant sans effet hémodynamique"],"r":0,"e":"C'est un point de vigilance particulier chez le patient neuro-critique.","s":6},{"q":"Quelle stratégie d'atténuation précède l'aspiration ?","o":["La pré-oxygénation à 100 % ou 0,2 au-dessus de la base","L'instillation systématique de 10 mL de sérum physiologique","L'augmentation de la pression d'aspiration à −200 mmHg","L'arrêt du monitorage pendant 1 minute, pour éviter les alarmes"],"r":0,"e":"Les autres stratégies sont ausculter, surveiller signes et symptômes, sédation adéquate et aspirer seulement si nécessaire.","s":6},{"q":"À quelle fréquence faut-il aspirer ?","o":["Uniquement quand c'est nécessaire, sans horaires fixes","Toutes les 2 heures, de façon systématique, jour et nuit","Toutes les 4 heures, de façon systématique, jour et nuit","À chaque changement d'équipe soignante"],"r":0,"e":"L'aspiration systématique à horaires fixes n'est pas recommandée.","s":6},{"q":"Quel matériel de surveillance est indispensable ?","o":["Le stéthoscope et l'oxymètre","Le tensiomètre uniquement","Le spiromètre","Le débitmètre de pointe"],"r":0,"e":"Ils permettent d'ausculter avant/après et de surveiller la saturation pendant le geste.","s":6},{"q":"Quel équipement de sécurité doit être disponible ?","o":["Un support vital de base ou avancé","Un défibrillateur uniquement","Un chariot de kinésithérapie","Un aspirateur de secours"],"r":0,"e":"Il figure dans la liste du matériel nécessaire, avec l'oxygène et le système de vide.","s":6},{"q":"En quelle année date la guideline AARC sur l'aspiration nasopharyngée ?","o":["2004","2010","2022","1992"],"r":0,"e":"2004 nasopharyngée, 2010 endotrachéale, 2022 voies aériennes artificielles.","s":6},{"q":"Quelle qualité relationnelle est explicitement citée comme prérequis ?","o":["Les soft skills : comprendre les besoins et humaniser","L'autonomie : savoir travailler seul, sans l'équipe","La rapidité : aspirer en moins de 5 secondes, quoi qu'il arrive","La force physique : tenir le patient pendant l'aspiration"],"r":0,"e":"Les soft skills figurent dans les prérequis, au même titre que les compétences techniques.","s":6},{"q":"Quels sont les quatre objectifs de l'aspiration des sécrétions ?","o":["Favoriser la clairance des voies aériennes","Maintenir leur perméabilité","Améliorer l'oxygénation","Prévenir les atélectasies","Réduire la fréquence cardiaque"],"r":[0,1,2,3],"e":"Clairance, perméabilité, oxygénation et prévention des atélectasies. L'aspiration a au contraire tendance à augmenter la fréquence cardiaque.","s":6},{"q":"De quelles années datent les guidelines AARC citées ?","o":["2004 pour le nasopharyngé","2010 pour l'endotrachéal","2022 pour les voies artificielles","1992 et 1993 pour les premières","2019 pour la trachéotomie"],"r":[0,1,2,3],"e":"Les quatre repères chronologiques sont donnés dans la fiche.","s":6},{"q":"Quelles sont les indications de l'aspiration ?","o":["Bruits adventices à l'auscultation","Sécrétions visibles dans la voie artificielle","Courbe en dents de scie au ventilateur","Horaire programmé dans le plan de soins"],"r":[0,1,2],"e":"Trois indications objectives. L'aspiration ne se fait jamais à horaires fixes, mais uniquement lorsqu'elle est nécessaire.","s":6},{"q":"Quelles sont les contre-indications de l'aspiration ?","o":["Saignement nasal","Chirurgie de la trachée","Infarctus aigu du myocarde","Bronchospasme","Sécrétions abondantes visibles"],"r":[0,1,2,3],"e":"Les quatre contre-indications sont citées.","s":6},{"q":"Quelles compétences le soignant doit-il posséder avant d'aspirer ?","o":["L'auscultation","La surveillance des signes vitaux","L'anatomie et la physiologie","La réponse aux événements indésirables","Les soft skills et l'humanisation","La lecture de l'électrocardiogramme"],"r":[0,1,2,3,4],"e":"Les cinq prérequis sont énumérés, avec la compétence à utiliser les équipements.","s":6},{"q":"Quel matériel faut-il réunir pour une aspiration ?","o":["Stéthoscope et oxymètre","Lunettes, gants, masque, tenue","Oxygène, vide, tubulure, cathéter","Lubrifiant ou anesthésique local","Support vital de base ou avancé","Spiromètre portable et embouts"],"r":[0,1,2,3,4],"e":"Le matériel complet est énuméré dans la fiche.","s":6},{"q":"Quelles voies d'aspiration sont décrites ?","o":["Nasopharyngée et oropharyngée","Sonde endotrachéale","Trachéotomie","Cavité orale","Voie transcricoïdienne"],"r":[0,1,2,3],"e":"Cinq voies : nasopharyngée, oropharyngée, sonde endotrachéale, trachéotomie et cavité orale.","s":6},{"q":"Quelle formule donne la taille MAXIMALE de cathéter en cas de sécrétions épaisses ?","o":["(taille de la sonde − 1) × 2","(taille de la voie aérienne − 2) / 2","taille de la sonde / 2","taille 10 ou 12"],"r":0,"e":"Sécrétions épaisses : (taille de la sonde − 1) × 2 donne la taille maximale. La formule générale est (taille de la voie aérienne − 2) / 2.","s":6},{"q":"Sur quels critères choisit-on entre système ouvert et fermé ?","o":["Les quantités qu'ils recueillent","Leur coût","Leurs complications","La couleur du dispositif"],"r":[0,1,2],"e":"Trois critères de choix : quantités recueillies, coût et complications. Le système fermé évite les inconvénients de la déconnexion de la sonde endotrachéale.","s":6},{"q":"Quels effets indésirables sont attribués à l'instillation de sérum physiologique ?","o":["Désaturation en oxygène","Arythmies cardiaques","Toux excessive, bronchospasme","Bactéries détachées dans la voie","Hypertension artérielle prolongée"],"r":[0,1,2,3],"e":"Ces quatre effets expliquent qu'elle ne doive pas être utilisée au quotidien ; si elle est nécessaire, on emploie de faibles volumes.","s":6},{"q":"Quelles complications traumatiques l'aspiration peut-elle provoquer ?","o":["Traumatisme de la muqueuse","Trachéite","Lacération ou perforation nasale","Fracture costale"],"r":[0,1,2],"e":"Traumatisme muqueux, trachéite, lacération et perforation des fosses nasales et du pharynx.","s":6},{"q":"Quelles pressions peuvent s'élever lors d'une aspiration ?","o":["La pression artérielle systolique","La pression artérielle moyenne","La pression de perfusion cérébrale","La pression intracrânienne","La pression partielle en oxygène"],"r":[0,1,2,3],"e":"Les quatre pressions peuvent augmenter, ce qui explique la prudence chez le patient neurologique.","s":6},{"q":"Quelles complications non mécaniques accompagnent l'aspiration ?","o":["Désaturation en oxygène","Anxiété","Arythmies cardiaques","Hypothermie"],"r":[0,1,2],"e":"Désaturation, anxiété et arythmies, avec l'augmentation de la fréquence cardiaque et des pressions.","s":6},{"q":"Quel niveau de pré-oxygénation est recommandé avant une aspiration ?","o":["100 % ou 0,2 au-dessus du niveau de base","21 %, soit l'air ambiant sans oxygène ajouté","50 % systématiquement, quel que soit le patient","Aucune pré-oxygénation, pour éviter l'hyperoxie"],"r":0,"e":"La pré-oxygénation se fait à 100 % ou 0,2 au-dessus du niveau de base, parmi les stratégies d'atténuation des complications.","s":6},{"q":"Quelles stratégies permettent d'atténuer les complications de l'aspiration ?","o":["Ausculter","Surveiller les signes","Discuter la sédation en équipe","Pré-oxygéner","Aspirer à heures fixes"],"r":[0,1,2,3],"e":"Auscultation, surveillance, sédation discutée avec l'équipe, pré-oxygénation, et aspiration uniquement lorsque nécessaire.","s":6},{"q":"Pourquoi discuter la sédation avec l'équipe avant une aspiration ?","o":["Une sédation adéquate fait partie des stratégies d'atténuation","Elle remplace la pré-oxygénation avant une aspiration chez le patient ventilé","Elle est systématiquement obligatoire avant toute aspiration","Elle raccourcit la durée de l'aspiration à moins de 5 secondes"],"r":0,"e":"La sédation adéquate, à discuter avec l'équipe, figure parmi les stratégies d'atténuation, aux côtés de l'auscultation, de la surveillance et de la pré-oxygénation.","s":6},{"q":"Qu'est-ce qui justifie l'usage de gants stériles quand c'est possible ?","o":["Prévenir l'infection, en plus de l'hygiène des mains systématique","Se protéger des projections, en plus du masque et des lunettes de protection","Améliorer le confort du patient, en évitant le contact du latex","Respecter la réglementation sur les équipements de protection"],"r":0,"e":"L'hygiène des mains est systématique et l'usage de gants stériles est encouragé lorsque c'est possible.","s":6},{"q":"Pourquoi l'aspect en dents de scie sur la courbe du ventilateur est-il une indication d'aspiration ?","o":["Il traduit des sécrétions dans le circuit ou les voies aériennes","Il signale une fuite autour du ballonnet de la sonde d'intubation","Il indique une désadaptation du patient au ventilateur, par asynchronie","Il révèle un pneumothorax sous ventilation mécanique"],"r":0,"e":"L'aspect en dents de scie sur la courbe de ventilation mécanique est l'un des trois signes objectifs indiquant la nécessité d'aspirer.","s":6},{"q":"Pourquoi ne faut-il pas aspirer à horaires fixes ?","o":["L'aspiration expose à des complications et ne se fait que si nécessaire","Aspirer souvent fatigue le soignant et désorganise le travail de l'équipe","Le matériel s'use trop vite quand on aspire à heures fixes","Les guidelines l'interdisent sans prescription médicale écrite et signée"],"r":0,"e":"L'aspiration comporte de nombreuses complications traumatiques, cardiovasculaires et respiratoires : elle ne se pratique que sur indication.","s":6},{"q":"Qu'est-ce qui distingue l'aspiration continue de l'aspiration intermittente ?","o":["Deux façons d'appliquer la pression négative, selon la situation","L'intermittente est interdite par les guidelines actuelles de l'AARC","La continue dure toujours plus de 15 secondes par passage","L'intermittente ne s'utilise que par voie nasale, chez l'enfant"],"r":0,"e":"La fiche présente aspiration continue et intermittente comme deux modalités possibles, le principe restant d'aspirer uniquement lorsque c'est nécessaire et pendant 15 secondes au maximum.","s":6},{"q":"Que mesure l'électrocardiogramme ?","o":["L'activité électrique cardiaque","La contraction mécanique du myocarde","Le débit cardiaque","La pression intracavitaire"],"r":0,"e":"Cette activité électrique cause la contraction et renseigne sur la structure et la fonction des cellules myocardiques.","s":7},{"q":"Quelles sont les trois finalités de l'ECG ?","o":["Évaluation, diagnostic et monitorage","Diagnostic, traitement et pronostic","Dépistage, prévention et suivi au long cours","Mesure, calcul et interprétation"],"r":0,"e":"Ce sont les trois applications pratiques citées.","s":7},{"q":"À quoi correspondent 10 mm de hauteur sur le tracé ?","o":["1 mV","0,2 seconde","1 seconde","10 mV"],"r":0,"e":"C'est l'étalonnage standard en amplitude.","s":7},{"q":"Quelle durée sépare deux lignes foncées ?","o":["0,2 seconde","0,04 seconde","1 seconde","0,1 seconde"],"r":0,"e":"C'est la base du calcul rapide de la fréquence cardiaque.","s":7},{"q":"Où se place l'électrode V1 ?","o":["4ᵉ espace intercostal, bord sternal droit","4ᵉ espace intercostal, bord sternal gauche","5ᵉ espace intercostal, ligne médio-claviculaire","5ᵉ espace intercostal, ligne axillaire moyenne"],"r":0,"e":"V2 est au 4ᵉ EIC bord sternal gauche.","s":7},{"q":"Où se place l'électrode V4 ?","o":["5ᵉ espace intercostal, ligne médio-claviculaire gauche","4ᵉ espace intercostal, bord sternal gauche","5ᵉ espace intercostal, ligne axillaire antérieure gauche","4ᵉ espace intercostal, entre les lignes de V2 et V3"],"r":0,"e":"V5 est sur la ligne axillaire antérieure et V6 sur la ligne axillaire moyenne.","s":7},{"q":"Où se place l'électrode V6 ?","o":["5ᵉ espace intercostal, ligne axillaire moyenne","5ᵉ espace intercostal, ligne axillaire antérieure","5ᵉ espace intercostal, ligne médio-claviculaire","4ᵉ espace intercostal, bord sternal gauche"],"r":0,"e":"V5 est sur la ligne axillaire antérieure, V6 sur la moyenne.","s":7},{"q":"Que représente l'onde P ?","o":["La dépolarisation des oreillettes","La dépolarisation des ventricules","La repolarisation des ventricules","La repolarisation des oreillettes"],"r":0,"e":"Son amplitude est de 2 à 3 mm et sa durée de 0,006 à 0,12 s.","s":7},{"q":"Que représente le complexe QRS ?","o":["La dépolarisation des ventricules","La dépolarisation des oreillettes","La repolarisation des ventricules","La conduction auriculo-ventriculaire"],"r":0,"e":"Amplitude 5 à 30 mm, durée 0,06 à 0,10 s.","s":7},{"q":"Quelle est la durée normale du complexe QRS ?","o":["0,06 à 0,10 seconde","0,12 à 0,20 seconde","0,006 à 0,12 seconde","0,20 à 0,40 seconde"],"r":0,"e":"Un QRS élargi oriente vers une origine ventriculaire ou un bloc de branche.","s":7},{"q":"Que représente l'onde T ?","o":["La repolarisation des ventricules","La dépolarisation des ventricules","La repolarisation des oreillettes","La conduction nodale"],"r":0,"e":"Amplitude de 0,5 à 10 mm, positive en DI, II et V3 à V6, inversée en aVR.","s":7},{"q":"Dans quelle dérivation les ondes P, QRS et T sont-elles négatives ou inversées ?","o":["aVR","DII","V5","aVF"],"r":0,"e":"aVR explore le cœur « de dos », d'où les déflexions inversées.","s":7},{"q":"Quelle est la durée normale de l'intervalle PR ?","o":["0,12 à 0,20 seconde","0,06 à 0,10 seconde","0,20 à 0,30 seconde","0,04 à 0,08 seconde"],"r":0,"e":"Il va du début de l'onde P au début du QRS.","s":7},{"q":"Que mesure l'intervalle QT ?","o":["La dépolarisation et la repolarisation ventriculaires","La seule dépolarisation des ventricules, du début à la fin du QRS","La conduction auriculo-ventriculaire, du début de P au QRS","La dépolarisation des oreillettes"],"r":0,"e":"Le segment ST correspond à la fin de la dépolarisation et au début de la repolarisation ventriculaire.","s":7},{"q":"Quels nombres faut-il mémoriser pour le calcul rapide de la FC ?","o":["300, 150, 100, 75, 60, 50","300, 200, 100, 75, 50, 25","250, 125, 100, 80, 60, 40","360, 180, 120, 90, 72, 60"],"r":0,"e":"On part d'une onde R coïncidant avec une ligne foncée et on compte les lignes foncées suivantes.","s":7},{"q":"Comment calcule-t-on une fréquence cardiaque très basse ?","o":["Nombre de cycles sur 6 secondes × 10","Nombre de cycles sur 3 secondes × 20","300 divisé par le nombre de grands carreaux","1500 divisé par le nombre de petits carreaux"],"r":0,"e":"Exemple : 3 cycles en 6 secondes × 10 = 30 bpm.","s":7},{"q":"Quelle situation physiologique donne une bradycardie sinusale ?","o":["Un athlète au repos","Un exercice intense","Une fièvre","Un stress aigu"],"r":0,"e":"L'usage de bêtabloquants est l'autre cause citée.","s":7},{"q":"Quelle situation donne une tachycardie sinusale ?","o":["Une température corporelle élevée","Un traitement par bêtabloquants","Un entraînement d'endurance au repos","Une stimulation vagale"],"r":0,"e":"L'exercice est l'autre cause citée.","s":7},{"q":"Qu'est-ce qui caractérise une arythmie sinusale ?","o":["Ondes semblables, distances différentes","Ondes différentes, distances semblables","Ondes P absentes, distances irrégulières","QRS élargis, distances semblables"],"r":0,"e":"Dans le rythme sinusal normal, ondes et distances sont semblables.","s":7},{"q":"Qu'est-ce qui cause une extrasystole ?","o":["Un foyer ectopique qui décharge avant le stimulus attendu","Un bloc de conduction entre les oreillettes et les ventricules","Une hyperkaliémie exclusivement, quelle que soit sa valeur","Une stimulation vagale qui ralentit brutalement le nœud sinusal"],"r":0,"e":"Elle survient lorsque le nœud SA voit son automatisme naturel supprimé.","s":7},{"q":"Quelle cause d'extrasystole n'est PAS citée ?","o":["L'hypothermie","L'ischémie localisée","Les calcifications cardiaques","Les irritations toxiques"],"r":0,"e":"Les trois causes citées sont l'ischémie, les calcifications et les irritations toxiques.","s":7},{"q":"Comment reconnaît-on une extrasystole atriale ?","o":["Une origine prématurée avec une onde P différente","Une absence d'onde P avec un QRS élargi et bizarre","Une absence d'onde P avec un QRS fin","Un QRS élargi avec une onde P normale"],"r":0,"e":"L'extrasystole nodale est sans onde P ; la ventriculaire est sans onde P avec QRS élargi.","s":7},{"q":"Comment reconnaît-on une extrasystole ventriculaire ?","o":["Prématurée, sans onde P, avec un QRS élargi","Prématurée, avec une onde P différente, QRS fin","Prématurée, sans onde P, avec un QRS fin","Un allongement progressif du PR jusqu'au bloc"],"r":0,"e":"Le QRS élargi signe l'origine ventriculaire.","s":7},{"q":"Qu'est-ce que le bigéminisme ?","o":["1 cycle normal pour 1 extrasystole ventriculaire","2 cycles normaux pour 1 extrasystole ventriculaire","3 cycles normaux pour 1 extrasystole ventriculaire","2 extrasystoles ventriculaires consécutives"],"r":0,"e":"Trigéminisme : 2 cycles normaux pour 1 ESV ; quadrigéminisme : 3 cycles normaux pour 1 ESV.","s":7},{"q":"Qu'est-ce que le trigéminisme ?","o":["2 cycles normaux pour 1 extrasystole ventriculaire","1 cycle normal pour 1 extrasystole ventriculaire","3 extrasystoles ventriculaires consécutives, en salve","3 cycles normaux pour 1 extrasystole ventriculaire"],"r":0,"e":"Le quadrigéminisme correspond à 3 cycles normaux pour 1 ESV.","s":7},{"q":"Quelle est la fréquence caractéristique d'un flutter ?","o":["250 à 350 par minute","350 à 450 par minute","150 à 200 par minute","100 à 150 par minute"],"r":0,"e":"La fibrillation se situe entre 350 et 450 par minute.","s":7},{"q":"Quelle est la fréquence caractéristique d'une fibrillation ?","o":["350 à 450 par minute","250 à 350 par minute","150 à 250 par minute","Plus de 500 par minute"],"r":0,"e":"La fibrillation est causée par de nombreux foyers ectopiques déchargeant continuellement à des fréquences différentes.","s":7},{"q":"Quel est le signe ECG de la fibrillation auriculaire ?","o":["Une ligne de base irrégulière","Une onde sinusoïdale","Des ondes P semblables","Un allongement progressif du PR"],"r":0,"e":"Le flutter atrial montre au contraire des ondes P semblables.","s":7},{"q":"Que définit un bloc AV du 1ᵉʳ degré ?","o":["Un intervalle PR supérieur à 0,20 seconde","L'absence d'un cycle complet, toutes les 3 à 4 secondes","Un allongement progressif du PR, sur 3 à 4 cycles, jusqu'au bloc","Le blocage de 100 % des stimuli auriculaires"],"r":0,"e":"L'allongement progressif jusqu'au bloc caractérise le 2ᵉ degré type I (Wenckebach).","s":7},{"q":"Qu'est-ce qui caractérise le bloc AV du 2ᵉ degré type I (Wenckebach) ?","o":["Un PR qui s'allonge progressivement jusqu'au bloc","Un bloc soudain, sans allongement préalable du PR","Un PR fixe supérieur à 0,20 s, sans aucun bloc","Le blocage de tous les stimuli, avec échappement"],"r":0,"e":"Le type II (Mobitz) donne un bloc soudain, pouvant survenir en 1:1, 5:4, 5:3 ou 3:2.","s":7},{"q":"Quelles informations l'activité électrique cardiaque fournit-elle ?","o":["La structure des cellules myocardiques","La fonction des cellules myocardiques","La saturation en oxygène du sang","La pression artérielle systolique"],"r":[0,1],"e":"L'activité électrique cause la contraction des cellules myocardiques et renseigne sur leur structure et leur fonction.","s":7},{"q":"Quels types de dérivations l'ECG utilise-t-il ?","o":["Périphériques, selon le triangle d'Einthoven","Précordiales, sur la paroi thoracique, de V1 à V6","Œsophagiennes, par une sonde nasale descendue","Abdominales, autour de l'ombilic et des flancs"],"r":[0,1],"e":"Dérivations périphériques (triangle d'Einthoven) et précordiales.","s":7},{"q":"Où se placent les électrodes V2 et V3 ?","o":["V2 : 4ᵉ espace intercostal, bord sternal gauche","V3 : milieu entre V2 et V4","V2 : 5ᵉ espace intercostal, ligne axillaire antérieure","V3 : bord sternal droit"],"r":[0,1],"e":"V2 : 4ᵉ EIC bord sternal gauche. V3 : à mi-chemin entre V2 et V4.","s":7},{"q":"Où se place l'électrode V5 ?","o":["5ᵉ espace intercostal, ligne axillaire antérieure","5ᵉ espace intercostal, ligne médio-claviculaire","5ᵉ espace intercostal, ligne axillaire moyenne","4ᵉ espace intercostal, bord sternal droit"],"r":0,"e":"V4 : ligne médio-claviculaire. V5 : ligne axillaire antérieure. V6 : ligne axillaire moyenne — toutes au 5ᵉ espace intercostal.","s":7},{"q":"Quelle est l'amplitude normale de l'onde P ?","o":["2 à 3 mm","5 à 30 mm","0,5 à 10 mm","10 mm exactement"],"r":0,"e":"Onde P : 2 à 3 mm. QRS : 5 à 30 mm. Onde T : 0,5 à 10 mm.","s":7},{"q":"Dans quelles dérivations le complexe QRS est-il positif ?","o":["DI, DII et DIII","aVL et aVF","V4 à V6","V1 à V3"],"r":[0,1,2],"e":"Le QRS est positif en DI, II, III, aVL, aVF et V4 à V6, négatif en aVR et V1 à V3.","s":7},{"q":"Dans quelles dérivations l'onde T est-elle positive ?","o":["DI et DII","V3 à V6","aVR","V1"],"r":[0,1],"e":"L'onde T est positive en DI, DII et V3 à V6, et inversée en aVR.","s":7},{"q":"Que délimite l'intervalle PR ?","o":["Du début de l'onde P au début du QRS","De la fin de l'onde P au début du QRS, sans compter l'onde P elle-même","Du début du QRS à la fin de l'onde T","De l'onde T à l'onde P suivante"],"r":0,"e":"L'intervalle PR va du début de l'onde P au début du QRS et dure normalement 0,12 à 0,20 seconde.","s":7},{"q":"Que représente le segment ST ?","o":["La fin de la dépolarisation et le début de la repolarisation ventriculaires","La dépolarisation des oreillettes, avant le complexe QRS","La conduction auriculo-ventriculaire, à travers le nœud et le faisceau de His","La repolarisation des oreillettes, masquée par le QRS"],"r":0,"e":"Le segment ST correspond à la fin de la dépolarisation ventriculaire et au début de la repolarisation ventriculaire.","s":7},{"q":"Sur quel raisonnement repose le calcul rapide de la fréquence cardiaque ?","o":["0,2 s entre deux lignes foncées, soit 1/300 de minute","Deux intervalles, soit 150 battements par minute","Trois intervalles, soit 100 battements par minute","Un petit carreau, soit 1 seconde complète"],"r":[0,1,2],"e":"Le raisonnement part de 0,2 s entre deux lignes foncées : 1/300 de minute, d'où la série 300, 150, 100, 75, 60, 50.","s":7},{"q":"Un patient présente 3 cycles sur 6 secondes. Quelle est sa fréquence cardiaque ?","o":["30 bpm","18 bpm","60 bpm","50 bpm"],"r":0,"e":"Pour les fréquences très basses : nombre de cycles sur 6 secondes × 10, soit 3 × 10 = 30 bpm.","s":7},{"q":"Comment définit-on le rythme cardiaque ?","o":["Le mouvement régulier et périodique, normalement sinusal","Le nombre de battements par minute, au repos et à l'effort","L'amplitude des ondes, mesurée en millivolts","La durée du QRS, mesurée en millisecondes"],"r":0,"e":"Le rythme est le mouvement régulier et périodique ; le rythme normal du cycle cardiaque est le rythme sinusal.","s":7},{"q":"Qu'est-ce qui distingue un rythme sinusal normal d'une arythmie sinusale ?","o":["Les ondes sont semblables, mais les distances varient dans l'arythmie","Les ondes sont différentes dans l'arythmie sinusale, mais les distances semblables","Le rythme sinusal normal n'a pas d'onde P, l'arythmie en a une","L'arythmie sinusale a un QRS élargi, le rythme normal un QRS fin"],"r":0,"e":"Rythme régulier normal : ondes semblables et distances semblables. Arythmie sinusale : ondes semblables mais distances différentes.","s":7},{"q":"Quel terme est également utilisé pour désigner une arythmie ?","o":["Dysrythmie","Bradycardie","Extrasystole","Bloc"],"r":0,"e":"Arythmie signifie littéralement « sans rythme », mais désigne un rythme anormal ou une interruption de la régularité ; on emploie aussi le terme dysrythmie.","s":7},{"q":"Comment reconnaît-on une extrasystole nodale ?","o":["Une origine prématurée, sans onde P","Une onde P différente, prématurée","Un QRS élargi, sans onde P","L'absence d'un cycle complet, avec une pause"],"r":0,"e":"Extrasystole atriale : onde P différente. Nodale : sans onde P. Ventriculaire : sans onde P et QRS élargi.","s":7},{"q":"Qu'est-ce que le quadrigéminisme ?","o":["3 cycles normaux pour 1 extrasystole ventriculaire","2 cycles normaux pour 1 extrasystole ventriculaire","1 cycle normal pour 1 extrasystole ventriculaire","4 extrasystoles ventriculaires consécutives, en salve"],"r":0,"e":"Bigéminisme : 1 cycle normal pour 1 ESV. Trigéminisme : 2 pour 1. Quadrigéminisme : 3 pour 1.","s":7},{"q":"Selon quelles modalités les extrasystoles ventriculaires peuvent-elles se présenter ?","o":["Unifocales ou multifocales","Isolées ou en salves","En bigéminisme ou trigéminisme","Toujours isolées et unifocales"],"r":[0,1,2],"e":"Les ESV peuvent être unifocales ou multifocales, isolées ou en salves (de 3, de 6…), et suivre un schéma de répétition.","s":7},{"q":"Quelle est la cause commune des tachyarythmies ?","o":["Un foyer ectopique très excitable, parfois plusieurs, qui décharge vite","Un bloc de conduction entre les oreillettes et les ventricules","Une stimulation vagale extrême, qui ralentit le nœud sinusal","Une ischémie du nœud sinusal, qui supprime l'automatisme naturel"],"r":0,"e":"Les tachyarythmies naissent d'un foyer ectopique très excitable ; souvent plus d'un foyer génère les stimuli.","s":7},{"q":"Quels signes ECG distinguent flutter atrial et flutter ventriculaire ?","o":["Flutter atrial : ondes P semblables","Flutter ventriculaire : onde sinusoïdale","Flutter atrial : ligne de base irrégulière","Flutter ventriculaire : absence de schéma"],"r":[0,1],"e":"Flutter (250-350/min) : ondes P semblables en atrial, onde sinusoïdale en ventriculaire. La ligne de base irrégulière et l'absence de schéma caractérisent la fibrillation.","s":7},{"q":"Quelles sont les causes de bloc auriculo-ventriculaire ?","o":["L'ischémie du nœud AV","Une compression du nœud AV","L'inflammation du nœud AV","Une stimulation vagale extrême","Une hyperkaliémie isolée"],"r":[0,1,2,3],"e":"Les quatre causes sont citées. Par exemple une myocardite pour l'inflammation.","s":7},{"q":"Selon l'OMS (Brown, 1964), que vise la réadaptation cardiovasculaire ?","o":["Un état physique, mental et social optimal, pour une place normale","La seule récupération de la fonction cardiaque, mesurée à l'échographie","La prévention des récidives, par les seuls médicaments prescrits","La reprise du sport de compétition, dans les six mois"],"r":0,"e":"L'accent est mis sur le fait que la personne y parvienne par ses propres moyens.","s":8},{"q":"Quelle est la première cause de décès dans le monde selon l'OMS ?","o":["Les maladies cardiovasculaires et métaboliques","Les cancers, toutes localisations confondues","Les maladies neurologiques dégénératives","Les maladies rénales chroniques avec dialyse"],"r":0,"e":"Cardiopathies ischémiques, AVC et diabète de type 2 arrivent en tête.","s":8},{"q":"Quelle est une des principales causes d'incapacité dans le monde ?","o":["La douleur cervicale et lombaire","L'insuffisance cardiaque chronique et l'œdème","La BPCO et l'insuffisance respiratoire","Le diabète et ses complications"],"r":0,"e":"Avec les complications de la naissance prématurée, la diarrhée et les accidents de la route.","s":8},{"q":"Qui a décrit l'infarctus aigu du myocarde vers 1912 ?","o":["James Bryan Herrick","William Heberden","Robert Bruce","Nanette Wenger"],"r":0,"e":"William Heberden avait fait la description clinique originale vers 1700.","s":8},{"q":"Qu'apporte Wenger en 1969 ?","o":["Un protocole en 14 étapes, avec exercices, activités quotidiennes, éducation","L'évaluation de la capacité fonctionnelle, sur tapis roulant, en 7 paliers","La description de l'infarctus du myocarde et de ses 4 stades évolutifs","La classification des maladies cardiaques en 4 classes de gravité"],"r":0,"e":"Bruce (1957) avait développé l'évaluation de la capacité fonctionnelle.","s":8},{"q":"Quelle pratique était en vigueur entre 1930 et 1960 ?","o":["3 semaines de repos après un infarctus, escaliers interdits 1 an","Une mobilisation précoce en réanimation, dès les 24 premières heures","Un exercice supervisé dès la sortie, 3 fois par semaine","Une réadaptation en groupe, sur 12 semaines"],"r":0,"e":"On cherchait à gérer l'inactivité, mais avec des restrictions considérables.","s":8},{"q":"Quelle situation est une contre-indication à la réadaptation cardiovasculaire ?","o":["L'angor instable","L'angor stabilisé","Un pontage récent stabilisé","Une angioplastie stabilisée"],"r":0,"e":"Les contre-indications concernent les patients instables : angor instable, IDM, arythmies complexes, réponses hémodynamiques anormales.","s":8},{"q":"Quel type d'arythmie contre-indique la réadaptation ?","o":["Les arythmies complexes, comme un bloc du 3ᵉ degré","Les extrasystoles isolées, au repos","La bradycardie sinusale de l'athlète entraîné, à moins de 50 par minute","L'arythmie sinusale respiratoire"],"r":0,"e":"Les arythmies stabilisées figurent au contraire parmi les autres indications.","s":8},{"q":"Quel facteur de risque n'est PAS modifiable ?","o":["L'âge","L'obésité","Le tabagisme","La sédentarité"],"r":0,"e":"Le cours distingue facteurs de risque modifiables (obésité, dyslipidémie, HTA, tabagisme, diabète, stress, sédentarité) et non modifiables.","s":8},{"q":"Que fait le kinésithérapeute dans l'équipe de réadaptation cardiaque ?","o":["Évaluation, diagnostic, prescription d'exercice et éducation","La surveillance de l'ECG, seule, pendant les séances d'exercice","Le conseil nutritionnel, seul, et la gestion du poids","Les techniques respiratoires, seules, et la kiné de désencombrement"],"r":0,"e":"L'équipe comprend aussi médecin, psychologue, diététicien et assistant social.","s":8},{"q":"Que couvre la phase I de la réadaptation cardiovasculaire ?","o":["De l'événement cardiaque jusqu'à la sortie d'hôpital","Les trois mois qui suivent la sortie, en ambulatoire supervisé","L'entretien supervisé, de 3 à 6 mois après l'événement","L'entretien non supervisé, à domicile, à vie"],"r":0,"e":"Elle inclut la mobilisation précoce en réanimation, les techniques respiratoires et la gestion de la ventilation mécanique.","s":8},{"q":"Combien de temps dure en moyenne la phase II ?","o":["Trois mois","Six semaines","Un an","Six mois"],"r":0,"e":"La phase II est supervisée et se déroule après la sortie d'hôpital.","s":8},{"q":"Quelle phase correspond à un entretien non supervisé de durée indéfinie ?","o":["La phase IV","La phase I","La phase II","La phase III"],"r":0,"e":"La phase III est un entretien supervisé de 3 à 6 mois, pouvant se prolonger.","s":8},{"q":"Quel objectif appartient à la phase I ?","o":["Éviter les complications pulmonaires et raccourcir l'hospitalisation","Améliorer la condition physique à long terme, sur plusieurs années","Prescrire l'intensité de l'exercice pour l'autonomie au domicile","Réduire la compétition et favoriser l'engagement en groupe"],"r":0,"e":"La phase I vise aussi à diminuer les effets du repos prolongé et à maintenir la capacité fonctionnelle.","s":8},{"q":"Quel objectif général vise le processus athéroscléreux ?","o":["Prévenir sa progression ou l'inverser","L'accélérer pour stimuler la collatéralité","Le mesurer uniquement","Le traiter chirurgicalement"],"r":0,"e":"C'est l'un des objectifs généraux de la réadaptation cardiovasculaire.","s":8},{"q":"Quel signe doit être recherché à l'évaluation cardiovasculaire ?","o":["La claudication intermittente","La dysphagie haute aux solides","L'hémoptysie de faible abondance","La dysarthrie d'apparition brutale"],"r":0,"e":"Signes et symptômes recherchés : dyspnée, claudication intermittente, fatigue, tolérance à l'effort, angor, lipothymie, œdème, palpitations, nausées, crampes, pâleur.","s":8},{"q":"Quel examen complémentaire n'est PAS cité pour l'évaluation ?","o":["La spirométrie","Le Holter","La MAPA","L'épreuve d'effort"],"r":0,"e":"Les examens cités sont ECG, échocardiographie, Holter, MAPA, scintigraphie, cathétérismes et épreuves d'effort.","s":8},{"q":"Quelle est la fréquence recommandée de l'exercice aérobie ?","o":["3 à 4 fois par semaine","1 fois par semaine","Tous les jours","2 fois par mois"],"r":0,"e":"L'intensité se règle sur le VO₂, le seuil ventilatoire, la FC, la réserve de FC ou l'échelle de perception de l'effort.","s":8},{"q":"Quelle est la durée de l'échauffement ?","o":["5 à 10 minutes","20 à 40 minutes","1 à 2 minutes","15 à 20 minutes"],"r":0,"e":"L'échauffement et la récupération durent tous deux 5 à 10 minutes ; le conditionnement 20 à 40 minutes.","s":8},{"q":"Quel est un objectif de l'échauffement ?","o":["Un ajustement circulatoire progressif et une baisse des résistances","L'élimination de l'acide lactique accumulé pendant la séance d'effort","La dissipation de la chaleur produite par l'exercice","Le retour progressif de la FC à sa valeur de repos"],"r":0,"e":"Il vise à éviter les lésions musculo-squelettiques et la possibilité d'arythmies.","s":8},{"q":"Quelle est la durée du conditionnement ?","o":["20 à 40 minutes","5 à 10 minutes","45 à 60 minutes","10 à 15 minutes"],"r":0,"e":"Le conditionnement se fait à intensité modérée et continue, sur de grands groupes musculaires.","s":8},{"q":"Quel est le but du conditionnement ?","o":["Stimuler l'absorption, le transport et l'utilisation de l'oxygène","Augmenter la température, la vigilance et la souplesse avant l'effort","Éliminer l'acide lactique, le CO₂ et la chaleur accumulés","Réduire la compétition, le stress et la pression entre patients"],"r":0,"e":"C'est le cœur aérobie de la séance, avec monitorage, individualisation et progression.","s":8},{"q":"Quel est un objectif de la phase de récupération ?","o":["Éliminer l'acide lactique, ramener la FC et la PA au repos","Augmenter la température corporelle, avant l'effort principal","Augmenter progressivement la FC, jusqu'à la zone cible d'entraînement","Stimuler au maximum le système cardiorespiratoire"],"r":0,"e":"Elle vise à éviter les effets délétères des catécholamines et les complications post-effort.","s":8},{"q":"Quel est l'objectif de la phase récréative ?","o":["Réduire la compétition, favoriser motivation et engagement","Augmenter l'intensité maximale de l'effort en fin de séance","Tester la 1RM sur chaque groupe musculaire du patient","Mesurer la VO₂ max sur cycloergomètre, à chaque séance"],"r":0,"e":"C'est une composante d'adhésion à long terme.","s":8},{"q":"Quelle intensité est recommandée pour l'exercice résisté ?","o":["60 à 75 % de 1RM","30 à 40 % de 1RM","85 à 95 % de 1RM","100 % de 1RM"],"r":0,"e":"Avec 10 à 15 répétitions et 3 séries.","s":8},{"q":"Combien de répétitions sont recommandées en exercice résisté ?","o":["10 à 15","3 à 5","20 à 30","1 à 2"],"r":0,"e":"À 60-75 % de 1RM, sur 3 séries et 6 à 10 exercices.","s":8},{"q":"Quel est le rapport temps d'exercice / temps de récupération recommandé ?","o":["2:1","1:1","1:2","3:1"],"r":0,"e":"Avec 2 minutes pour chaque phase excentrique/concentrique.","s":8},{"q":"Combien d'exercices comporte une séance de renforcement ?","o":["6 à 10","2 à 3","15 à 20","1 à 2"],"r":0,"e":"Ils portent sur les membres supérieurs et inférieurs, souvent en circuits.","s":8},{"q":"Quelle modalité moderne d'exercice est citée ?","o":["La réalité virtuelle","L'électrostimulation","L'hydrothérapie","La cryothérapie"],"r":0,"e":"Avec l'exercice aérobie fractionné, l'exercice fonctionnel et les élastiques.","s":8},{"q":"Quelle est l'incidence des événements cardiaques pendant la réadaptation ?","o":["1 événement toutes les 50 000 heures d'exercice","1 événement toutes les 500 heures d'exercice supervisé","1 événement toutes les 5 000 heures d'exercice","1 événement par jour de réadaptation en centre"],"r":0,"e":"Soit 25 000 patients ; et 1 fibrillation ventriculaire pour 111 996 patients/heure d'exercice.","s":8},{"q":"Quelles pathologies respiratoires figurent parmi les principales causes de décès (OMS 2021) ?","o":["La COVID-19","La BPCO","Les infections respiratoires basses","La tuberculose","L'embolie pulmonaire"],"r":[0,1,2,3],"e":"Les quatre sont citées dans le groupe respiratoire, aux côtés des causes cardiovasculaires et métaboliques, du cancer, des causes neurologiques et rénales.","s":8},{"q":"Quelles causes d'incapacité sont citées dans le monde ?","o":["Les complications de la prématurité","La douleur cervicale et lombaire","La diarrhée","Les accidents de la route","Les maladies cardiovasculaires"],"r":[0,1,2,3],"e":"Les quatre causes principales d'incapacité sont énumérées.","s":8},{"q":"Qui a réalisé la description clinique originale vers 1700 ?","o":["William Heberden","James Bryan Herrick","Bruce RA","Wenger N"],"r":0,"e":"William Heberden vers 1700 ; Herrick décrit l'IDM vers 1912 ; Bruce évalue la capacité fonctionnelle en 1957 ; Wenger propose son protocole en 1969.","s":8},{"q":"Qu'apporte Bruce RA en 1957 ?","o":["L'évaluation de la capacité fonctionnelle des cardiaques","Le protocole en 14 étapes avec exercices gradués","La description de l'infarctus du myocarde et de ses stades","La définition OMS de la réadaptation cardiaque"],"r":0,"e":"Bruce RA, 1957 : évaluation de la capacité fonctionnelle des patients cardiaques.","s":8},{"q":"Que comprend le protocole de Wenger (1969) ?","o":["Des exercices gradués","Les activités quotidiennes","Une composante éducative","Un test de 1RM initial"],"r":[0,1,2],"e":"Le protocole en 14 étapes de Wenger associe exercices gradués, AVQ et composante éducative.","s":8},{"q":"Quels événements marquent 1977 et 1982 ?","o":["1977 : premier congrès mondial de réadaptation","1982 : lancement d'une revue spécialisée","1982 : début de la réadaptation à Porto","1977 : inclusion des patients de prévention"],"r":[0,1,2],"e":"1977 : premier congrès mondial. 1982 : revue spécialisée et début au Portugal, à Porto. 1996 : inclusion des patients de prévention. La revue est le Journal of Cardiopulmonary Rehabilitation ; les patients de prévention sont inclus en 1996.","s":8},{"q":"Quelles indications de réadaptation concernent des patients stables ?","o":["Maladie coronarienne et infarctus","Pontage et angioplastie coronaire","Angor stabilisé sous traitement","Angor instable, douleur de repos"],"r":[0,1,2],"e":"Ces indications concernent des patients stables. L'angor instable est au contraire une contre-indication.","s":8},{"q":"Quelles autres indications de réadaptation cardiovasculaire sont citées ?","o":["Insuffisance cardiaque, transplantation","Valvulopathies, myocardite, péricardite","Artériopathie, cardiopathies congénitales","Arythmies stabilisées sous traitement","Angor instable et infarctus en cours"],"r":[0,1,2,3],"e":"Toutes ces situations figurent parmi les autres indications, avec les facteurs de risque modifiables et non modifiables.","s":8},{"q":"Quels facteurs de risque modifiables sont cités ?","o":["Obésité, dyslipidémie","HTA, tabagisme","Diabète","Stress, sédentarité","Antécédents familiaux"],"r":[0,1,2,3],"e":"Obésité, dyslipidémie, HTA, tabagisme, diabète, stress et sédentarité sont modifiables.","s":8},{"q":"Quels professionnels composent l'équipe de réadaptation cardiovasculaire ?","o":["Kinésithérapeute et médecin","Psychologue","Diététicien","Assistant social","Ergothérapeute"],"r":[0,1,2,3],"e":"L'équipe s'organise autour de l'évaluation et de l'éducation.","s":8},{"q":"Quels types d'exercice le kinésithérapeute prescrit-il en réadaptation cardiaque ?","o":["Aérobie","De résistance","De flexibilité","Maximal seul"],"r":[0,1,2],"e":"Le kinésithérapeute prescrit l'exercice aérobie, de résistance et de flexibilité, et participe à la composante éducative.","s":8},{"q":"Que comprend la phase I de la réadaptation cardiovasculaire ?","o":["Mobilisation précoce en réanimation","Techniques respiratoires","Gestion de la ventilation mécanique","Exercices physiques en service","Entretien non supervisé"],"r":[0,1,2,3],"e":"La phase I va de l'événement cardiaque à la sortie d'hôpital. L'entretien non supervisé est la phase IV.","s":8},{"q":"Quel est l'objectif principal de la phase II ?","o":["Contribuer au retour le plus rapide possible aux activités quotidiennes","Éviter les complications pulmonaires liées à l'alitement prolongé","Réduire la durée d'hospitalisation après l'événement cardiaque","Programmer les activités de loisir à long terme, en autonomie complète, sans supervision"],"r":0,"e":"La phase II, supervisée et d'environ trois mois après la sortie, vise le retour rapide aux AVQ, avec une prescription individualisée.","s":8},{"q":"Quelles conditions matérielles la phase II exige-t-elle ?","o":["Un environnement adapté","Une prise en charge d'urgence disponible","Un monitorage","Une absence totale de supervision"],"r":[0,1,2],"e":"La phase II est supervisée, avec environnement adapté, capacité de prise en charge d'urgence et monitorage.","s":8},{"q":"Quels objectifs spécifiques la réadaptation cardiovasculaire poursuit-elle ?","o":["Capacité fonctionnelle, force, souplesse, équilibre","Un traitement médicamenteux optimisé","Arythmies et troubles hémodynamiques dépistés","Santé nutritionnelle et psychologique","Une fraction d'éjection normalisée"],"r":[0,1,2,3],"e":"Les quatre objectifs spécifiques sont cités, avec l'évaluation et la promotion de l'activité physique. Les arythmies sont dépistées avant, pendant et après l'effort.","s":8},{"q":"Quels signes et symptômes recherche-t-on à l'évaluation cardiovasculaire ?","o":["Dyspnée, claudication","Fatigue, tolérance à l'effort","Angor, lipothymie","Œdème, palpitations, nausées","Hématurie, brûlures urinaires"],"r":[0,1,2,3],"e":"La liste complète des signes à rechercher est énumérée dans la fiche.","s":8},{"q":"Quels examens complémentaires sont cités pour l'évaluation ?","o":["ECG et échocardiographie","Holter et MAPA","Scintigraphie et cathétérismes","Épreuves d'effort","Spirométrie forcée"],"r":[0,1,2,3],"e":"Les examens complémentaires comprennent ECG, échocardiographie, Holter, MAPA, scintigraphie, cathétérismes et épreuves d'effort.","s":8},{"q":"Sur quels paramètres règle-t-on l'intensité de l'exercice aérobie ?","o":["La VO₂","Le seuil ventilatoire","La FC et sa réserve","La perception de l'effort","La PA diastolique"],"r":[0,1,2,3],"e":"Ces quatre paramètres permettent de fixer l'intensité, dans une logique d'interdépendance volume × intensité.","s":8},{"q":"Quels objectifs physiologiques poursuit l'échauffement ?","o":["Un ajustement circulatoire graduel","Une augmentation de la température corporelle","Une augmentation progressive de FC et PA","Une diminution des résistances périphériques","L'élimination de l'acide lactique"],"r":[0,1,2,3],"e":"Les quatre premiers. L'élimination de l'acide lactique est un objectif de la phase de récupération.","s":8},{"q":"Quel matériel est proposé pendant l'échauffement ?","o":["Ballon et bâton","Haltères et lestes","Cerceau","Tapis roulant"],"r":[0,1,2],"e":"L'échauffement, de faible intensité et progressif, utilise ballon, bâton, haltères, lestes et cerceau, en position assise ou couchée. Le tapis roulant relève du conditionnement.","s":8},{"q":"Sous quelle pression se fait l'inspiration en ventilation spontanée ?","o":["Pression négative","Pression positive","Pression atmosphérique","Pression nulle"],"r":0,"e":"La ventilation mécanique, elle, se fait sous pression positive.","s":9},{"q":"Quel objectif de la ventilation mécanique concerne l'équilibre acido-basique ?","o":["La correction de l'acidose respiratoire aiguë","La prévention des atélectasies chez le patient alité","L'amélioration de la compliance du système respiratoire","La prévention des lésions pulmonaires induites, par une ventilation protectrice"],"r":0,"e":"Avec la correction de l'hypoxémie et l'amélioration des échanges gazeux.","s":9},{"q":"Quel objectif concerne la charge de travail respiratoire ?","o":["La diminution du coût en O₂ de la respiration","La modification des relations volume/pression","La prévention de l'infection","L'amélioration de la compliance"],"r":0,"e":"Avec le soulagement de la détresse respiratoire et la correction de la fatigue des muscles respiratoires.","s":9},{"q":"Quelle interface relève de la ventilation mécanique invasive ?","o":["La canule de trachéotomie","Le masque nasal","Le casque, ou « helmet »","L'embout buccal de ventilation"],"r":0,"e":"VMI : sonde orotrachéale, sonde nasotrachéale, canule de trachéotomie.","s":9},{"q":"Quelle est la particularité d'une canule de trachéotomie fenêtrée ?","o":["Elle permet de parler","Elle est plus étanche","Elle évite l'aspiration","Elle réduit la PEP"],"r":0,"e":"La canule non fenêtrée ne permet pas la phonation.","s":9},{"q":"Que fait le ventilateur dans une modalité contrôlée ?","o":["Il contrôle toute l'inspiration et remplace totalement l'effort musculaire","Il assiste une musculature inspiratoire active, à chaque cycle déclenché","Il maintient uniquement une PEP, sans aucune aide inspiratoire","Il ne délivre que de l'oxygène, à débit continu, sans pression"],"r":0,"e":"En modalité assistée, le ventilateur assiste une musculature inspiratoire active.","s":9},{"q":"En pression contrôlée, que contrôle le ventilateur ?","o":["La pression, le patient initiant le volume","Le volume, le patient initiant la pression","La pression et le volume en même temps","Ni la pression ni le volume, seulement la FiO₂"],"r":0,"e":"En volume contrôlé c'est l'inverse : le ventilateur contrôle le volume, le patient initie la pression.","s":9},{"q":"En volume assisté, que fait le patient ?","o":["Il initie la pression","Il initie le volume","Il ne fait rien","Il contrôle la fréquence uniquement"],"r":0,"e":"Le ventilateur assiste le volume et le patient initie la pression.","s":9},{"q":"Dans les modalités assistées, qui initie les cycles respiratoires ?","o":["Le patient initie tous les cycles","Le ventilateur initie tous les cycles","Alternativement l'un et l'autre","Aucun, ils sont automatiques"],"r":0,"e":"Dans les modalités contrôlées, le patient peut avoir ou non un stimulus respiratoire.","s":9},{"q":"Que signifie PRVC ?","o":["Pressure-regulated volume control","Positive respiratory volume control","Pressure release ventilation control","Peak respiratory volume cycle"],"r":0,"e":"Avec l'IMV (en désuétude) et la SIMV, ce sont des modalités mixtes.","s":9},{"q":"Que signifie FiO₂ ?","o":["Fraction inspirée d'oxygène, en pourcentage","Flux inspiratoire d'oxygène, en litres par minute","Force inspiratoire en oxygène, en cmH₂O","Fréquence inspiratoire d'oxygène, en cycles par minute"],"r":0,"e":"C'est l'un des paramètres réglés sur le ventilateur.","s":9},{"q":"Quel est le rôle de la PEP ?","o":["Éviter la fermeture précoce de bronchioles à l'expiration","Augmenter le volume courant délivré à chaque inspiration du patient","Réduire la FiO₂ nécessaire à la saturation","Contrôler la fréquence respiratoire minimale"],"r":0,"e":"PEP = Positive Expiratory End Pressure, pression positive en fin d'expiration.","s":9},{"q":"Dans quelles modalités règle-t-on la fréquence respiratoire ?","o":["Seulement dans les modalités contrôlées","Seulement dans les modalités assistées","Dans toutes les modalités, sans exception","Jamais, la machine la calcule seule"],"r":0,"e":"Elle concerne le patient sans stimulus respiratoire ou n'initiant que quelques cycles.","s":9},{"q":"Comment calcule-t-on la pression de pic en pression contrôlée ?","o":["PC + PEP","PC − PEP","PC × PEP","PC seule"],"r":0,"e":"En pression assistée, la pression de pic vaut PA + PEP.","s":9},{"q":"Quelles modalités ne sont habituellement PAS appliquées en VNI ?","o":["Les modalités contrôlées","Les modalités assistées","La CPAP","La BiPAP"],"r":0,"e":"Toutes les modalités de VMI peuvent techniquement être appliquées, mais les contrôlées ne le sont habituellement pas.","s":9},{"q":"Quelle est l'indication principale de la CPAP à domicile ?","o":["Le syndrome d'apnées obstructives du sommeil","La BPCO avec hypercapnie chronique et exacerbations répétées","La fibrose pulmonaire avec hypoxémie d'effort","L'asthme sévère avec crises nocturnes"],"r":0,"e":"La CPAP est aussi indiquée dans l'œdème aigu du poumon ; la BiPAP est indiquée dans la BPCO.","s":9},{"q":"Quelle est l'indication principale de la BiPAP à domicile ?","o":["La BPCO","Le SAOS","L'œdème aigu du poumon","La pneumonie"],"r":0,"e":"La BiPAP assiste la pression via l'IPAP et l'EPAP.","s":9},{"q":"Que fait le ventilateur en mode CPAP ?","o":["Il maintient une pression positive continue, le patient initiant tous les cycles","Il contrôle le volume de chaque cycle, avec une fréquence imposée","Il alterne deux niveaux de pression, inspiratoire et expiratoire, avec une fréquence de secours","Il impose une fréquence minimale, avec une pression fixe"],"r":0,"e":"La BiPAP, elle, assiste la pression avec deux niveaux (IPAP et EPAP).","s":9},{"q":"Quel est le rôle de l'IPAP ?","o":["Fournir le soutien ventilatoire à l'inspiration","Éviter la ré-inhalation de CO₂ en fin d'expiration, dans le masque","Maintenir une pression continue, sur tout le cycle","Fixer la fréquence respiratoire minimale"],"r":0,"e":"C'est le niveau de pression positive programmé atteint pendant l'inspiration.","s":9},{"q":"Quel est le rôle de l'EPAP ?","o":["Éviter la ré-inhalation de CO₂","Fournir le soutien inspiratoire","Augmenter le volume courant","Réduire la FiO₂"],"r":0,"e":"Sur les appareils de VNI, la PEP équivaut à l'EPAP.","s":9},{"q":"Quel est un effet immédiat de la VNI dans les syndromes obstructifs ?","o":["La baisse du travail respiratoire et une rééducation optimisée","La stabilité clinique à long terme et la réduction des hospitalisations","Le contrôle de l'hypoventilation alvéolaire nocturne","L'augmentation du volume résiduel et de la distension"],"r":0,"e":"Le contrôle de l'hypoventilation est un effet immédiat dans les syndromes restrictifs.","s":9},{"q":"Quel est l'effet à long terme de la VNI dans les syndromes restrictifs ?","o":["La stabilité clinique et la réduction des hospitalisations","La guérison de la maladie neuromusculaire sous-jacente","L'arrêt définitif de l'oxygénothérapie à domicile","L'augmentation de la CVF de plus de 20 %"],"r":0,"e":"Dans les syndromes obstructifs, l'effet à long terme cité est la réduction des hospitalisations.","s":9},{"q":"Quel est l'effet de la mobilisation précoce en réanimation ?","o":["Elle diminue la durée de ventilation mécanique","Elle augmente le risque infectieux, par les manipulations","Elle prolonge le séjour en réanimation","Elle n'a aucun effet démontré dans la littérature"],"r":0,"e":"Positionnement corporel, mobilisation précoce, exercice et entraînement musculaire ont des preuves d'efficacité.","s":9},{"q":"Quels patients ne sont PAS candidats à une activité physique vigoureuse en USI ?","o":["Les patients instables, ou sous FiO₂ élevée et ventilation agressive","Les patients coopérants, éveillés et hémodynamiquement stables","Les patients extubés depuis plus de 24 heures, sans oxygène","Les patients sous VNI intermittente, stables entre les séances"],"r":0,"e":"Le risque de mobiliser doit être mis en balance avec les risques de l'immobilité.","s":9},{"q":"Comment réduire le besoin métabolique de l'exercice en USI ?","o":["En recrutant moins de groupes musculaires et en raccourcissant l'exercice","En augmentant la résistance, pour limiter le nombre de répétitions possibles","En allongeant les séances, pour répartir l'effort dans le temps","En augmentant la fréquence des séances, pour fractionner l'effort"],"r":0,"e":"Cela se traduit par un nombre de répétitions moindre.","s":9},{"q":"Quelle modalité convient à un patient NON coopérant ?","o":["L'électrostimulation neuromusculaire","Le transfert au fauteuil, avec aide","La marche, avec un déambulateur","L'entraînement musculaire résisté"],"r":0,"e":"Avec la mobilisation passive et le cycloergomètre motorisé passif.","s":9},{"q":"Selon l'ESICM 2008, quand utiliser l'aspiration chez le patient non intubé ?","o":["Seulement si les autres méthodes échouent, niveau D","En première intention, avant toute autre technique","Systématiquement, toutes les 4 heures, jour et nuit","Jamais, chez le patient non intubé, quelle que soit la situation clinique"],"r":0,"e":"Avec précaution chez les patients sous anticoagulation, avec lésions osseuses ou des tissus mous, ou chirurgies des VAS.","s":9},{"q":"Selon l'ESICM 2008, l'aspiration et l'instillation de sérum physiologique chez le patient intubé doivent être :","o":["Utilisées sur indication spécifique, et non de façon routinière","Utilisées systématiquement, à chaque soin du patient intubé","Totalement proscrites chez le patient intubé","Utilisées uniquement la nuit, pendant le sommeil"],"r":0,"e":"C'est une recommandation de niveau C.","s":9},{"q":"Quels sont les objectifs de l'hyperinsufflation manuelle (Stiller, 2013) ?","o":["Ré-expandre les zones collabées et mobiliser les sécrétions","Réduire la fréquence respiratoire du patient ventilé et sédaté","Diminuer la FiO₂ nécessaire, par une meilleure oxygénation","Augmenter le volume résiduel, par une hyperinsufflation prolongée"],"r":0,"e":"Elle agit en augmentant l'oxygénation et la compliance, en diminuant la résistance et en prévenant les atélectasies.","s":9},{"q":"Quelle est une contre-indication de l'hyperinsufflation manuelle ?","o":["Un pneumothorax non drainé","Une atélectasie lobaire","Une rétention de sécrétions","Une hypoxémie modérée"],"r":0,"e":"Autres contre-indications : OAP, bulles d'emphysème, fistule broncho-pleurale, bronchospasme, instabilité hémodynamique, hémoptysie ; précaution si PEP > 15 cmH₂O.","s":9},{"q":"Quels objectifs gazométriques et cliniques la ventilation mécanique poursuit-elle ?","o":["Améliorer les échanges et corriger l'hypoxémie","Corriger l'acidose respiratoire aiguë","Soulager la détresse respiratoire","Réduire le coût en O₂ et la fatigue musculaire","Prévenir et corriger les atélectasies"],"r":[0,1,2,3],"e":"Les quatre objectifs gazométriques et cliniques sont cités, distincts des objectifs mécaniques et préventifs.","s":9},{"q":"Quels objectifs mécaniques et préventifs la ventilation mécanique poursuit-elle ?","o":["Modifier les relations volume/pression","Prévenir les atélectasies, gagner en compliance","Prévenir les lésions pulmonaires, les guérir","Éviter l'infection et les effets de l'immobilité","Corriger l'acidose respiratoire aiguë"],"r":[0,1,2,3],"e":"Les quatre objectifs mécaniques et préventifs sont énumérés.","s":9},{"q":"Quelles interfaces de ventilation non invasive sont citées ?","o":["Masques facial, nasal, oro-nasal","Canules nasales","Embout buccal","Casque et interface faciale totale","Canule de trachéotomie"],"r":[0,1,2,3],"e":"Sept interfaces de VNI sont listées dans la fiche.","s":9},{"q":"Quelles interfaces relèvent de la ventilation mécanique invasive ?","o":["Sonde orotrachéale","Sonde nasotrachéale","Canule de trachéotomie","Masque facial"],"r":[0,1,2],"e":"Les trois premières sont invasives ; le masque facial est une interface de VNI.","s":9},{"q":"En volume contrôlé, que contrôle le ventilateur et qu'initie le patient ?","o":["Le ventilateur contrôle le volume, le patient initie la pression","Le ventilateur contrôle la pression, le patient initie le volume","Les deux sont contrôlés par le ventilateur","Les deux sont initiés par le patient"],"r":0,"e":"Volume contrôlé : le ventilateur contrôle le volume, le patient initie la pression. Pression contrôlée : l'inverse.","s":9},{"q":"Quelles modalités mixtes sont citées ?","o":["PRVC","IMV, en désuétude","SIMV","CPAP"],"r":[0,1,2],"e":"PRVC, IMV (en désuétude) et SIMV sont les modalités mixtes. La CPAP est une modalité de VNI.","s":9},{"q":"Quelle différence importante distingue modalités contrôlées et assistées quant au stimulus respiratoire ?","o":["En contrôlé, le stimulus peut manquer ; en assisté, le patient initie tout","En contrôlé, le patient initie tous les cycles ; en assisté, la machine les impose","En assisté, le patient n'a jamais de stimulus ; en contrôlé, il en a toujours un","Aucune différence : le stimulus est le même dans les deux modalités ventilatoires"],"r":0,"e":"C'est le point d'attention souligné dans la fiche : en modalité contrôlée le stimulus respiratoire peut être présent ou absent, en modalité assistée le patient initie tous les cycles.","s":9},{"q":"Quelles autres données le ventilateur affiche-t-il ?","o":["Le volume-minute en L/min","Le volume courant inspiratoire","Le volume courant expiratoire","La saturation artérielle"],"r":[0,1,2],"e":"Volume-minute et volumes courants inspiratoire et expiratoire figurent parmi les données affichées.","s":9},{"q":"Comment calcule-t-on la pression de pic en pression assistée ?","o":["PA + PEP","PC + PEP","IPAP − EPAP","FiO₂ × PEP"],"r":0,"e":"Pression de pic = PC + PEP en pression contrôlée, ou PA + PEP en pression assistée.","s":9},{"q":"À quoi l'EPAP équivaut-il sur les appareils de VNI ?","o":["À la PEP","À l'IPAP","À la FiO₂","À la fréquence respiratoire"],"r":0,"e":"Sur les appareils de VNI, la PEP équivaut à l'EPAP, qui évite la ré-inhalation de CO₂.","s":9},{"q":"Quelles sont les indications de la CPAP ?","o":["Le syndrome d'apnées du sommeil","L'œdème aigu du poumon","La BPCO hypercapnique","La fibrose pulmonaire"],"r":[0,1],"e":"CPAP : SAOS et œdème aigu du poumon. BiPAP : BPCO.","s":9},{"q":"Quels effets immédiats la VNI a-t-elle dans les syndromes restrictifs ?","o":["Une diminution des symptômes","Un contrôle de l'hypoventilation","Une diminution du travail respiratoire","Une optimisation de la rééducation"],"r":[0,1],"e":"Restrictifs : diminution des symptômes et contrôle de l'hypoventilation. Obstructifs : diminution des symptômes, du travail respiratoire et optimisation de la rééducation.","s":9},{"q":"Quelles interventions ont fait la preuve de leur efficacité contre le déconditionnement en réanimation ?","o":["Le positionnement corporel","La mobilisation précoce","L'exercice","L'entraînement musculaire","La neurostimulation antalgique"],"r":[0,1,2,3],"e":"Quatre interventions ont des preuves d'efficacité dans le déconditionnement physique.","s":9},{"q":"Sur quoi repose le dosage de l'exercice en unité de soins intensifs ?","o":["La condition clinique et la réponse au traitement","Un protocole standardisé, identique pour tous les patients","La durée du séjour en unité de soins intensifs","L'âge du patient et ses antécédents"],"r":0,"e":"En USI, l'exercice est dosé en fonction de la condition clinique et de la réponse au traitement, le risque de mobiliser étant mis en balance avec ceux de l'immobilité.","s":9},{"q":"Quelles modalités conviennent à un patient coopérant sous ventilation mécanique ?","o":["Mobilisation au bord du lit","Transfert au fauteuil","Entraînement musculaire résisté","Cycloergomètre et marche","Électrostimulation neuromusculaire"],"r":[0,1,2,3],"e":"Ces quatre modalités s'adressent au patient coopérant. Mobilisation passive, cycloergomètre motorisé passif et NMES conviennent au patient non coopérant.","s":9},{"q":"Quel niveau de preuve l'ESICM 2008 attribue-t-elle aux stratégies d'augmentation du volume inspiratoire chez le patient non intubé ?","o":["Niveau B","Niveau C","Niveau D","Niveau A"],"r":0,"e":"Niveau B, comme les stratégies d'augmentation des débits expiratoires et la toux assistée. L'aspiration est de niveau D chez le patient non intubé.","s":9},{"q":"Quelles précautions l'ESICM recommande-t-elle pour l'aspiration chez le patient non intubé ?","o":["Prudence chez les patients sous anticoagulation","Prudence en cas de lésions osseuses ou des tissus mous","Prudence après chirurgie des voies aériennes supérieures","Aspirer systématiquement en première intention"],"r":[0,1,2],"e":"L'aspiration ne s'utilise que lorsque les autres méthodes échouent, avec ces trois précautions.","s":9},{"q":"Que recommande l'ESICM concernant l'hyperinsufflation manuelle ?","o":["Prudence en cas de risque de baro- ou volotraumatisme","Prudence chez le patient instable sur le plan hémodynamique","Ne causer ni hyper- ni hypoventilation","Une application routinière, à chaque soin"],"r":[0,1,2],"e":"Trois recommandations de niveau B. Rien n'est routinier : ni l'aspiration ni l'instillation de sérum physiologique.","s":9},{"q":"Que recommande l'ESICM sur les problèmes émotionnels et de communication ?","o":["Viser aussi bien l'inconfort et l'anxiété que les problèmes physiologiques","Inclure une composante éducative","Considérer le massage pour l'anxiété et la promotion du sommeil","Inclure le toucher thérapeutique dans toutes les interventions","Limiter au maximum les échanges verbaux pour économiser le patient"],"r":[0,1,2,3],"e":"Les quatre recommandations concernent la dimension émotionnelle et communicationnelle du soin en réanimation.","s":9},{"q":"Par quels mécanismes l'hyperinsufflation manuelle agit-elle (Stiller, 2013) ?","o":["En augmentant l'oxygénation","En augmentant la compliance statique et dynamique","En diminuant la résistance des voies aériennes","En prévenant les atélectasies","En augmentant la fréquence respiratoire"],"r":[0,1,2,3],"e":"Ces quatre mécanismes permettent de ré-expandre les zones collabées et de mobiliser les sécrétions périphériques.","s":9},{"q":"Quelle est la cause la plus fréquente d'admission en USI ?","o":["La dysfonction respiratoire","L'insuffisance rénale","Le traumatisme crânien","L'infarctus du myocarde"],"r":0,"e":"Une atteinte des échanges gazeux ou de la pompe ventilatoire peut conduire à la ventilation mécanique.","s":10},{"q":"Quel objectif n'est PAS attribué à la kinésithérapie en USI ?","o":["Poser le diagnostic médical","Éviter la VM ou accélérer le sevrage","Réduire les coûts","Accélérer la sortie de l'USI"],"r":0,"e":"Les objectifs cités sont fonctionnels, préventifs, économiques et de durée de séjour.","s":10},{"q":"Quelle est la caractéristique gazométrique d'une défaillance pulmonaire ?","o":["Une hypoxémie isolée","Une hypoxémie et une hypercapnie","Une hypercapnie isolée","Une alcalose respiratoire"],"r":0,"e":"La défaillance de la pompe ventilatoire associe hypoxémie ET hypercapnie.","s":10},{"q":"Quelle est la caractéristique d'une défaillance de la pompe ventilatoire ?","o":["Hypoxémie et hypercapnie","Hypoxémie isolée","Hypocapnie","Alcalose métabolique"],"r":0,"e":"Elle relève d'une altération du drive respiratoire, d'une dysfonction mécanique ou neuromusculaire.","s":10},{"q":"Quel mécanisme relève de la défaillance pulmonaire ?","o":["L'altération du rapport ventilation/perfusion","L'altération du drive respiratoire, d'origine centrale","La dysfonction neuromusculaire, de la commande au muscle","La dysfonction mécanique de la paroi"],"r":0,"e":"S'y ajoutent la réduction de la ventilation régionale, la baisse de la clairance bronchique et la réduction de la capacité de diffusion.","s":10},{"q":"Quel objectif de la kinésithérapie respiratoire concerne les voies aériennes ?","o":["Réduire la résistance des voies aériennes et les garder libres","Augmenter la FiO₂ délivrée par le ventilateur, jusqu'à la normoxie","Réduire la PEP pour faciliter l'expiration du patient ventilé","Augmenter le volume résiduel en fin d'expiration"],"r":0,"e":"Avec l'amélioration de la ventilation et de la compliance et la réduction du travail respiratoire.","s":10},{"q":"Que doit permettre l'évaluation préalable au traitement ?","o":["Connaître la cause résoluble par la kiné et choisir la stratégie","Poser le diagnostic médical à la place du réanimateur de garde","Décider seul de l'extubation du patient ventilé, sans l'équipe","Régler les paramètres du ventilateur sans l'équipe"],"r":0,"e":"Recommandation de Gosselink et al. (2008), avec un monitorage des fonctions vitales pour garantir efficacité et sécurité.","s":10},{"q":"Que signifie SODR ?","o":["Signes objectifs de difficulté respiratoire","Score d'obstruction des voies respiratoires","Syndrome obstructif à début rapide","Signes d'obstruction et de désaturation respiratoire"],"r":0,"e":"L'inspection porte une attention particulière aux SODR.","s":10},{"q":"Quel élément de l'histoire antérieure est particulièrement pertinent en USI ?","o":["Les épisodes multiples de VM et les sevrages difficiles","Les antécédents chirurgicaux de l'enfance, sous AG","Le groupe sanguin et le rhésus du patient, en ABO","Les allergies alimentaires connues"],"r":0,"e":"On recherche aussi la chronicité, les hospitalisations multiples, les comorbidités et le degré de fonctionnalité antérieur. VM : ventilation mécanique ; AG : anesthésie générale.","s":10},{"q":"Quelle est la température normale et sa variation admise ?","o":["37 °C ± 0,6 °C","36 °C ± 1 °C","38 °C ± 0,5 °C","37,5 °C ± 1 °C"],"r":0,"e":"La fièvre est définie au-dessus de 37,5 °C.","s":10},{"q":"Quel est l'effet d'une augmentation de 0,6 °C sur la consommation d'oxygène ?","o":["Une augmentation de 10 %","Une augmentation de 1 %","Une augmentation de 50 %","Aucun effet"],"r":0,"e":"Avec une augmentation compensatoire de la FC et de la FR.","s":10},{"q":"Quelle est la fréquence cardiaque normale en USI ?","o":["60 à 100 bpm","40 à 60 bpm","100 à 140 bpm","80 à 120 bpm"],"r":0,"e":"La normale générale est 60-80 bpm, élargie à 60-100 en USI, avec une variation admise de ± 20 bpm.","s":10},{"q":"Quelle est la fréquence respiratoire normale en USI ?","o":["Jusqu'à 30 cpm","Jusqu'à 20 cpm","Jusqu'à 40 cpm","Jusqu'à 12 cpm"],"r":0,"e":"La normale générale est 12-20 cpm, élargie jusqu'à 30 cpm en USI.","s":10},{"q":"Quelle est la méthode la plus fiable pour mesurer la FR selon le cours ?","o":["Le ventilateur, et parfois la palpation","Le moniteur, à partir des mouvements du thorax","L'oxymètre de pouls, à partir de la courbe","La ligne artérielle, à partir de la pression"],"r":0,"e":"La lecture sur moniteur, faite à partir des mouvements thoraciques, est très faillible.","s":10},{"q":"Comment repère-t-on une ligne artérielle ?","o":["Par une bande longitudinale rouge","Par une bande bleue","Par une étiquette blanche","Par sa position fémorale uniquement"],"r":0,"e":"Elle est normalement sur l'artère radiale ou fémorale et permet les prélèvements de gazométrie.","s":10},{"q":"Quel est l'avantage de la ligne artérielle ?","o":["Des lectures instantanées de pression et des prélèvements artériels","Une absence totale de risque infectieux, même après plusieurs semaines","Une pose facile, sans geste invasif ni anesthésie locale préalable","Une insensibilité à la mobilisation du membre cathétérisé"],"r":0,"e":"Elle est au contraire très vulnérable à la mobilisation.","s":10},{"q":"Quelle SpO₂ traduit une désaturation importante ?","o":["Inférieure à 90 %","Inférieure à 95 %","Inférieure à 98 %","Inférieure à 85 % seulement"],"r":0,"e":"La valeur normale est de 95 à 100 %.","s":10},{"q":"Que mesure la SpO₂ ?","o":["Le rapport entre oxyhémoglobine et hémoglobine totale","La pression partielle en oxygène dans le sang artériel","Le contenu artériel en oxygène, en mL par litre de sang","Le débit d'oxygène délivré aux tissus, en mL par minute"],"r":0,"e":"L'oxymétrie de pouls est non invasive, rapide, facile et fiable, et mesure aussi la FC.","s":10},{"q":"Quelle est la valeur normale de la pression intracrânienne ?","o":["0 à 15 mmHg","15 à 30 mmHg","30 à 50 mmHg","Moins de 0 mmHg"],"r":0,"e":"Elle est monitorée chez les patients neuro-critiques.","s":10},{"q":"À partir de quelle fréquence une tachypnée devient-elle préoccupante ?","o":["Plus de 40 cpm","Plus de 20 cpm","Plus de 30 cpm","Plus de 25 cpm"],"r":0,"e":"L'eupnée est définie entre 12 et 30 cpm dans ce contexte.","s":10},{"q":"Qu'est-ce que la respiration de Cheyne-Stokes ?","o":["Des pauses entrecoupées de périodes de polypnée","Une respiration régulière, rapide et superficielle","Une respiration lente et profonde, à rythme régulier","Une apnée prolongée de plus de 20 secondes, sans reprise"],"r":0,"e":"C'est un schéma ventilatoire particulier à reconnaître.","s":10},{"q":"Quelle est la cause classique d'une bradypnée en USI ?","o":["Une dépression centrale ou une sédation","Une fièvre élevée, au-delà de 39 °C","Une douleur aiguë, mal contrôlée","Une hypoxémie sévère, sous 60 mmHg"],"r":0,"e":"La bradypnée correspond à une FR diminuée.","s":10},{"q":"Quel score de Glasgow définit le coma ?","o":["Inférieur à 7","Inférieur à 12","Inférieur à 15","Inférieur à 3"],"r":0,"e":"C'est le seuil retenu dans le cours.","s":10},{"q":"Que décrit le niveau 2 de l'échelle de Ramsay ?","o":["Éveillé, tranquille et coopérant","Éveillé, agité et anxieux","Endormi, réponse vive aux stimuli","Endormi, sans réponse"],"r":0,"e":"Le niveau 1 est agité et anxieux, le 3 répond seulement aux ordres.","s":10},{"q":"Que décrit le niveau 6 de l'échelle de Ramsay ?","o":["Endormi, sans réponse aux stimuli externes","Endormi, avec une réponse lente aux stimuli","Éveillé, coopérant et orienté","Éveillé, agité et anxieux"],"r":0,"e":"L'échelle va de 1 (éveillé agité) à 6 (endormi sans réponse).","s":10},{"q":"Combien de questions comporte le S5Q ?","o":["5","3","7","10"],"r":0,"e":"Il évalue la coopération : ouvrir/fermer les yeux, regarder, ouvrir la bouche et tirer la langue, hocher la tête, froncer les sourcils après un compte.","s":10},{"q":"Quelle proportion de patients gardent des contractures après un séjour prolongé en USI ?","o":["Plus de 30 %","Moins de 5 %","Environ 70 %","Environ 10 %"],"r":0,"e":"Elles concernent les grandes articulations : épaule et hanche.","s":10},{"q":"Quelles causes de limitation articulaire faut-il évaluer ?","o":["Tonus, allongement, capsule, peau et œdème","Le tonus seul, coté à l'échelle d'Ashworth","La capsule seule, testée en fin d'amplitude","La douleur seule, cotée à l'échelle visuelle analogique"],"r":0,"e":"Ces cinq causes doivent être évaluées fréquemment.","s":10},{"q":"Que mesurent la PIM et la PEM ?","o":["La force musculaire respiratoire","La pression intracrânienne","La pression artérielle moyenne","Le volume courant"],"r":0,"e":"Elles complètent les tests musculaires fonctionnel et analytique.","s":10},{"q":"Que traduit un score de Glasgow bas dans la décision de ventilation mécanique ?","o":["Une incapacité à protéger les voies aériennes","Une défaillance de la capacité ventilatoire","Une défaillance de la capacité d'oxygénation","Une instabilité hémodynamique avec un état de choc"],"r":0,"e":"PaCO₂ élevée = défaillance ventilatoire ; PaO₂ basse = défaillance d'oxygénation ; Glasgow bas = défaut de protection des voies aériennes.","s":10},{"q":"Quels objectifs la kinésithérapie poursuit-elle en unité de soins intensifs ?","o":["Résoudre les problèmes et prévenir","Éviter la ventilation, accélérer le sevrage","Diminuer la mortalité et la morbidité","Accélérer la sortie, réduire les coûts","Poser le diagnostic médical précis"],"r":[0,1,2,3],"e":"Les six objectifs se regroupent en ces quatre familles.","s":10},{"q":"Quels sont les principaux problèmes rencontrés en situation critique ?","o":["Déconditionnement et faiblesse musculaire","Limitations articulaires","Rétention de sécrétions et atélectasies","Éviter l'intubation et l'échec du sevrage","Hypertension artérielle chronique"],"r":[0,1,2,3],"e":"Ces problèmes guident le raisonnement clinique, orienté avant tout par les atteintes de la fonction.","s":10},{"q":"Quels mécanismes relèvent de la défaillance de la pompe ventilatoire (Gosselink, 2008) ?","o":["Le drive respiratoire altéré","La dysfonction mécanique","La dysfonction neuromusculaire","Le rapport V/Q altéré"],"r":[0,1,2],"e":"Drive, mécanique et neuromusculaire pour la pompe. Le rapport ventilation/perfusion, la clairance bronchique et la capacité de diffusion relèvent de la défaillance pulmonaire.","s":10},{"q":"Quels objectifs poursuit la kinésithérapie respiratoire en USI ?","o":["Améliorer la ventilation","Gagner en compliance","Réduire le travail respiratoire","Garder les voies libres","Augmenter la FiO₂ délivrée"],"r":[0,1,2,3],"e":"Ces objectifs visent à éviter ou réduire atélectasies et pneumonie, intubation et échec du sevrage. La ventilation est régionale ou globale ; on réduit aussi la résistance des voies aériennes.","s":10},{"q":"Quels sont les six temps de l'évaluation du patient critique ?","o":["Examen subjectif : dossier, équipe, famille","Observation : aspect, signes vitaux","Conscience et coopération","Mobilité et force musculaire","Palpation et auscultation","Gazométrie artérielle seule"],"r":[0,1,2,3,4],"e":"Les six temps structurent l'évaluation en réanimation.","s":10},{"q":"Quels éléments de l'histoire clinique antérieure sont particulièrement pertinents en USI ?","o":["Une condition chronique","Des hospitalisations multiples","Des épisodes multiples de ventilation mécanique","Des sevrages difficiles","Le niveau d'études du patient"],"r":[0,1,2,3],"e":"Ces quatre éléments, avec les comorbidités et le degré de fonctionnalité antérieur, orientent le pronostic.","s":10},{"q":"Que faut-il observer dans l'aspect général du patient critique ?","o":["L'intervention : ventilation, seringues","L'invasivité : ligne artérielle, drains","Les signes vitaux : FC, PA, FR, SpO₂","La gazométrie : pH, PaO₂, PaCO₂"],"r":[0,1,2],"e":"Degré d'intervention, degré d'invasivité, signes vitaux et inspection avec attention aux SODR.","s":10},{"q":"À partir de quelle température parle-t-on de fièvre ?","o":["Au-dessus de 37,5 °C","Au-dessus de 37 °C","Au-dessus de 38,5 °C","Au-dessus de 39 °C"],"r":0,"e":"La pyrexie est définie au-dessus de 37,5 °C, avec augmentation du métabolisme.","s":10},{"q":"Quelles conséquences une augmentation de 0,6 °C entraîne-t-elle ?","o":["10 % de consommation d'oxygène en plus","Une hausse compensatoire de la FC","Une hausse compensatoire de la FR","Une baisse de la pression artérielle"],"r":[0,1,2],"e":"Chaque hausse de 0,6 °C majore de 10 % la consommation d'oxygène, avec augmentation compensatoire de la FC et de la FR.","s":10},{"q":"Quelles méthodes permettent de lire la fréquence cardiaque en USI ?","o":["Le moniteur","Le tracé ECG","L'oxymètre","La ligne artérielle","Le brassard à tension"],"r":[0,1,2,3],"e":"Quatre sources de lecture de la FC, dont la valeur normale est de 60 à 80 bpm (60 à 100 en USI).","s":10},{"q":"Pourquoi la lecture de la FR sur le moniteur est-elle jugée faillible ?","o":["Elle repose sur la détection des mouvements du thorax","Le capteur est souvent mal placé sur le doigt du patient","Elle dépend directement de la valeur de la SpO₂","Elle ne s'affiche pas en continu sur l'écran"],"r":0,"e":"Le moniteur lit les mouvements thoraciques, ce qui est très faillible. Le ventilateur est fiable, et la palpation est parfois la méthode la plus fiable.","s":10},{"q":"Où se place une ligne artérielle ?","o":["Sur l'artère radiale","Sur l'artère fémorale","Sur l'artère carotide","Sur la veine jugulaire"],"r":[0,1],"e":"La ligne artérielle, méthode invasive la plus courante en USI, se place sur l'artère radiale ou fémorale. Elle est signalée par une bande longitudinale rouge.","s":10},{"q":"Quelles sont les qualités de l'oxymétrie de pouls ?","o":["Non invasive","Rapide et facile","Fiable","Mesure SpO₂ et FC","Mesure la PaO₂"],"r":[0,1,2,3],"e":"L'oxymétrie de pouls mesure le rapport entre oxyhémoglobine et hémoglobine totale, ainsi que la FC.","s":10},{"q":"Comment définit-on l'eupnée ?","o":["Une FR entre 12 et 30 cpm","Une FR au-delà de 30 cpm, superficielle","Une FR sous 12 cpm, profonde","Une FR à 0 cpm, abolie"],"r":0,"e":"Eupnée : 12 à 30 cpm. Tachypnée : augmentée mais superficielle. Bradypnée : diminuée. Apnée : abolie.","s":10},{"q":"Qu'est-ce que la polypnée et quand devient-elle préoccupante ?","o":["Une FR augmentée, préoccupante seulement au-delà de 40 cpm","Une FR diminuée, préoccupante seulement sous 10 cpm","Une FR abolie, préoccupante dès les premières secondes","Une FR irrégulière, préoccupante dès qu'elle varie de plus de 5 cpm"],"r":0,"e":"Comme la tachypnée, la polypnée n'est préoccupante qu'au-delà de 40 cpm.","s":10},{"q":"Que décrit le niveau 4 de l'échelle de Ramsay ?","o":["Endormi, avec une réponse vive aux stimuli","Endormi, avec une réponse lente aux stimuli","Éveillé, ne répondant qu'aux ordres simples","Éveillé, tranquille, coopérant et orienté dans le temps"],"r":0,"e":"1 agité et anxieux, 2 tranquille et coopérant, 3 ne répond qu'aux ordres, 4 endormi avec réponse vive, 5 endormi avec réponse lente, 6 endormi sans réponse.","s":10},{"q":"Quelles consignes composent le S5Q ?","o":["Ouvrez et fermez les yeux","Regardez-moi","Ouvrez la bouche, tirez la langue","Hochez la tête : oui, non","Froncez les sourcils à 5","Comptez à rebours depuis 100"],"r":[0,1,2,3,4],"e":"Les cinq questions standardisées évaluent la coopération du patient.","s":10},{"q":"Quels domaines le Nottingham Health Profile explore-t-il ?","o":["Douleur et énergie","Mobilité physique","Sommeil","Isolement et émotions","Rôle émotionnel"],"r":[0,1,2,3],"e":"Six domaines pour le Nottingham Health Profile, à distinguer des huit domaines du SF-36.","s":10},{"q":"Quels questionnaires évaluent l'impact du séjour en USI chez le patient respiratoire chronique ?","o":["Le Chronic Respiratory Disease Questionnaire","Le St. George's Respiratory Questionnaire","Le SF-36, questionnaire générique en 8 domaines","Le Nottingham Health Profile, en 6 domaines"],"r":[0,1],"e":"Ces deux questionnaires s'adressent spécifiquement aux patients atteints de pathologie respiratoire chronique.","s":10},{"q":"Quelles questions l'auscultation pulmonaire doit-elle permettre de trancher ?","o":["Y a-t-il des bruits adventices ?","L'obstruction est-elle installée ou seulement à risque ?","Les bruits respiratoires normaux sont-ils altérés ?","Y a-t-il restriction par immobilité, manque de stimulus ou hypoventilation ?","Quelle est la valeur de la capacité vitale forcée ?"],"r":[0,1,2,3],"e":"L'auscultation est à la fois une évaluation et un monitorage du traitement, guidée par ces quatre questions.","s":10},{"q":"Combien de phases compte le développement pulmonaire ?","o":["5","3","4","7"],"r":0,"e":"Embryonnaire, pseudoglandulaire, canaliculaire, sacculaire et alvéolaire.","s":11},{"q":"À partir de quelle structure se développe le tractus respiratoire ?","o":["L'intestin primitif","Le tube neural","Le mésoderme para-axial","La crête neurale"],"r":0,"e":"C'est un événement de la phase embryonnaire (~0-5 semaines).","s":11},{"q":"À la fin de quelle phase l'arbre bronchique est-il complètement formé ?","o":["La phase pseudoglandulaire","La phase canaliculaire","La phase sacculaire","La phase alvéolaire"],"r":0,"e":"À la fin de la phase pseudoglandulaire (~5-16 semaines), avec 16 générations jusqu'aux conduits alvéolaires.","s":11},{"q":"Quand apparaissent les pneumocytes de type I et II ?","o":["À la phase canaliculaire","À la phase embryonnaire","À la phase sacculaire","À la phase alvéolaire"],"r":0,"e":"La phase canaliculaire (~17-27 semaines) permet aussi les premiers échanges gazeux.","s":11},{"q":"Quand débute la synthèse du surfactant alvéolaire ?","o":["À la phase sacculaire, vers 28-36 semaines","À la phase canaliculaire, vers 17-27 semaines","À la naissance, avec la première respiration","À la phase pseudoglandulaire, vers 5-17 semaines"],"r":0,"e":"Elle est assurée par les pneumocytes de type II.","s":11},{"q":"Combien d'alvéoles a un nouveau-né ?","o":["17 à 71 millions","200 à 600 millions","1 à 5 millions","100 millions exactement"],"r":0,"e":"L'adulte en a 200 à 600 millions : 85 % des alvéoles se forment après la naissance.","s":11},{"q":"Quel pourcentage des alvéoles se forme après la naissance ?","o":["85 %","50 %","20 %","95 %"],"r":0,"e":"Entre le 4ᵉ et le 21ᵉ jour, puis au cours de la croissance.","s":11},{"q":"Vers quel âge les alvéoles cessent-elles de se multiplier selon l'hypothèse prévalente ?","o":["2-3 ans","6 mois","6 ans","10 ans"],"r":0,"e":"Elles passent ensuite par un processus d'augmentation de volume et de surface.","s":11},{"q":"Quelle conséquence a la trompe d'Eustache courte et horizontalisée du nourrisson ?","o":["Le mucus progresse vers l'oreille moyenne, avec un risque d'otite","Une hypoventilation alvéolaire, par obstruction nasale permanente et prolongée","Une augmentation de la compliance thoracique, par l'horizontalisation","Un bronchospasme réflexe, par irritation du rhinopharynx"],"r":0,"e":"Toute obstruction du rhinopharynx peut causer des altérations de pression et/ou une otite.","s":11},{"q":"Pourquoi la ventilation du nourrisson est-elle essentiellement naso-pharyngée ?","o":["La cavité buccale est presque entièrement occupée par la langue","La bouche est fermée en permanence par un réflexe archaïque","Le larynx est situé très bas, au niveau de C6-C7","L'épiglotte est rigide et ferme l'accès à la bouche"],"r":0,"e":"Les végétations adénoïdes, amygdales et la langue sont volumineuses.","s":11},{"q":"Quelle est la forme de l'épiglotte du nourrisson ?","o":["En oméga, molle, à 45° de la paroi pharyngée","Plate et rigide, à 20° de la paroi pharyngée","Triangulaire et fine, verticale, dans l'axe de la trachée","Circulaire et épaisse, à 90° de la paroi"],"r":0,"e":"Chez l'adulte, l'angle est de 20°.","s":11},{"q":"Où se situe le larynx du nouveau-né ?","o":["En position haute, en regard de C3-C4","En position basse, en regard de C6-C7","En position très haute, en regard de C1-C2","En position thoracique, en regard de T1"],"r":0,"e":"Cette position haute participe à la possibilité de respirer et déglutir en même temps.","s":11},{"q":"Jusqu'à quel âge le nourrisson respire-t-il et déglutit-il en même temps ?","o":["3 à 4 mois","6 mois","1 an","2 ans"],"r":0,"e":"C'est lié à la position haute du larynx et à la relation entre base de langue et épiglotte.","s":11},{"q":"Quelle est la capacité pulmonaire totale à la naissance ?","o":["15 mL","150 mL","500 mL","50 mL"],"r":0,"e":"Elle est de 500 mL chez l'adulte.","s":11},{"q":"Jusqu'à quel âge la résistance des petites voies aériennes est-elle élevée ?","o":["Moins de 5 ans","Moins de 2 ans","Moins de 10 ans","Moins de 6 mois"],"r":0,"e":"C'est lié au faible calibre des voies aériennes inférieures.","s":11},{"q":"Quel élément prédomine dans l'obstruction bronchique du nourrisson ?","o":["L'hypersécrétion","Le bronchospasme","La fibrose","L'emphysème"],"r":0,"e":"Le muscle lisse est proportionnellement réduit et les glandes muqueuses plus grandes et nombreuses, donc le spasme a moins d'importance que chez l'adulte.","s":11},{"q":"Quelle est la forme de la cage thoracique du nourrisson ?","o":["Circulaire, avec des arcs costaux horizontaux","Ovale, comme chez l'adulte, avec des côtes obliques","Aplatie d'avant en arrière, avec des côtes très obliques vers le bas","Triangulaire, avec un sternum saillant en avant"],"r":0,"e":"Cela réduit l'avantage mécanique des intercostaux et laisse le thorax en position inspiratoire.","s":11},{"q":"Quelle conséquence a la compliance élevée de la cage thoracique du nourrisson ?","o":["Peu de résistance aux déformations, collapsus facile, tirage sous-costal","Une meilleure réserve inspiratoire, grâce à la souplesse du thorax","Une plus grande force des intercostaux, mieux orientés","Une meilleure ventilation collatérale, par les pores de Kohn ouverts"],"r":0,"e":"Le thorax en position inspiratoire implique aussi une moindre réserve inspiratoire.","s":11},{"q":"De quel type de fibres sont composés les muscles respiratoires du nouveau-né ?","o":["De fibres de type II surtout, sensibles à la fatigue","De fibres de type I surtout, résistantes à la fatigue","De fibres I et II à parts égales, comme chez l'adulte","De fibres cardiaques, à contraction rythmique"],"r":0,"e":"Elles ont une moindre réserve de glycogène et de graisse, d'où la fatigabilité, surtout chez le prématuré.","s":11},{"q":"Quelle est la position du diaphragme du nourrisson ?","o":["Plus horizontale et aplatie que chez l'adulte","Plus verticale, en dôme haut dans le thorax","Identique à celle de l'adulte, dès la naissance","En dôme très accentué, avec une grande course"],"r":0,"e":"Cela réduit son avantage mécanique et limite sa capacité contractile.","s":11},{"q":"À quoi sert la ventilation collatérale ?","o":["Éviter l'atélectasie quand la voie principale d'une unité est obstruée","Augmenter le volume courant de chaque inspiration, au repos","Humidifier l'air inspiré avant l'arrivée dans les alvéoles distales","Filtrer les particules fines qui atteignent les bronchioles"],"r":0,"e":"C'est un mécanisme de protection des unités périphériques.","s":11},{"q":"Pourquoi la ventilation collatérale est-elle quasi inexistante avant 6 ans ?","o":["Par absence de pores de Köhn","Par excès de muscle lisse","Par immaturité du surfactant","Par étroitesse de la trachée"],"r":0,"e":"D'où une plus grande probabilité de micro-atélectasies périphériques voire d'atélectasies lobulaires.","s":11},{"q":"Quel facteur prédispose l'enfant à la désaturation ?","o":["Une consommation d'O₂ élevée, liée au métabolisme de croissance","Une fréquence respiratoire plus faible que chez l'adulte","Une compliance thoracique réduite, par un thorax rigide","Une ventilation collatérale très efficace, dès la naissance"],"r":0,"e":"S'y ajoutent la résistance des voies aériennes, l'immaturité du contrôle respiratoire et du réflexe de toux, et l'efficience réduite des muscles.","s":11},{"q":"Qu'est-ce qui diminue le drainage muco-ciliaire ?","o":["Le froid et le sommeil","Le mouvement","L'hydratation des voies aériennes","Les inspirations à grand volume"],"r":0,"e":"Le drainage peut au contraire être stimulé par le mouvement et l'hydratation.","s":11},{"q":"Quel effet ont les inspirations à grand volume sur le transport muco-ciliaire ?","o":["Elles stimulent la production d'ATP, qui régule le transport","Elles épuisent l'ATP des cils, ce qui ralentit leur battement","Elles n'ont aucun effet sur le transport muco-ciliaire","Elles augmentent la viscosité du mucus, en l'asséchant"],"r":0,"e":"C'est un des fondements physiologiques des techniques inspiratoires lentes. ATP : adénosine triphosphate.","s":11},{"q":"Selon Postiaux (2004), qu'arrive-t-il à la viscoélasticité du mucus ?","o":["Elle diminue quand l'amplitude et la durée de la sollicitation augmentent","Elle augmente quand l'amplitude et la durée de la sollicitation augmentent","Elle reste constante, quelle que soit la sollicitation","Elle dépend uniquement de la température du mucus"],"r":0,"e":"Sollicitations citées : battement ciliaire, secousses de la toux, mouvements vibratoires (pleurs et rire).","s":11},{"q":"Quel mécanisme les pleurs reproduisent-ils ?","o":["Un mécanisme de PEP, par adduction des cordes vocales","Un mécanisme de toux forcée, à glotte fermée","Une hyperinsufflation manuelle, réalisée par le soignant","Une ELTGOL, expiration lente à glotte ouverte"],"r":0,"e":"L'augmentation de pression endobronchique s'apparente à une pression expiratoire positive. PEP : pression expiratoire positive.","s":11},{"q":"Qu'est-ce que l'effet thixotropique ?","o":["La viscosité d'un fluide baisse quand on lui applique un cisaillement","La viscosité d'un fluide augmente quand la température monte","Le mucus se solidifie quand on lui applique une pression","Le fluide devient plus dense au repos, puis se liquéfie quand on le chauffe"],"r":0,"e":"Le son continu « AAAAA » émis pendant les pleurs peut favoriser cet effet sur le mucus.","s":11},{"q":"Quelle est la position de l'école française sur les sécrétions et la pesanteur ?","o":["Elles sont mobilisées contre la pesanteur et non grâce à elle","Elles sont mobilisées grâce à la pesanteur, par le drainage postural de chaque segment","La pesanteur n'a aucun rôle dans la mobilisation des sécrétions","Le drainage postural reste indispensable avant toute technique"],"r":0,"e":"C'est une rupture explicite avec l'école anglo-saxonne, qui privilégiait le drainage postural.","s":11},{"q":"Que conclut la revue Cochrane 2023 sur les techniques expiratoires forcées dans la bronchiolite grave ?","o":["Elles n'améliorent pas l'état de santé et peuvent nuire gravement","Elles améliorent nettement la gravité, sur des données de haute qualité","Elles sont le traitement de référence de la bronchiolite grave à l'hôpital","Les données sont insuffisantes pour conclure dans un sens ou dans l'autre"],"r":0,"e":"Ce sont des données de haute qualité. La technique passive d'expiration lente, elle, montre une amélioration légère à modérée sur données de faible qualité.","s":11},{"q":"Quels dérivés embryonnaires participent au développement pulmonaire ?","o":["Ectodermiques : épiderme et nerfs","Mésodermiques : cartilage, muscle, plèvre","Endodermiques : épithélium des voies basses","Neuro-ectodermiques : système nerveux seul"],"r":[0,1,2],"e":"Les trois feuillets participent, le tractus respiratoire se développant à partir de l'intestin primitif.","s":11},{"q":"Combien de générations compte l'arbre bronchique à la fin de la phase pseudoglandulaire ?","o":["16","10","23","5"],"r":0,"e":"À la fin de la phase pseudoglandulaire (~5-16 semaines), l'arbre bronchique est complètement formé sur 16 générations, jusqu'aux conduits alvéolaires.","s":11},{"q":"Que se passe-t-il pendant la phase canaliculaire ?","o":["Pneumocytes de type I et II","Bronchioles et acinus","Alvéole primitive, échanges possibles","Cartilage bronchique au nombre adulte","Synthèse du surfactant, en fin de phase"],"r":[0,1,2,3],"e":"La phase canaliculaire (~17-27 semaines) comprend ces quatre événements. Le surfactant apparaît à la phase sacculaire.","s":11},{"q":"Que caractérise la phase sacculaire ?","o":["Les voies aériennes périphériques forment des saccules","Début de la synthèse du surfactant par les pneumocytes de type II","Grand développement de l'acinus","Maturation de la vascularisation et de l'innervation"],"r":[0,1,2],"e":"Phase sacculaire (~28-36 semaines). La maturation de la vascularisation et de l'innervation appartient à la phase alvéolaire.","s":11},{"q":"Entre quels jours se forme l'essentiel des alvéoles après la naissance ?","o":["Entre le 4ᵉ et le 21ᵉ jour","Entre le 1ᵉʳ et le 7ᵉ jour","Entre le 30ᵉ et le 90ᵉ jour","Entre 6 et 12 mois"],"r":0,"e":"85 % des alvéoles se forment après la naissance, entre le 4ᵉ et le 21ᵉ jour.","s":11},{"q":"Que caractérise la première phase de la croissance pulmonaire post-natale ?","o":["Jusqu'à 18 mois : alvéolisation et maturation microvasculaire","De 18 mois à la fin de la croissance : croissance proportionnelle","À la naissance : arrêt complet et définitif de toute alvéolisation","Avant la naissance : formation de tout l'arbre bronchique"],"r":0,"e":"Première phase : naissance-18 mois, alvéolisation et maturation microvasculaire. Deuxième phase : croissance proportionnelle jusqu'à la fin de la croissance staturo-pondérale. Les compartiments du parenchyme se modifient en quantité.","s":11},{"q":"Quelles conséquences a l'anatomie de la cavité orale du nourrisson ?","o":["Une ventilation surtout naso-pharyngée","Un risque d'obstruction des voies hautes","Une déglutition impossible en respirant","Une hypersécrétion salivaire permanente"],"r":[0,1],"e":"Végétations, amygdales et langue volumineuses, cavité buccale presque totalement occupée par la langue et base de la langue proche de l'épiglotte expliquent ces deux conséquences.","s":11},{"q":"Quel est l'angle de l'épiglotte par rapport à la paroi du pharynx chez le nourrisson et chez l'adulte ?","o":["45° chez le nourrisson, 20° chez l'adulte","20° chez le nourrisson, 45° chez l'adulte","90° chez les deux","Il n'y a pas de différence"],"r":0,"e":"L'épiglotte du nourrisson, en forme d'oméga et molle, fait 45° avec la paroi du pharynx, contre 20° chez l'adulte.","s":11},{"q":"Quelle conséquence pratique découle de la trachée étroite, courte et molle du nourrisson ?","o":["Une toux réflexe par les récepteurs trachéaux","Des voies aériennes supérieures à garder libres","Une ventilation collatérale qui augmente","Une compliance thoracique qui diminue"],"r":[0,1],"e":"Ces deux conséquences découlent des particularités du larynx et de la trachée du nourrisson.","s":11},{"q":"Pourquoi le bronchospasme joue-t-il un rôle mineur dans l'obstruction du nourrisson ?","o":["Le muscle lisse est réduit dans les voies distales","Les glandes muqueuses sont plus grandes et plus nombreuses","Le cartilage bronchique est absent avant 2 ans","La ventilation collatérale compense l'obstruction"],"r":[0,1],"e":"Peu de muscle lisse distal et des glandes muqueuses proportionnellement plus développées font de l'hypersécrétion l'élément dominant de l'obstruction.","s":11},{"q":"Quelles conséquences mécaniques a la cage thoracique du nourrisson ?","o":["Des intercostaux moins efficaces","Un thorax inspiratoire, peu de réserve","Une compliance élevée, avec tirage","Une force diaphragmatique accrue"],"r":[0,1,2],"e":"Forme circulaire et arcs costaux horizontalisés expliquent ces trois conséquences.","s":11},{"q":"Pourquoi les muscles respiratoires du nouveau-né fatiguent-ils rapidement ?","o":["Des fibres de type II surtout","Peu de réserves de glycogène et de graisse","Un diaphragme horizontal et aplati","Des intercostaux peu développés","Des fibres de type I surtout"],"r":[0,1,2,3],"e":"Ces quatre éléments expliquent la fatigue musculaire majorée quand la FR augmente, en particulier chez le prématuré.","s":11},{"q":"Quels facteurs prédisposent l'enfant à la désaturation et à l'insuffisance respiratoire ?","o":["Une plus grande résistance des voies aériennes supérieures et inférieures","Une consommation d'O₂ accrue par un taux métabolique plus élevé","Une fréquence respiratoire plus élevée avec un volume courant pratiquement stable","Une immaturité du contrôle respiratoire et du réflexe de toux","Une plus grande compliance de la cage thoracique","Une capacité de diffusion alvéolaire supérieure à celle de l'adulte"],"r":[0,1,2,3,4],"e":"Sept facteurs sont cités, dont la diminution de la ventilation collatérale et l'efficience réduite des muscles respiratoires.","s":11},{"q":"Comment se forme l'expectoration selon le mécanisme muco-ciliaire ?","o":["La sécrétion bronchique se mêle aux sécrétions orales et nasales","Le mucus s'associe aux fluides, aux débris et aux cellules desquamées","Elle provient uniquement des alvéoles, sous forme de liquide","Elle provient uniquement du nez, par écoulement postérieur"],"r":[0,1],"e":"Le mucus + fluides + débris + cellules de desquamation forment la sécrétion bronchique, qui mélangée aux sécrétions non bronchiques donne l'expectoration.","s":11},{"q":"Qu'est-ce qui stimule le drainage muco-ciliaire ?","o":["Le mouvement","L'hydratation","Le froid","Le sommeil"],"r":[0,1],"e":"Mouvement et hydratation stimulent le drainage ; le froid et le sommeil le diminuent.","s":11},{"q":"Quelles sollicitations diminuent la viscoélasticité du mucus selon Postiaux (2004) ?","o":["Le battement ciliaire","Les secousses de la toux","Les vibrations des pleurs et du rire","L'immobilité prolongée au lit"],"r":[0,1,2],"e":"Les propriétés de viscoélasticité diminuent avec l'augmentation de l'amplitude et de la durée de la sollicitation : battement ciliaire, toux, pleurs et rire.","s":11},{"q":"Par quel mécanisme les pleurs augmentent-ils la pression endobronchique ?","o":["Par l'adduction des cordes vocales à l'expiration","Par une inspiration profonde, avant le cri","Par une contraction abdominale isolée, sans les cordes vocales","Par une fermeture de la glotte à l'inspiration"],"r":0,"e":"Pendant la vocalisation, l'adduction des cordes vocales en phase expiratoire augmente la pression endobronchique, à la manière d'une PEP.","s":11},{"q":"Quels effets combinés les pleurs produisent-ils sur le mucus ?","o":["Un effet thixotropique","Une augmentation de pression","Une vibration","Un mucus mieux décollé et éliminé","Une bronchoconstriction réflexe"],"r":[0,1,2,3],"e":"Effet thixotropique, augmentation de pression et vibration se combinent en un effet positif sur le décollement, la diminution de viscosité et la clairance. Le rire semble avoir un effet semblable.","s":11},{"q":"Que permet l'association entre auscultation et mécanique ventilatoire selon l'école française ?","o":["Un diagnostic des syndromes obstructifs","Le lieu, le type et la nature de l'obstruction","Le choix de techniques adaptées","La mesure de la capacité vitale"],"r":[0,1,2],"e":"Ce concept « par niveaux » de l'obstruction broncho-pulmonaire permet de poser un diagnostic ventilatoire puis de choisir les techniques.","s":11},{"q":"Quels sont les points-clés de l'école française ?","o":["Les sécrétions vont contre la pesanteur","Les expirations lentes agissent sur les petites bronches","Les inspirations lentes épurent la périphérie","Le drainage postural est la référence"],"r":[0,1,2],"e":"Les trois premiers points s'opposent précisément à l'approche anglo-saxonne fondée sur le drainage postural, la percussion et les expirations forcées.","s":11}]};
